export interface BusinessCardData {
  id: string;
  name: string;
  title?: string;
  company?: string;
  email?: string;
  phone?: string;
  website?: string;
  address?: string;
  notes?: string;
  scannedAt: number;
  imageUrl?: string;
}

export type ScanStatus = 'idle' | 'scanning' | 'processing' | 'success' | 'error';

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractCardInfo = async (base64Image: string): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: "Extract information from this business card image. Return the information in structured JSON format. If a field is not present, leave it as an empty string.",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING, description: "Full name of the person" },
          title: { type: Type.STRING, description: "Job title" },
          company: { type: Type.STRING, description: "Company name" },
          email: { type: Type.STRING, description: "Email address" },
          phone: { type: Type.STRING, description: "Phone number" },
          website: { type: Type.STRING, description: "Website URL" },
          address: { type: Type.STRING, description: "Mailing or office address" },
          notes: { type: Type.STRING, description: "Any other details found" },
        },
        required: ["name"],
      },
    },
  });

  try {
    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text);
  } catch (error) {
    console.error("Error parsing Gemini response:", error);
    throw error;
  }
};

import React, { useRef, useState, useCallback, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  const startCamera = useCallback(async () => {
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' },
        audio: false,
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
    } catch (err) {
      setError('Cannot access camera. Please ensure permissions are granted.');
      console.error(err);
    }
  }, []);

  useEffect(() => {
    startCamera();
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [startCamera]);

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');

      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        context.drawImage(video, 0, 0, canvas.width, canvas.height);

        const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="fixed inset-0 bg-black z-50 flex flex-col items-center justify-between p-4">
      <div className="w-full flex justify-between items-center text-white mb-4">
        <h2 className="text-xl font-semibold">Align Business Card</h2>
        <button 
          onClick={onClose}
          className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition-colors"
        >
          <i className="fa-solid fa-xmark text-lg"></i>
        </button>
      </div>

      <div className="relative flex-1 w-full max-w-lg overflow-hidden rounded-2xl border-2 border-white/30 bg-slate-900 flex items-center justify-center">
        {error ? (
          <div className="text-white text-center p-6">
            <i className="fa-solid fa-triangle-exclamation text-4xl mb-4 text-yellow-400"></i>
            <p>{error}</p>
          </div>
        ) : (
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            className="w-full h-full object-cover"
          />
        )}

        {/* Scanning Overlay */}
        <div className="absolute inset-0 border-2 border-white/20 pointer-events-none">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[85%] aspect-[1.6/1] border-2 border-indigo-500 rounded-lg shadow-[0_0_0_100vmax_rgba(0,0,0,0.5)]">
             <div className="absolute inset-0 bg-gradient-to-b from-indigo-500/10 to-transparent animate-pulse"></div>
          </div>
        </div>
      </div>

      <div className="w-full max-w-lg py-8 flex justify-center items-center gap-8">
        <button 
          onClick={capturePhoto}
          className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-4 border-indigo-500 active:scale-90 transition-transform shadow-lg shadow-white/10"
        >
          <div className="w-16 h-16 bg-white border-2 border-slate-200 rounded-full"></div>
        </button>
      </div>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default CameraScanner;

