import React, { useState, useEffect, useCallback } from 'react';
import { BusinessCardData, ScanStatus } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import BusinessCard from './components/BusinessCard';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [showScanner, setShowScanner] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Load cards from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('smart_cards');
    if (saved) {
      try {
        setCards(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  // Save cards to localStorage when updated
  useEffect(() => {
    localStorage.setItem('smart_cards', JSON.stringify(cards));
  }, [cards]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setStatus('processing');
    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = (e.target?.result as string).split(',')[1];
      await processImage(base64);
    };
    reader.onerror = () => {
      setErrorMsg('Failed to read file');
      setStatus('error');
    };
    reader.readAsDataURL(file);
  };

  const onCapture = async (base64: string) => {
    setShowScanner(false);
    setStatus('processing');
    await processImage(base64);
  };

  const processImage = async (base64: string) => {
    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setStatus('success');
      setTimeout(() => setStatus('idle'), 3000);
    } catch (err) {
      setErrorMsg('Failed to analyze the card. Please try again.');
      setStatus('error');
      console.error(err);
    }
  };

  const deleteCard = (id: string) => {
    if (window.confirm('Are you sure you want to delete this contact?')) {
      setCards(prev => prev.filter(c => c.id !== id));
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white/80 backdrop-blur-md border-b border-slate-200">
        <div className="max-w-5xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-200">
              <i className="fa-solid fa-id-card-clip text-xl"></i>
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-purple-600">
              Smart Scanner
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <label className="cursor-pointer bg-slate-100 hover:bg-slate-200 text-slate-700 px-4 py-2 rounded-xl text-sm font-medium transition-colors">
              <i className="fa-solid fa-upload mr-2"></i>
              Upload
              <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
            </label>
            <button 
              onClick={() => setShowScanner(true)}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-xl text-sm font-medium shadow-lg shadow-indigo-200 transition-all active:scale-95"
            >
              <i className="fa-solid fa-camera mr-2"></i>
              Scan Now
            </button>
          </div>
        </div>
      </header>

      {/* Hero / Processing Status */}
      <main className="max-w-5xl mx-auto px-4 py-8">
        {status === 'processing' && (
          <div className="mb-12 bg-indigo-50 border border-indigo-100 rounded-2xl p-12 text-center animate-in fade-in zoom-in duration-300">
            <div className="relative w-20 h-20 mx-auto mb-6">
              <div className="absolute inset-0 border-4 border-indigo-200 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
              <i className="fa-solid fa-microchip absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-indigo-600 text-2xl"></i>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Analyzing Business Card...</h2>
            <p className="text-slate-600">Our AI is extracting names, contacts, and details for you.</p>
          </div>
        )}

        {status === 'error' && (
          <div className="mb-12 bg-red-50 border border-red-100 rounded-2xl p-8 text-center">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4 text-red-600">
              <i className="fa-solid fa-triangle-exclamation text-2xl"></i>
            </div>
            <h2 className="text-xl font-bold text-red-800 mb-2">Oops! Something went wrong</h2>
            <p className="text-red-600 mb-4">{errorMsg || 'Could not process the image.'}</p>
            <button 
              onClick={() => setStatus('idle')}
              className="text-red-800 font-semibold underline underline-offset-4"
            >
              Dismiss
            </button>
          </div>
        )}

        {/* Empty State */}
        {cards.length === 0 && status === 'idle' && (
          <div className="py-20 text-center">
            <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-400">
              <i className="fa-solid fa-address-book text-4xl"></i>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">No contacts yet</h2>
            <p className="text-slate-500 max-w-sm mx-auto">
              Scan your first business card or upload a photo to start building your digital rolodex.
            </p>
            <button 
              onClick={() => setShowScanner(true)}
              className="mt-8 bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-3 rounded-2xl font-semibold shadow-xl shadow-indigo-200 transition-all hover:-translate-y-1 active:scale-95"
            >
              Start Scanning
            </button>
          </div>
        )}

        {/* Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {cards.map((card) => (
            <BusinessCard 
              key={card.id} 
              data={card} 
              onDelete={() => deleteCard(card.id)} 
            />
          ))}
        </div>
      </main>

      {/* Modals & Overlays */}
      {showScanner && (
        <CameraScanner 
          onCapture={onCapture} 
          onClose={() => setShowScanner(false)} 
        />
      )}

      {/* Floating Action Button (Mobile) */}
      <div className="md:hidden fixed bottom-6 right-6 z-30">
        <button 
          onClick={() => setShowScanner(true)}
          className="w-16 h-16 bg-indigo-600 text-white rounded-full shadow-2xl shadow-indigo-400 flex items-center justify-center active:scale-90 transition-transform"
        >
          <i className="fa-solid fa-camera text-2xl"></i>
        </button>
      </div>

      <footer className="max-w-5xl mx-auto px-4 py-12 text-center text-slate-400 text-sm border-t border-slate-100 mt-20">
        <p>&copy; 2024 Smart Card Scanner. Powered by Gemini AI.</p>
      </footer>
    </div>
  );
};

export default App;

