import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractCardInfo = async (base64Image: string): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: "Extract information from this business card image for a CRM database (QS Hub style). Important: If a field is not explicitly found on the card, you MUST return an empty string (\"\") for that field. Do not omit any fields from the JSON. Return valid JSON only.",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING, description: "Full name" },
          title: { type: Type.STRING, description: "Job title" },
          company: { type: Type.STRING, description: "Company name" },
          department: { type: Type.STRING, description: "Department name" },
          email: { type: Type.STRING, description: "Professional email address" },
          phone: { type: Type.STRING, description: "Office phone number" },
          mobile: { type: Type.STRING, description: "Mobile phone number" },
          fax: { type: Type.STRING, description: "Fax number" },
          website: { type: Type.STRING, description: "Company website URL" },
          address: { type: Type.STRING, description: "Full mailing address" },
          notes: { type: Type.STRING, description: "Additional observations" },
        },
        required: ["name", "title", "company", "department", "email", "phone", "mobile", "fax", "website", "address", "notes"],
      },
    },
  });

  try {
    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text);
  } catch (error) {
    console.error("Error parsing Gemini response:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { BusinessCardData } from '../types';

interface BusinessCardProps {
  data: BusinessCardData;
  onDelete?: () => void;
}

const BusinessCard: React.FC<BusinessCardProps> = ({ data, onDelete }) => {
  const [copied, setCopied] = useState(false);

  const copyToClipboard = () => {
    // Exclude internal fields for clean submission
    const { id, scannedAt, imageUrl, ...submissionData } = data;
    navigator.clipboard.writeText(JSON.stringify(submissionData, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-white rounded-2xl shadow-md overflow-hidden border border-slate-200 group flex flex-col h-full">
      <div className="p-5 flex-1 space-y-3">
        <div className="flex justify-between items-start">
