            <h3 className="text-xl font-bold text-slate-900 leading-tight">{data.name || 'Unknown Name'}</h3>
            <p className="text-indigo-600 text-sm font-semibold">{data.title || 'No Title'}</p>
          </div>
          <button 
            onClick={copyToClipboard}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
              copied ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600 hover:bg-indigo-50 hover:text-indigo-600'
            }`}
          >
            <i className={`fa-solid ${copied ? 'fa-check' : 'fa-copy'}`}></i>
            {copied ? 'Copied' : 'JSON'}
          </button>
        </div>

        <div className="pt-2 space-y-2 border-t border-slate-50">
          <div className="flex items-center gap-3 text-slate-600">
            <i className="fa-solid fa-building w-4 text-slate-400"></i>
            <span className="text-sm">{data.company || <span className="text-slate-300 italic">Empty</span>}</span>
          </div>
          {data.department && (
            <div className="flex items-center gap-3 text-slate-600">
              <i className="fa-solid fa-sitemap w-4 text-slate-400"></i>
              <span className="text-sm">{data.department}</span>
            </div>
