          <div className="flex items-center gap-3 text-slate-600">
            <i className="fa-solid fa-envelope w-4 text-slate-400"></i>
            <span className="text-sm truncate">{data.email || <span className="text-slate-300 italic">Empty</span>}</span>
          </div>
          <div className="flex items-center gap-3 text-slate-600">
            <i className="fa-solid fa-phone w-4 text-slate-400"></i>
            <span className="text-sm">{data.phone || data.mobile || <span className="text-slate-300 italic">Empty</span>}</span>
          </div>
        </div>
      </div>

      <div className="px-5 py-3 bg-slate-50 border-t border-slate-100 flex justify-between items-center">
        <span className="text-[10px] text-slate-400 uppercase font-bold tracking-wider">
          QS Hub Ready
        </span>
        <button 
          onClick={onDelete}
          className="text-slate-300 hover:text-red-500 transition-colors p-1"
        >
          <i className="fa-solid fa-trash-can text-sm"></i>
        </button>
      </div>
    </div>
  );
};

