  const [status, setStatus] = useState<ScanStatus>('idle');
  const [showScanner, setShowScanner] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards');
    if (saved) {
      try {
        setCards(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards', JSON.stringify(cards));
  }, [cards]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setStatus('processing');
    const reader = new FileReader();
    reader.onload = async (e) => {
      const base64 = (e.target?.result as string).split(',')[1];
      await processImage(base64);
    };
    reader.readAsDataURL(file);
    event.target.value = ''; // Reset input
  };

  const onCapture = async (base64: string) => {
    setShowScanner(false);
    setStatus('processing');
    await processImage(base64);
  };

  const processImage = async (base64: string) => {
    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setStatus('idle');
    } catch (err) {
      setErrorMsg('Analyze failed. Ensure image is clear.');
      setStatus('error');
      console.error(err);
    }
  };

  const exportAll = () => {
    const exportData = cards.map(({ id, scannedAt, imageUrl, ...rest }) => rest);
    const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `qshub_export_${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
