            </div>
            <h1 className="text-lg font-bold tracking-tight text-slate-800">QS Hub Scanner</h1>
          </div>

          <div className="flex items-center gap-2">
            {cards.length > 0 && (
              <button 
                onClick={exportAll}
                className="hidden sm:flex items-center gap-2 text-slate-600 hover:text-indigo-600 px-3 py-2 text-sm font-semibold transition-colors"
              >
                <i className="fa-solid fa-download"></i>
                Export All
              </button>
            )}
            <label className="cursor-pointer hover:bg-slate-100 p-2 rounded-full transition-colors">
              <i className="fa-solid fa-upload text-slate-500"></i>
              <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
            </label>
            <button 
              onClick={() => setShowScanner(true)}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-sm transition-all"
            >
              <i className="fa-solid fa-plus mr-2"></i>
              Scan Card
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-4 py-8">
        {status === 'processing' && (
          <div className="mb-10 text-center py-10 bg-white rounded-3xl border border-slate-200 shadow-sm animate-pulse">
            <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
            <p className="text-slate-600 font-bold">Formatting for QS Hub...</p>
          </div>
        )}

        {status === 'error' && (
          <div className="mb-10 p-4 bg-red-50 text-red-700 rounded-xl flex items-center justify-between border border-red-100">
            <span className="text-sm font-medium">{errorMsg}</span>
            <button onClick={() => setStatus('idle')} className="text-xs font-bold underline">Dismiss</button>
          </div>
        )}

        {cards.length === 0 && status === 'idle' ? (
          <div className="py-20 text-center bg-white rounded-3xl border border-dashed border-slate-300">
            <div className="mb-4 text-slate-200">
              <i className="fa-solid fa-id-card text-6xl"></i>
            </div>
            <h2 className="text-xl font-bold text-slate-800">Ready to ingest data</h2>
            <p className="text-slate-500 text-sm mt-1">Upload business cards to start the extraction process.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {cards.map((card) => (
              <BusinessCard 
                key={card.id} 
                data={card} 
                onDelete={() => setCards(prev => prev.filter(c => c.id !== card.id))} 
              />
            ))}
          </div>
        )}
      </main>

      {showScanner && (
        <CameraScanner 
          onCapture={onCapture} 
          onClose={() => setShowScanner(false)} 
        />
      )}
    </div>
  );
};

