import { BusinessCardData, ScanStatus } from './types';
import { extractCardInfo } from './services/geminiService';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v2');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) setSelectedCardId(parsed[0].id);
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v2', JSON.stringify(cards));
  }, [cards]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileArray = Array.from(files);
    processFilesBatch(fileArray);
    event.target.value = '';
  };

  const processFilesBatch = async (files: File[]) => {
    setStatus('processing');
    setBatchProgress({ current: 0, total: files.length });
    setErrorMsg(null);

    const newScannedCards: BusinessCardData[] = [];

    for (let i = 0; i < files.length; i++) {
      setBatchProgress({ current: i + 1, total: files.length });
      const file = files[i];

      try {
        const base64 = await fileToBase64(file);
        const info = await extractCardInfo(base64);
        const newCard: BusinessCardData = {
          id: crypto.randomUUID(),
          ...info,
          scannedAt: Date.now(),
          imageUrl: `data:image/jpeg;base64,${base64}`,
        };
        newScannedCards.push(newCard);

        // Immediately add to list so user sees results one by one
        setCards(prev => [newCard, ...prev]);
        if (i === 0) setSelectedCardId(newCard.id);
      } catch (err) {
        console.error(`Failed to process file ${file.name}`, err);
        setErrorMsg(`Partial failure: Could not process ${file.name}`);
      }
    }

    setStatus('idle');
    setBatchProgress({ current: 0, total: 0 });
    if (window.innerWidth < 1024) setIsSidebarOpen(false);
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const copyToClipboard = (card: BusinessCardData) => {
    const { id, scannedAt, imageUrl, ...submissionData } = card;
    navigator.clipboard.writeText(JSON.stringify(submissionData, null, 2));
    setCopiedId(card.id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const downloadJSON = (data: any[], filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportAll = () => {
    const exportData = cards.map(({ id, scannedAt, imageUrl, ...rest }) => rest);
    downloadJSON(exportData, `qshub_all_${new Date().toISOString().split('T')[0]}.json`);
  };

  const exportLast10 = () => {
    const last10 = cards.slice(0, 10).map(({ id, scannedAt, imageUrl, ...rest }) => rest);
    downloadJSON(last10, `qshub_last10_${new Date().toISOString().split('T')[0]}.json`);
  };

  const deleteCard = (id: string) => {
    setCards(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (selectedCardId === id) {
        setSelectedCardId(filtered.length > 0 ? filtered[0].id : null);
      }
      return filtered;
    });
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-72 lg:static lg:w-80 flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-4 flex flex-col gap-3">
          <div className="flex items-center justify-between">
            <h2 className="text-xs font-bold text-slate-500 uppercase tracking-widest">History</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400">
              <i className="fa-solid fa-xmark"></i>
            </button>
          </div>

          <div className="flex gap-2">
            <button 
              onClick={exportLast10} 
              disabled={cards.length === 0} 
              className="flex-1 bg-white border border-slate-300 text-slate-600 hover:bg-slate-50 px-2 py-1.5 rounded text-[10px] font-bold shadow-sm disabled:opacity-30 transition-colors"
