                  className={`p-3 rounded-lg cursor-pointer transition-all flex items-center gap-3 group ${
                    selectedCardId === card.id ? 'bg-white shadow-sm ring-1 ring-slate-200' : 'hover:bg-white/50'
                  }`}
                >
                  <div className="w-8 h-8 rounded bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold text-xs shrink-0">
                    {card.name ? card.name.charAt(0) : '?'}
