                      {new Date(card.scannedAt).toLocaleDateString()}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 bg-white shadow-[-4px_0_15px_rgba(0,0,0,0.02)]">
        {/* Toolbar */}
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-4 lg:px-6 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2">
              <i className="fa-solid fa-bars"></i>
            </button>
            <div className="hidden sm:flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500"></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Ingester</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-1.5 rounded text-sm font-semibold shadow-sm flex items-center gap-2"
            >
              <i className="fa-solid fa-images"></i>
              <span className="hidden sm:inline">Batch Upload</span>
              <span className="sm:hidden">Upload</span>
            </button>
