              </div>
              <h2 className="text-xl font-bold text-slate-800">Batch Processing</h2>
              <p className="text-sm text-slate-500 mt-1">
                Processing card <span className="text-indigo-600 font-bold">{batchProgress.current}</span> of <span className="font-bold">{batchProgress.total}</span>
              </p>
              <p className="text-xs text-slate-400 mt-4 max-w-xs mx-auto">Gemini AI is extracting structured CRM data from your uploads.</p>
            </div>
          ) : selectedCard ? (
            <div className="max-w-5xl mx-auto grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
              {/* Left Column: Visuals */}
              <div className="space-y-6">
                <div className="aspect-[1.6/1] bg-slate-50 rounded-xl border border-slate-200 shadow-sm overflow-hidden flex items-center justify-center">
                  <img src={selectedCard.imageUrl} alt="Scan" className="max-w-full max-h-full object-contain" />
                </div>

                <div className="bg-slate-900 rounded-xl p-5 text-white shadow-xl">
                  <div className="flex items-center justify-between mb-4">
                    <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">JSON Output</span>
                    <button 
                      onClick={() => copyToClipboard(selectedCard)}
                      className={`px-3 py-1 rounded text-[10px] font-bold transition-all ${
                        copiedId === selectedCard.id ? 'bg-green-500 text-white' : 'bg-white/10 hover:bg-white/20'
                      }`}
                    >
                      {copiedId === selectedCard.id ? 'COPIED' : 'COPY'}
                    </button>
                  </div>
                  <pre className="text-[10px] font-mono opacity-80 overflow-x-auto">
                    {JSON.stringify({
                      name: selectedCard.name,
                      title: selectedCard.title,
                      company: selectedCard.company,
                      department: selectedCard.department,
                      email: selectedCard.email,
                      phone: selectedCard.phone,
                      mobile: selectedCard.mobile,
                      fax: selectedCard.fax,
                      website: selectedCard.website,
                      address: selectedCard.address,
                      notes: selectedCard.notes
                    }, null, 2)}
                  </pre>
                </div>
              </div>

              {/* Right Column: Structured Data */}
              <div className="space-y-6">
                <div className="flex justify-between items-start">
                  <div>
                    <h2 className="text-2xl font-bold text-slate-900 leading-none mb-2">{selectedCard.name || 'No Name'}</h2>
                    <p className="text-indigo-600 font-semibold text-sm">{selectedCard.title || 'No Title'}</p>
                  </div>
                  <button onClick={() => deleteCard(selectedCard.id)} className="text-slate-300 hover:text-red-500 transition-colors">
                    <i className="fa-solid fa-trash-can"></i>
                  </button>
                </div>

                <div className="grid grid-cols-1 gap-4 bg-slate-50 p-6 rounded-2xl border border-slate-100">
                  <DataRow label="Company" value={selectedCard.company} icon="fa-building" />
                  <DataRow label="Email" value={selectedCard.email} icon="fa-envelope" />
                  <DataRow label="Mobile" value={selectedCard.mobile} icon="fa-mobile-screen" />
                  <DataRow label="Department" value={selectedCard.department} icon="fa-sitemap" />
                  <DataRow label="Address" value={selectedCard.address} icon="fa-location-dot" />
                  <DataRow label="Website" value={selectedCard.website} icon="fa-globe" />
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-4">
              <div 
                className="w-full max-w-lg p-12 border-2 border-dashed border-slate-200 rounded-3xl hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group"
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-16 h-16 bg-white shadow-sm rounded-2xl flex items-center justify-center mx-auto mb-4 text-indigo-500 group-hover:scale-110 transition-transform">
                  <i className="fa-solid fa-cloud-arrow-up text-2xl"></i>
                </div>
                <h3 className="text-lg font-bold text-slate-800">Batch Upload Cards</h3>
                <p className="text-xs text-slate-500 mt-1">Select one or multiple images to start extraction</p>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Mobile Sidebar Overlay */}
      {isSidebarOpen && (
        <div className="fixed inset-0 bg-black/20 z-40 lg:hidden" onClick={() => setIsSidebarOpen(false)}></div>
      )}

      {errorMsg && (
        <div className="fixed bottom-6 inset-x-6 lg:left-auto lg:right-6 bg-red-600 text-white px-6 py-3 rounded-lg shadow-2xl flex items-center justify-between z-[60] animate-in slide-in-from-right-full">
          <div className="flex items-center gap-3">
            <i className="fa-solid fa-triangle-exclamation"></i>
            <span className="text-xs font-bold">{errorMsg}</span>
          </div>
          <button onClick={() => setErrorMsg(null)}><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

const DataRow = ({ label, value, icon }: { label: string, value?: string, icon: string }) => (
