    <div className="flex items-center gap-2 mb-1">
      <i className={`fa-solid ${icon} text-slate-300 text-[10px] w-4`}></i>
      <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{label}</span>
    </div>
    <div className="pl-6">
      <p className={`text-sm ${value ? 'text-slate-700 font-medium' : 'text-slate-300 italic'}`}>
        {value || 'Empty'}
      </p>
