);

export default App;

export interface BusinessCardData {
  id: string;
  name: string;
  title: string;
  company: string;
  department: string;
  email: string;
  phone: string;
  mobile: string;
  fax: string;
  website: string;
  address: string;
  notes: string;
  category: 'employer' | 'academic'; // Added for QS Hub
  scannedAt: number;
  imageUrl?: string;
}

export type ScanStatus = 'idle' | 'scanning' | 'processing' | 'success' | 'error';

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractCardInfo = async (base64Image: string): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: "Extract information from this business card for QS Hub CRM. Critically, categorize the card as 'academic' if it's from a University, School, or Research Institute, and 'employer' if it's from a corporate company, NGO, or government body. If a field is missing, return \"\". Return valid JSON.",
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING, description: "Full name" },
          title: { type: Type.STRING, description: "Job title" },
          company: { type: Type.STRING, description: "Company or Institution name" },
          department: { type: Type.STRING, description: "Department name" },
          email: { type: Type.STRING, description: "Professional email address" },
          phone: { type: Type.STRING, description: "Office phone number" },
          mobile: { type: Type.STRING, description: "Mobile phone number" },
          fax: { type: Type.STRING, description: "Fax number" },
          website: { type: Type.STRING, description: "Website URL" },
          address: { type: Type.STRING, description: "Full mailing address" },
          notes: { type: Type.STRING, description: "Additional observations" },
          category: { type: Type.STRING, enum: ["employer", "academic"], description: "Classification for QS Hub" },
        },
        required: ["name", "title", "company", "department", "email", "phone", "mobile", "fax", "website", "address", "notes", "category"],
      },
    },
  });

  try {
    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text);
  } catch (error) {
    console.error("Error parsing Gemini response:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus } from './types';
import { extractCardInfo } from './services/geminiService';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v3');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) setSelectedCardId(parsed[0].id);
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v3', JSON.stringify(cards));
  }, [cards]);

  // Split cards by category
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileArray = Array.from(files);
    processFilesBatch(fileArray);
    event.target.value = '';
  };

  const processFilesBatch = async (files: File[]) => {
    setStatus('processing');
    setBatchProgress({ current: 0, total: files.length });
    setErrorMsg(null);

    for (let i = 0; i < files.length; i++) {
      setBatchProgress({ current: i + 1, total: files.length });
      const file = files[i];
      try {
        const reader = new FileReader();
        const base64 = await new Promise<string>((resolve) => {
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(file);
        });

        const info = await extractCardInfo(base64);
        const newCard: BusinessCardData = {
          id: crypto.randomUUID(),
          ...info,
          scannedAt: Date.now(),
          imageUrl: `data:image/jpeg;base64,${base64}`,
        };
        setCards(prev => [newCard, ...prev]);
        if (i === 0) setSelectedCardId(newCard.id);
      } catch (err) {
        setErrorMsg(`Failed: ${file.name}`);
      }
    }
    setStatus('idle');
  };

  const toggleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        return { ...c, category: c.category === 'employer' ? 'academic' : 'employer' };
      }
      return c;
    }));
  };

  const downloadJSON = (data: any[], filename: string) => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportByCategory = (category: 'employer' | 'academic') => {
    const filtered = cards.filter(c => c.category === category)
      .map(({ id, scannedAt, imageUrl, ...rest }) => rest);
    downloadJSON(filtered, `qshub_${category}_${new Date().toISOString().split('T')[0]}.json`);
  };

  const deleteCard = (id: string) => {
    setCards(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (selectedCardId === id) setSelectedCardId(filtered.length > 0 ? filtered[0].id : null);
      return filtered;
    });
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      {/* QS Styled Sidebar - Dual Column History */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[420px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Submission Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <button onClick={() => exportByCategory('employer')} className="bg-indigo-600 hover:bg-indigo-700 text-white p-2 rounded text-[10px] font-bold shadow-sm flex flex-col items-center">
              <span>Export Employer</span>
              <span className="opacity-70">({employerCards.length})</span>
            </button>
            <button onClick={() => exportByCategory('academic')} className="bg-emerald-600 hover:bg-emerald-700 text-white p-2 rounded text-[10px] font-bold shadow-sm flex flex-col items-center">
              <span>Export Academic</span>
              <span className="opacity-70">({academicCards.length})</span>
            </button>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          {/* Employer Column */}
          <div className="flex-1 border-r border-slate-200 flex flex-col">
            <div className="p-2 bg-indigo-50 border-b border-slate-200 text-center">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">Employer</span>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
              {employerCards.map(card => (
                <HistoryItem key={card.id} card={card} isActive={selectedCardId === card.id} onClick={() => setSelectedCardId(card.id)} colorClass="indigo" />
              ))}
            </div>
          </div>
          {/* Academic Column */}
          <div className="flex-1 flex flex-col">
            <div className="p-2 bg-emerald-50 border-b border-slate-200 text-center">
              <span className="text-[9px] font-black text-emerald-400 uppercase tracking-tighter">Academic</span>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
              {academicCards.map(card => (
                <HistoryItem key={card.id} card={card} isActive={selectedCardId === card.id} onClick={() => setSelectedCardId(card.id)} colorClass="emerald" />
              ))}
            </div>
          </div>
        </div>
      </aside>

      {/* Main Panel */}
      <main className="flex-1 flex flex-col min-w-0 bg-white">
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-6 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Workspace</span>
            </div>
          </div>
          <button onClick={() => fileInputRef.current?.click()} className="bg-slate-900 hover:bg-black text-white px-5 py-2 rounded-lg text-xs font-bold shadow-lg flex items-center gap-2 transition-all active:scale-95">
            <i className="fa-solid fa-cloud-arrow-up"></i>
            <span>Batch Upload</span>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-10 bg-slate-50/30">
          {status === 'processing' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-bold text-slate-800">QS Classifier Busy</h2>
              <p className="text-sm text-slate-500">Processing {batchProgress.current} / {batchProgress.total}</p>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Visuals */}
                <div className="space-y-6">
                  <div className="bg-white p-2 rounded-2xl shadow-xl border border-slate-200 overflow-hidden ring-4 ring-slate-50">
                    <img src={selectedCard.imageUrl} alt="Scan" className="w-full h-auto rounded-xl" />
                  </div>
                  <div className={`p-4 rounded-2xl border flex items-center justify-between shadow-sm ${selectedCard.category === 'employer' ? 'bg-indigo-50 border-indigo-100' : 'bg-emerald-50 border-emerald-100'}`}>
                    <div>
                      <span className="text-[10px] font-bold uppercase opacity-50 block mb-1">QS Classification</span>
                      <span className={`text-lg font-black uppercase tracking-tight ${selectedCard.category === 'employer' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                        {selectedCard.category}
                      </span>
                    </div>
                    <button onClick={() => toggleCategory(selectedCard.id)} className="bg-white px-4 py-2 rounded-xl text-[11px] font-bold border border-slate-200 hover:bg-slate-50 shadow-sm transition-all active:scale-95">
                      Switch to {selectedCard.category === 'employer' ? 'Academic' : 'Employer'}
                    </button>
                  </div>
                </div>

                {/* Data Form */}
                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.name || 'Untitled'}</h1>
                    <button onClick={() => deleteCard(selectedCard.id)} className="text-slate-300 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label="Institution / Company" value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Work Email" value={selectedCard.email} icon="fa-envelope" />
                    <DataEntry label="Department" value={selectedCard.department} icon="fa-sitemap" />
                    <DataEntry label="Contact Number" value={selectedCard.mobile || selectedCard.phone} icon="fa-phone" />
                    <DataEntry label="Location" value={selectedCard.address} icon="fa-location-dot" />
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-24 h-24 bg-white rounded-[2rem] shadow-2xl flex items-center justify-center mb-6 text-indigo-500 animate-bounce cursor-pointer hover:scale-110 transition-all" onClick={() => fileInputRef.current?.click()}>
                <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
              </div>
              <h3 className="text-2xl font-black text-slate-800 tracking-tight">Ready for QS Hub Ingestion</h3>
              <p className="text-slate-400 text-sm mt-2 max-w-xs">Upload business cards to automatically classify as Academic or Employer contacts.</p>
            </div>
          )}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in slide-in-from-bottom-10">
          <i className="fa-solid fa-circle-exclamation"></i>
          <span className="text-sm font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

