import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function startCamera() {
      try {
        const mediaStream = await navigator.mediaDevices.getUserMedia({ 
          video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
        });
        setStream(mediaStream);
        if (videoRef.current) {
          videoRef.current.srcObject = mediaStream;
        }
      } catch (err) {
        setError("無法開啟相機，請檢查權限設定。");
        console.error(err);
      }
    }
    startCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  const capture = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-black/90 rounded-3xl overflow-hidden relative group">
      {error ? (
        <div className="text-white text-center p-6">
          <i className="fa-solid fa-circle-exclamation text-4xl mb-4 text-red-500"></i>
          <p className="font-bold">{error}</p>
        </div>
      ) : (
        <>
          <video ref={videoRef} autoPlay playsInline className="h-full w-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />

          {/* Scanning UI Overlay */}
          <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none flex items-center justify-center">
             <div className="w-full max-w-sm aspect-[1.6/1] border-2 border-indigo-400/50 rounded-lg relative overflow-hidden">
                <div className="absolute inset-0 bg-indigo-400/10 animate-pulse"></div>
                {/* Scanning line animation */}
                <div className="absolute top-0 left-0 w-full h-1 bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,1)] animate-[scan_2s_infinite_linear]"></div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center gap-10">
            <button 
              onClick={capture}
              className="w-20 h-20 rounded-full bg-white border-8 border-slate-300 flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-2xl"
            >
              <div className="w-12 h-12 rounded-full bg-indigo-600"></div>
            </button>
          </div>
        </>
      )}
      <style>{`
        @keyframes scan {
          0% { top: 0%; }
          100% { top: 100%; }
        }
      `}</style>
    </div>
  );
};

export default CameraScanner;

