      { wch: 30 }, { wch: 15 }, { wch: 15 }, { wch: 15 },
      { wch: 25 }, { wch: 40 }, { wch: 20 }, { wch: 15 }
    ];
    worksheet['!cols'] = wscols;

    const fileName = `QS_${category.charAt(0).toUpperCase() + category.slice(1)}s_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const deleteCard = (id: string) => {
    setCards(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (selectedCardId === id) setSelectedCardId(filtered.length > 0 ? filtered[0].id : null);
      return filtered;
    });
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
