            <div className="h-full flex flex-col items-center justify-center text-center">
              <div 
                className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group"
                onClick={() => fileInputRef.current?.click()}
