                    <div className="pt-4 border-t border-white/40">
                      <div className="flex items-center gap-2 mb-2">
                        <i className={`fa-solid fa-brain text-xs ${selectedCard.category === 'employer' ? 'text-indigo-400' : 'text-emerald-400'}`}></i>
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">AI 判定原因 (註解)</span>
                      </div>
                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">
                        {selectedCard.reasoning || "AI 正在分析判定邏輯..."}
                      </p>
                    </div>
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                    <button onClick={() => deleteCard(selectedCard.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label={selectedCard.category === 'academic' ? "Institution Name (單位名稱)" : "Company Name (公司名稱)"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title (職稱)" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email Address (電子郵件)" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category === 'academic' ? (
                       <DataEntry label="Department (系所部門)" value={selectedCard.department} icon="fa-sitemap" />
                    ) : (
                       <DataEntry label="Industry (產業別)" value={selectedCard.industry} icon="fa-industry" />
                    )}
                    <DataEntry label="Country / Territory (國家地區)" value={selectedCard.country} icon="fa-globe" />
                  </div>
