export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v3_reasoning');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) {
          setSelectedCardId(parsed[0].id);
          setViewMode('detail');
        }
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v3_reasoning', JSON.stringify(cards));
  }, [cards]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);

  const processSingleBase64 = async (base64: string) => {
    setStatus('processing');
    setBatchProgress({ current: 1, total: 1 });
    setErrorMsg(null);
    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setSelectedCardId(newCard.id);
      setViewMode('detail');
    } catch (err) {
      setErrorMsg("辨識失敗，請確保照片清晰且網路連線正常。");
    } finally {
      setStatus('idle');
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    processFilesBatch(Array.from(files));
    event.target.value = '';
  };

  const processFilesBatch = async (files: File[]) => {
    setStatus('processing');
    setBatchProgress({ current: 0, total: files.length });
    setErrorMsg(null);

    for (let i = 0; i < files.length; i++) {
      setBatchProgress({ current: i + 1, total: files.length });
      const file = files[i];
      try {
        const reader = new FileReader();
        const base64 = await new Promise<string>((resolve) => {
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(file);
        });

        const info = await extractCardInfo(base64);
        const newCard: BusinessCardData = {
          id: crypto.randomUUID(),
          ...info,
          scannedAt: Date.now(),
          imageUrl: `data:image/jpeg;base64,${base64}`,
        };
        setCards(prev => [newCard, ...prev]);
        if (i === 0) {
          setSelectedCardId(newCard.id);
          setViewMode('detail');
        }
      } catch (err) {
        setErrorMsg(`處理 ${file.name} 時出錯`);
      }
    }
    setStatus('idle');
  };

  const toggleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        return { ...c, category: c.category === 'employer' ? 'academic' : 'employer' };
      }
      return c;
    }));
  };

  const exportToExcel = (category: 'employer' | 'academic') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;

    let exportData;
    if (category === 'academic') {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Institution Name': c.company,
        'Department': c.department,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    } else {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Company Name': c.company,
        'Industry': c.industry,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    }

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category === 'academic' ? "Academic Reputation" : "Employer Reputation");

    const wscols = [
      { wch: 10 }, { wch: 20 }, { wch: 20 }, { wch: 25 },
      { wch: 35 }, { wch: 25 }, { wch: 20 }, { wch: 30 }
    ];
    worksheet['!cols'] = wscols;

    const fileName = `QS_${category === 'academic' ? 'Academic' : 'Employer'}_Reputation_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const deleteCard = (id: string) => {
    setCards(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (selectedCardId === id) setSelectedCardId(filtered.length > 0 ? filtered[0].id : null);
      return filtered;
    });
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[420px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Export Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <button 
              onClick={() => exportToExcel('employer')} 
              disabled={employerCards.length === 0}
              className="bg-indigo-600 hover:bg-indigo-700 text-white p-2 rounded text-[10px] font-bold shadow-sm flex flex-col items-center disabled:opacity-40 transition-all"
            >
              <i className="fa-solid fa-users-gear mb-1"></i>
              <span>Export Employer</span>
              <span className="opacity-70">({employerCards.length})</span>
            </button>
            <button 
              onClick={() => exportToExcel('academic')} 
              disabled={academicCards.length === 0}
              className="bg-emerald-600 hover:bg-emerald-700 text-white p-2 rounded text-[10px] font-bold shadow-sm flex flex-col items-center disabled:opacity-40 transition-all"
            >
              <i className="fa-solid fa-graduation-cap mb-1"></i>
              <span>Export Academic</span>
              <span className="opacity-70">({academicCards.length})</span>
            </button>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-slate-200 flex flex-col">
            <div className="p-2 bg-indigo-50 border-b border-slate-200 text-center">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">Employer</span>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
              {employerCards.map(card => (
                <HistoryItem key={card.id} card={card} isActive={selectedCardId === card.id} onClick={() => { setSelectedCardId(card.id); setViewMode('detail'); }} colorClass="indigo" />
              ))}
            </div>
          </div>
          <div className="flex-1 flex flex-col">
            <div className="p-2 bg-emerald-50 border-b border-slate-200 text-center">
              <span className="text-[9px] font-black text-emerald-400 uppercase tracking-tighter">Academic</span>
            </div>
            <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
              {academicCards.map(card => (
                <HistoryItem key={card.id} card={card} isActive={selectedCardId === card.id} onClick={() => { setSelectedCardId(card.id); setViewMode('detail'); }} colorClass="emerald" />
              ))}
            </div>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <button 
                  onClick={() => setViewMode('camera')}
                  className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'camera' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  <i className="fa-solid fa-camera"></i>
                  <span>拍照掃描</span>
                </button>
                <button 
                  onClick={() => setViewMode('file')}
                  className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'file' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  <i className="fa-solid fa-folder-open"></i>
                  <span>檔案上傳</span>
                </button>
                {selectedCard && (
                  <button 
                    onClick={() => setViewMode('detail')}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'detail' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                  >
                    <i className="fa-solid fa-address-card"></i>
                    <span>資料詳情</span>
                  </button>
                )}
             </nav>
          </div>
          <div className="hidden sm:flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Format Generator</span>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/30">
          {status === 'processing' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-bold text-slate-800">QS Parser Processing...</h2>
              <p className="text-sm text-slate-500">Extracting details for {batchProgress.current} / {batchProgress.total}</p>
            </div>
          ) : viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto p-2">
              <CameraScanner onCapture={processSingleBase64} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-upload text-3xl"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">批量上傳</h3>
                <p className="text-slate-400 text-sm mt-2">點擊上傳多張名片照片，自動生成 QS 格式 Excel</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Left Column: Image Reference Only */}
                <div className="space-y-6">
                  <div className="bg-white p-2 rounded-2xl shadow-xl border border-slate-200 overflow-hidden ring-4 ring-slate-50">
                    <img src={selectedCard.imageUrl} alt="Scan" className="w-full h-auto rounded-xl" />
                  </div>
                </div>

                {/* Right Column: Actions, Reasoning and Data Fields */}
                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                    <button onClick={() => deleteCard(selectedCard.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>

                  {/* Classification and AI Reasoning moved here to the Right side */}
                  <div className={`p-6 rounded-3xl border shadow-sm ${selectedCard.category === 'employer' ? 'bg-indigo-50 border-indigo-100' : 'bg-emerald-50 border-emerald-100'}`}>
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <span className="text-[10px] font-bold uppercase opacity-50 block mb-1">分類判定 (Classification)</span>
                        <span className={`text-xl font-black uppercase tracking-tight ${selectedCard.category === 'employer' ? 'text-indigo-600' : 'text-emerald-600'}`}>
                          {selectedCard.category === 'employer' ? '雇主聲望 (Employer)' : '學術聲望 (Academic)'}
                        </span>
                      </div>
                      <button onClick={() => toggleCategory(selectedCard.id)} className="bg-white px-4 py-2 rounded-xl text-[11px] font-bold border border-slate-200 hover:bg-slate-50 shadow-sm transition-all active:scale-95">
                        手動修正分類
                      </button>
                    </div>

                    <div className="pt-4 border-t border-white/40">
                      <div className="flex items-center gap-2 mb-2">
                        <i className={`fa-solid fa-brain text-xs ${selectedCard.category === 'employer' ? 'text-indigo-400' : 'text-emerald-400'}`}></i>
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">AI 判定原因 (註解)</span>
                      </div>
                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">
                        {selectedCard.reasoning || "AI 正在分析判定邏輯..."}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label={selectedCard.category === 'academic' ? "Institution Name (單位名稱)" : "Company Name (公司名稱)"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title (職稱)" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email Address (電子郵件)" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category === 'academic' ? (
                       <DataEntry label="Department (系所部門)" value={selectedCard.department} icon="fa-sitemap" />
                    ) : (
                       <DataEntry label="Industry (產業別)" value={selectedCard.industry} icon="fa-industry" />
                    )}
                    <DataEntry label="Country / Territory (國家地區)" value={selectedCard.country} icon="fa-globe" />
                  </div>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in slide-in-from-bottom-10">
          <i className="fa-solid fa-triangle-exclamation"></i>
          <span className="text-sm font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

const HistoryItem = ({ card, isActive, onClick, colorClass }: { card: BusinessCardData, isActive: boolean, onClick: () => void, colorClass: string }) => (
  <div onClick={onClick} className={`p-2 rounded-xl cursor-pointer transition-all flex flex-col gap-1 border ${isActive ? `bg-white shadow-lg border-${colorClass}-200 ring-2 ring-${colorClass}-500/10` : 'bg-white/40 border-transparent hover:bg-white hover:shadow-sm'}`}>
    <p className={`text-[10px] font-bold truncate ${isActive ? `text-${colorClass}-600` : 'text-slate-700'}`}>{card.firstName} {card.lastName}</p>
    <p className="text-[8px] text-slate-400 font-medium truncate">{card.company}</p>
  </div>
);

const DataEntry = ({ label, value, icon }: { label: string, value?: string, icon: string }) => (
  <div className="group">
    <div className="flex items-center gap-2 mb-1">
      <div className="w-5 h-5 flex items-center justify-center rounded-md bg-slate-50 text-slate-400 text-[10px] group-hover:text-indigo-500 transition-colors">
        <i className={`fa-solid ${icon}`}></i>
      </div>
      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    </div>
    <div className="pl-7">
      <p className={`text-sm leading-relaxed ${value ? 'text-slate-800 font-semibold' : 'text-slate-300 italic'}`}>
        {value || 'Missing'}
      </p>
    </div>
  </div>
);

export default App;

export interface BusinessCardData {
  id: string;
  prefix: string; // Mr, Ms, Dr, etc.
  firstName: string;
  lastName: string;
  title: string; // Job Title
  company: string; // Institution or Company Name
  department: string;
  industry: string; // For Employers
  country: string;
  email: string;
  phone: string;
  mobile: string;
  fax: string;
  website: string;
  address: string;
  notes: string;
  category: 'employer' | 'academic' | 'staff';
  reasoning: string; // Explanation of why this category was chosen
  scannedAt: number;
  imageUrl?: string;
}

export type ScanStatus = 'idle' | 'scanning' | 'processing' | 'success' | 'error';

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const extractCardInfo = async (base64Image: string): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'image/jpeg',
            data: base64Image,
          },
        },
        {
          text: `Extract contact details from this business card for QS World University Rankings. 
          Categorize into THREE distinct groups:
          1. 'academic': Teaching or Research roles at a University (Professor, Lecturer, Researcher, Dean).
          2. 'staff': Administrative or Support roles at a University (Registrar, HR, IT, Secretary, Office Staff, Facilities).
          3. 'employer': Roles at Corporate, Private, or Government non-educational organizations.

          Split name into prefix (Mr/Ms/Dr/Prof), first name, and last name.
          Extract country and industry (for employers).
          Provide a brief explanation in Traditional Chinese for why you chose the category based on the institution or job title. 
          If a field is missing, use "". Return JSON.`,
        },
      ],
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          prefix: { type: Type.STRING, description: "Salutation (e.g., Mr., Ms., Dr., Prof.)" },
          firstName: { type: Type.STRING, description: "First Name" },
          lastName: { type: Type.STRING, description: "Last Name" },
          title: { type: Type.STRING, description: "Job Title" },
          company: { type: Type.STRING, description: "Institution or Company Name" },
          department: { type: Type.STRING, description: "Department" },
          industry: { type: Type.STRING, description: "Industry (Primary field for employers)" },
          country: { type: Type.STRING, description: "Country or Territory" },
          email: { type: Type.STRING, description: "Email address" },
          phone: { type: Type.STRING },
          mobile: { type: Type.STRING },
          fax: { type: Type.STRING },
          website: { type: Type.STRING },
          address: { type: Type.STRING },
          notes: { type: Type.STRING },
          category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
          reasoning: { type: Type.STRING, description: "Reasoning for category choice in Traditional Chinese" },
        },
        required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning"],
      },
    },
  });

  try {
    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text);
  } catch (error) {
    console.error("Error parsing Gemini response:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [status, setStatus] = useState<ScanStatus>('idle');
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v4_staff');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) {
          setSelectedCardId(parsed[0].id);
          setViewMode('detail');
        }
      } catch (e) {
        console.error("Failed to parse saved cards", e);
      }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v4_staff', JSON.stringify(cards));
  }, [cards]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const processSingleBase64 = async (base64: string) => {
    setStatus('processing');
    setBatchProgress({ current: 1, total: 1 });
    setErrorMsg(null);
    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setSelectedCardId(newCard.id);
      setViewMode('detail');
    } catch (err) {
      setErrorMsg("辨識失敗，請確保照片清晰且網路連線正常。");
    } finally {
      setStatus('idle');
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    processFilesBatch(Array.from(files));
    event.target.value = '';
  };

  const processFilesBatch = async (files: File[]) => {
    setStatus('processing');
    setBatchProgress({ current: 0, total: files.length });
    setErrorMsg(null);

    for (let i = 0; i < files.length; i++) {
      setBatchProgress({ current: i + 1, total: files.length });
      const file = files[i];
      try {
        const reader = new FileReader();
        const base64 = await new Promise<string>((resolve) => {
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(file);
        });

        const info = await extractCardInfo(base64);
        const newCard: BusinessCardData = {
          id: crypto.randomUUID(),
          ...info,
          scannedAt: Date.now(),
          imageUrl: `data:image/jpeg;base64,${base64}`,
        };
        setCards(prev => [newCard, ...prev]);
        if (i === 0) {
          setSelectedCardId(newCard.id);
          setViewMode('detail');
        }
      } catch (err) {
        setErrorMsg(`處理 ${file.name} 時出錯`);
      }
    }
    setStatus('idle');
  };

  const cycleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        const order: ('employer' | 'academic' | 'staff')[] = ['employer', 'academic', 'staff'];
        const nextIndex = (order.indexOf(c.category) + 1) % order.length;
        return { ...c, category: order[nextIndex] };
      }
      return c;
    }));
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;

    let exportData;
    if (category === 'academic' || category === 'staff') {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Institution Name': c.company,
        'Department': c.department,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    } else {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Company Name': c.company,
        'Industry': c.industry,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    }

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    const sheetName = category.charAt(0).toUpperCase() + category.slice(1) + " Reputation";
    XLSX.utils.book_append_sheet(workbook, worksheet, sheetName);

    const wscols = Array(8).fill({ wch: 25 });
    worksheet['!cols'] = wscols;

    const fileName = `QS_${category.toUpperCase()}_Reputation_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const deleteCard = (id: string) => {
    setCards(prev => {
      const filtered = prev.filter(c => c.id !== id);
      if (selectedCardId === id) setSelectedCardId(filtered.length > 0 ? filtered[0].id : null);
      return filtered;
    });
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      {/* Expanded Sidebar to handle 3 Categories */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[480px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportButton color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportButton color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportButton color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <ColumnGroup title="Employer" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={(id) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Academic" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={(id) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Staff" color="amber" items={staffCards} activeId={selectedCardId} onSelect={(id) => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <button 
                  onClick={() => setViewMode('camera')}
                  className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'camera' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  <i className="fa-solid fa-camera"></i>
                  <span>拍照掃描</span>
                </button>
                <button 
                  onClick={() => setViewMode('file')}
                  className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'file' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                >
                  <i className="fa-solid fa-folder-open"></i>
                  <span>檔案上傳</span>
                </button>
                {selectedCard && (
                  <button 
                    onClick={() => setViewMode('detail')}
                    className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${viewMode === 'detail' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}
                  >
                    <i className="fa-solid fa-address-card"></i>
                    <span>資料詳情</span>
                  </button>
                )}
             </nav>
          </div>
          <div className="hidden sm:flex items-center gap-2">
            <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Format Generator</span>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/30">
          {status === 'processing' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
              <h2 className="text-xl font-bold text-slate-800 tracking-tight">AI 辨識分類中...</h2>
              <p className="text-sm text-slate-500">正在處理第 {batchProgress.current} 張，共 {batchProgress.total} 張</p>
            </div>
          ) : viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto p-2">
              <CameraScanner onCapture={processSingleBase64} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-upload text-3xl"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">批量名片上傳</h3>
                <p className="text-slate-400 text-sm mt-2">支援自動區分校內教研、行政職員或企業雇主</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="bg-white p-2 rounded-2xl shadow-xl border border-slate-200 overflow-hidden ring-4 ring-slate-50">
                    <img src={selectedCard.imageUrl} alt="Scan" className="w-full h-auto rounded-xl" />
                  </div>
                </div>

                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                    <button onClick={() => deleteCard(selectedCard.id)} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>

                  {/* Enhanced Classification Block */}
                  <div className={`p-6 rounded-3xl border shadow-sm transition-colors duration-500 ${
                    selectedCard.category === 'employer' ? 'bg-indigo-50 border-indigo-100' : 
                    selectedCard.category === 'academic' ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-100'
                  }`}>
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <span className="text-[10px] font-bold uppercase opacity-50 block mb-1">分類判定 (Classification)</span>
                        <span className={`text-xl font-black uppercase tracking-tight ${
                          selectedCard.category === 'employer' ? 'text-indigo-600' : 
                          selectedCard.category === 'academic' ? 'text-emerald-600' : 'text-amber-600'
                        }`}>
                          {selectedCard.category === 'employer' ? '雇主聲望 (Employer)' : 
                           selectedCard.category === 'academic' ? '學術教研 (Academic)' : '校內職員 (Staff)'}
                        </span>
                      </div>
                      <button onClick={() => cycleCategory(selectedCard.id)} className="bg-white px-4 py-2 rounded-xl text-[11px] font-bold border border-slate-200 hover:bg-slate-50 shadow-sm transition-all active:scale-95">
                        切換分類
                      </button>
                    </div>

                    <div className="pt-4 border-t border-white/40">
                      <div className="flex items-center gap-2 mb-2">
                        <i className={`fa-solid fa-brain text-xs ${
                          selectedCard.category === 'employer' ? 'text-indigo-400' : 
                          selectedCard.category === 'academic' ? 'text-emerald-400' : 'text-amber-400'
                        }`}></i>
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">AI 判定註解</span>
                      </div>
                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">
                        {selectedCard.reasoning || "AI 正在分析判定邏輯..."}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label={selectedCard.category === 'employer' ? "Company Name" : "Institution Name"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email Address" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category === 'employer' ? (
                       <DataEntry label="Industry" value={selectedCard.industry} icon="fa-industry" />
                    ) : (
                       <DataEntry label="Department" value={selectedCard.department} icon="fa-sitemap" />
                    )}
                    <DataEntry label="Country / Territory" value={selectedCard.country} icon="fa-globe" />
                  </div>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-red-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in slide-in-from-bottom-10">
          <i className="fa-solid fa-triangle-exclamation"></i>
          <span className="text-sm font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

