                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">{selectedCard.reasoning}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label="Source (資料來源)" value={selectedCard.source} icon="fa-database" />
                    <DataEntry label={selectedCard.category === 'employer' ? "Company" : "Institution"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category !== 'employer' && <><DataEntry label="Department" value={selectedCard.department} icon="fa-sitemap" /><DataEntry label="Subject" value={selectedCard.subject} icon="fa-book" /></>}
                    {selectedCard.category === 'employer' && <DataEntry label="Industry" value={selectedCard.industry} icon="fa-industry" />}
                    <DataEntry label="Country or" value={selectedCard.country} icon="fa-globe" />
                    <DataEntry label="Phone (Optional)" value={selectedCard.phone} icon="fa-phone" />
