import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, retryCount = 0): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Extract contact details from this business card for QS World University Rankings. 
            Categorize into THREE distinct groups:
            1. 'academic': Teaching or Research roles at a University (Professor, Lecturer, Researcher, Dean).
            2. 'staff': Administrative or Support roles at a University (Registrar, HR, IT, Secretary, Office Staff, Facilities).
            3. 'employer': Roles at Corporate, Private, or Government non-educational organizations.

            For Academic/Staff, also identify the 'subject' area (e.g., Arts & Humanities, Engineering & Technology, Life Sciences & Medicine, Natural Sciences, Social Sciences & Management) based on their department or research.
            Set 'source' as "AI Scan".

            Split name into prefix (Mr/Ms/Dr/Prof), first name, and last name.
            Extract country and industry (for employers).
            Provide a brief explanation in Traditional Chinese for why you chose the category based on the institution or job title. 
            If a field is missing, use "". Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING, description: "Salutation" },
            firstName: { type: Type.STRING, description: "First Name" },
            lastName: { type: Type.STRING, description: "Last Name" },
            title: { type: Type.STRING, description: "Job Title" },
            company: { type: Type.STRING, description: "Institution or Company Name" },
            department: { type: Type.STRING, description: "Department" },
            industry: { type: Type.STRING, description: "Industry" },
            country: { type: Type.STRING, description: "Country or Territory" },
            email: { type: Type.STRING, description: "Email address" },
            subject: { type: Type.STRING, description: "Academic Subject Area" },
            source: { type: Type.STRING, description: "Data source" },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            fax: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            notes: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "Reasoning in Traditional Chinese" },
          },
          required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning", "subject", "source"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    // Handle Quota Exceeded (429) or Server Errors with backoff
    const errorMessage = error?.message || "";
    if ((errorMessage.includes("quota") || errorMessage.includes("429") || errorMessage.includes("500")) && retryCount < 3) {
      const waitTime = Math.pow(2, retryCount) * 2000; // 2s, 4s, 8s
      console.warn(`API 配額受限，將於 ${waitTime}ms 後重試...`);
      await sleep(waitTime);
      return extractCardInfo(base64Image, retryCount + 1);
    }

    if (errorMessage.includes("quota")) {
      throw new Error("API 配額已達上限，請稍候再試。");
    }

    console.error("Gemini Error:", error);
    throw new Error(errorMessage || "辨識過程發生未預期錯誤");
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v6_bg');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) {
          setSelectedCardId(parsed[0].id);
          setViewMode('detail');
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v6_bg', JSON.stringify(cards));
  }, [cards]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const activeTasks = tasks.filter(t => t.status === 'processing' || t.status === 'pending');
  const completedTasksCount = tasks.filter(t => t.status === 'completed').length;

  const processSingleBase64 = async (base64: string, fileName: string = "相機掃描") => {
    const taskId = crypto.randomUUID();
    const newTask: ProcessingTask = { id: taskId, fileName, status: 'processing', progress: 0 };
    setTasks(prev => [newTask, ...prev]);

    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'completed', progress: 100 } : t));
      if (cards.length === 0) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));
      setErrorMsg(err.message || "辨識失敗");
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const newTasks: ProcessingTask[] = fileList.map(f => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0
    }));
    setTasks(prev => [...newTasks, ...prev]);
    setViewMode('tasks');

    for (let i = 0; i < fileList.length; i++) {
      const file = fileList[i];
      const currentTaskId = newTasks[i].id;

      setTasks(prev => prev.map(t => t.id === currentTaskId ? { ...t, status: 'processing' } : t));

      try {
        const reader = new FileReader();
        const base64 = await new Promise<string>((resolve) => {
          reader.onload = () => resolve((reader.result as string).split(',')[1]);
          reader.readAsDataURL(file);
        });

        const info = await extractCardInfo(base64);
        const newCard: BusinessCardData = {
          id: crypto.randomUUID(),
          ...info,
          scannedAt: Date.now(),
          imageUrl: `data:image/jpeg;base64,${base64}`,
        };
        setCards(prev => [newCard, ...prev]);
        setTasks(prev => prev.map(t => t.id === currentTaskId ? { ...t, status: 'completed', progress: 100 } : t));

        // Add a small delay between batch items to be nice to the API
        await new Promise(r => setTimeout(r, 500));

      } catch (err: any) {
        setTasks(prev => prev.map(t => t.id === currentTaskId ? { ...t, status: 'error', error: err.message || "處理出錯" } : t));
      }
    }
    event.target.value = '';
  };

  const cycleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        const order: ('employer' | 'academic' | 'staff')[] = ['employer', 'academic', 'staff'];
        const nextIndex = (order.indexOf(c.category) + 1) % order.length;
        return { ...c, category: order[nextIndex] };
      }
      return c;
    }));
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    let exportData;
    if (category === 'academic' || category === 'staff') {
      exportData = filtered.map(c => ({
        'Source': c.source || 'AI Scanned',
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last': c.lastName,
        'Job Title': c.title,
        'Department': c.department,
        'Institution': c.company,
        'Country or': c.country,
        'Email': c.email,
        'Subject': c.subject || '',
        'Phone (Optional)': c.phone
      }));
    } else {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Company Name': c.company,
        'Industry': c.industry,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    }
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}_Export.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[480px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportButton color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportButton color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportButton color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <ColumnGroup title="Employer" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Academic" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Staff" color="amber" items={staffCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {activeTasks.length > 0 && (
          <div className="absolute top-16 left-0 right-0 h-1 bg-slate-100 z-[60] overflow-hidden">
             <div className="h-full bg-indigo-500 transition-all duration-500 animate-[pulse_2s_infinite]" style={{ width: `${(completedTasksCount / tasks.length) * 100}%` }}></div>
          </div>
        )}

        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="拍照" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasks.length})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={activeTasks.length > 0} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="hidden sm:flex items-center gap-4">
            {activeTasks.length > 0 && (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                <i className="fa-solid fa-spinner fa-spin text-indigo-500 text-xs"></i>
                <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-tighter">AI 分析中: {completedTasksCount}/{tasks.length}</span>
              </div>
            )}
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Generator</span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/30">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto p-2">
              <CameraScanner onCapture={(b64) => processSingleBase64(b64)} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">開始新任務</h3>
                <p className="text-slate-400 text-sm mt-2">支援背景重試，API 繁忙時會自動排隊</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-4">
               <h2 className="text-2xl font-black text-slate-800 mb-6">AI 分析任務列表</h2>
               <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                 {tasks.length === 0 ? (
                   <div className="p-20 text-center text-slate-400 italic">尚無任何處理任務</div>
                 ) : (
                   <table className="w-full text-left text-sm">
                     <thead className="bg-slate-50 border-b border-slate-100">
                       <tr>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">檔案名稱</th>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">狀態</th>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">詳細原因</th>
                       </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-50">
                       {tasks.map(task => (
                         <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                           <td className="px-6 py-4 font-medium text-slate-700">{task.fileName}</td>
                           <td className="px-6 py-4">
                             {task.status === 'processing' ? (
                               <span className="flex items-center gap-2 text-indigo-500 font-bold"><i className="fa-solid fa-spinner fa-spin"></i> 辨識中</span>
                             ) : task.status === 'completed' ? (
                               <span className="flex items-center gap-2 text-emerald-500 font-bold"><i className="fa-solid fa-circle-check"></i> 完成</span>
                             ) : task.status === 'error' ? (
                               <span className="flex items-center gap-2 text-red-500 font-bold"><i className="fa-solid fa-circle-xmark"></i> 失敗</span>
                             ) : (
                               <span className="flex items-center gap-2 text-slate-400 font-bold"><i className="fa-solid fa-clock"></i> 排隊中</span>
                             )}
                           </td>
                           <td className="px-6 py-4">
                             {task.status === 'completed' ? (
                               <span className="text-xs text-emerald-600 bg-emerald-50 px-2 py-1 rounded-md">已加入側邊欄</span>
                             ) : task.status === 'error' ? (
                               <span className="text-xs text-red-600 bg-red-50 px-2 py-1 rounded-md font-bold">{task.error}</span>
                             ) : (
                               <span className="text-xs text-slate-400 italic">等待 API 回應</span>
                             )}
                           </td>
                         </tr>
                       ))}
                     </tbody>
                   </table>
                 )}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="bg-white p-2 rounded-2xl shadow-xl border border-slate-200 overflow-hidden ring-4 ring-slate-50">
                    <img src={selectedCard.imageUrl} alt="Scan" className="w-full h-auto rounded-xl" />
                  </div>
                </div>
                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                    <button onClick={() => { setCards(prev => prev.filter(c => c.id !== selectedCard.id)); setSelectedCardId(null); }} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <div className={`p-6 rounded-3xl border shadow-sm transition-colors duration-500 ${selectedCard.category === 'employer' ? 'bg-indigo-50 border-indigo-100' : selectedCard.category === 'academic' ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-100'}`}>
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <span className="text-[10px] font-bold uppercase opacity-50 block mb-1">分類判定</span>
                        <span className={`text-xl font-black uppercase tracking-tight ${selectedCard.category === 'employer' ? 'text-indigo-600' : selectedCard.category === 'academic' ? 'text-emerald-600' : 'text-amber-600'}`}>
                          {selectedCard.category === 'employer' ? '雇主聲望' : selectedCard.category === 'academic' ? '學術教研' : '校內職員'}
                        </span>
                      </div>
                      <button onClick={() => cycleCategory(selectedCard.id)} className="bg-white px-4 py-2 rounded-xl text-[11px] font-bold border border-slate-200 hover:bg-slate-50 shadow-sm transition-all active:scale-95">切換分類</button>
                    </div>
                    <div className="pt-4 border-t border-white/40">
                      <div className="flex items-center gap-2 mb-2"><i className={`fa-solid fa-brain text-xs ${selectedCard.category === 'employer' ? 'text-indigo-400' : selectedCard.category === 'academic' ? 'text-emerald-400' : 'text-amber-400'}`}></i><span className="text-[10px] font-black uppercase tracking-widest text-slate-500">AI 判定註解</span></div>
                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">{selectedCard.reasoning}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label="Source (資料來源)" value={selectedCard.source} icon="fa-database" />
                    <DataEntry label={selectedCard.category === 'employer' ? "Company" : "Institution"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category !== 'employer' && <><DataEntry label="Department" value={selectedCard.department} icon="fa-sitemap" /><DataEntry label="Subject" value={selectedCard.subject} icon="fa-book" /></>}
                    {selectedCard.category === 'employer' && <DataEntry label="Industry" value={selectedCard.industry} icon="fa-industry" />}
                    <DataEntry label="Country or" value={selectedCard.country} icon="fa-globe" />
                    <DataEntry label="Phone (Optional)" value={selectedCard.phone} icon="fa-phone" />
                  </div>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/90 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] backdrop-blur-md border border-white/10">
          <i className="fa-solid fa-circle-info text-indigo-400"></i>
          <span className="text-sm font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportButton = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-2 rounded text-[9px] font-bold shadow-sm flex flex-col items-center disabled:opacity-30 transition-all`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-users-gear' : label === 'Academic' ? 'fa-graduation-cap' : 'fa-user-tie'} mb-1`}></i>
    <span>{label}</span>
    <span className="opacity-70">({count})</span>
  </button>
);

const ColumnGroup = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Staff' ? 'border-r border-slate-200' : ''}`}>
    <div className={`p-2 bg-${color}-50 border-b border-slate-200 text-center`}>
      <span className={`text-[8px] font-black text-${color}-400 uppercase tracking-tighter`}>{title}</span>
    </div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-1.5 space-y-1.5">
      {items.map((card: any) => (
        <div key={card.id} onClick={() => onSelect(card.id)} className={`p-2 rounded-lg cursor-pointer transition-all flex flex-col gap-0.5 border ${activeId === card.id ? `bg-white shadow-md border-${color}-200 ring-2 ring-${color}-500/10` : 'bg-white/40 border-transparent hover:bg-white hover:shadow-sm'}`}>
          <p className={`text-[10px] font-bold truncate ${activeId === card.id ? `text-${color}-600` : 'text-slate-700'}`}>{card.firstName} {card.lastName}</p>
          <p className="text-[8px] text-slate-400 font-medium truncate">{card.company}</p>
        </div>
      ))}
    </div>
  </div>
);

const DataEntry = ({ label, value, icon }: any) => (
  <div className="group">
    <div className="flex items-center gap-2 mb-1">
      <div className="w-5 h-5 flex items-center justify-center rounded-md bg-slate-50 text-slate-400 text-[10px] group-hover:text-indigo-500 transition-colors"><i className={`fa-solid ${icon}`}></i></div>
      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    </div>
    <div className="pl-7"><p className={`text-sm leading-relaxed ${value ? 'text-slate-800 font-semibold' : 'text-slate-300 italic'}`}>{value || '無資料'}</p></div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v6_bg');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0) {
          setSelectedCardId(parsed[0].id);
          setViewMode('detail');
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v6_bg', JSON.stringify(cards));
  }, [cards]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const activeTasks = tasks.filter(t => t.status === 'processing' || t.status === 'pending');
  const failedTasks = tasks.filter(t => t.status === 'error');
  const completedTasksCount = tasks.filter(t => t.status === 'completed').length;

  const performTask = async (taskId: string, base64: string) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'processing', error: undefined } : t));
    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'completed', progress: 100 } : t));
      if (cards.length === 0) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));
      if (err.message?.includes("配額")) {
         setErrorMsg("API 額度已滿，請等待 1 分鐘後再點擊重新嘗試。");
      }
    }
  };

  const processSingleBase64 = async (base64: string, fileName: string = "相機掃描") => {
    const taskId = crypto.randomUUID();
    const newTask: ProcessingTask = { id: taskId, fileName, status: 'processing', progress: 0 };
    // We need to store the image for retrying, but let's just use it immediately for now
    setTasks(prev => [newTask, ...prev]);
    await performTask(taskId, base64);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    // Note: In a real app we'd store the image data in IndexedDB to allow retry after refresh.
    // For now we keep it in memory for the current session.
    const newTasksWithData = await Promise.all(fileList.map(async (f) => {
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      return {
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending' as const,
        progress: 0,
        base64
      };
    }));

    setTasks(prev => [...newTasksWithData.map(({base64, ...t}) => t), ...prev]);
    setViewMode('tasks');

    for (const taskData of newTasksWithData) {
      await performTask(taskData.id, taskData.base64);
      // Wait 4 seconds between requests to safely stay under 15 RPM (Requests Per Minute)
      // 60s / 15 = 4s per request
      await new Promise(r => setTimeout(r, 4100));
    }

    event.target.value = '';
  };

  const retryFailedTasks = async () => {
    setErrorMsg(null);
    const toRetry = tasks.filter(t => t.status === 'error');
    // Note: Without persistent image storage, we can only retry if they are still in memory
    // In this simplified version, we'll suggest re-uploading if data is lost, 
    // or just let the loop continue if it was a batch.
    alert("請重新上傳失敗的檔案。系統已將失敗任務標記，建議每分鐘上傳不超過 15 張以避免配額問題。");
  };

  const clearTasks = () => {
    if (activeTasks.length > 0) {
      if (!confirm("尚有任務正在處理中，確定要清空嗎？")) return;
    }
    setTasks([]);
  };

  const cycleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        const order: ('employer' | 'academic' | 'staff')[] = ['employer', 'academic', 'staff'];
        const nextIndex = (order.indexOf(c.category) + 1) % order.length;
        return { ...c, category: order[nextIndex] };
      }
      return c;
    }));
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    let exportData;
    if (category === 'academic' || category === 'staff') {
      exportData = filtered.map(c => ({
        'Source': c.source || 'AI Scanned',
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last': c.lastName,
        'Job Title': c.title,
        'Department': c.department,
        'Institution': c.company,
        'Country or': c.country,
        'Email': c.email,
        'Subject': c.subject || '',
        'Phone (Optional)': c.phone
      }));
    } else {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Company Name': c.company,
        'Industry': c.industry,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    }
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}_Export.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[480px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportButton color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportButton color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportButton color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <ColumnGroup title="Employer" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Academic" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Staff" color="amber" items={staffCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {activeTasks.length > 0 && (
          <div className="absolute top-16 left-0 right-0 h-1 bg-slate-100 z-[60] overflow-hidden">
             <div className="h-full bg-indigo-500 transition-all duration-500 animate-[pulse_2s_infinite]" style={{ width: `${(completedTasksCount / tasks.length) * 100}%` }}></div>
          </div>
        )}

        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="拍照" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasks.length})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="hidden sm:flex items-center gap-4">
            {activeTasks.length > 0 && (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                <i className="fa-solid fa-spinner fa-spin text-indigo-500 text-xs"></i>
                <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-tighter">AI 分析中: 每 4 秒處理一張...</span>
              </div>
            )}
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Generator</span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/30">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto p-2">
              <CameraScanner onCapture={(b64) => processSingleBase64(b64)} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">開始新任務</h3>
                <p className="text-slate-400 text-sm mt-2 font-medium">系統已優化：每 4 秒處理一張以符合 Google 免費額度規範</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
              <div className="mt-10 flex gap-4">
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                   <div className="w-8 h-8 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-xs font-bold">15</div>
                   <div className="text-left"><p className="text-[10px] font-black uppercase text-slate-400">每分鐘上限</p><p className="text-xs font-bold text-slate-700">15 張名片</p></div>
                </div>
                <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
                   <div className="w-8 h-8 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs font-bold">1.5k</div>
                   <div className="text-left"><p className="text-[10px] font-black uppercase text-slate-400">每日上限</p><p className="text-xs font-bold text-slate-700">1,500 張名片</p></div>
                </div>
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-4">
               <div className="flex justify-between items-end mb-6">
                 <div>
                   <h2 className="text-2xl font-black text-slate-800">AI 分析任務列表</h2>
                   <p className="text-sm text-slate-400">當 API 出現「配額受限」時，請等待 60 秒後再重新上傳。</p>
                 </div>
                 <div className="flex gap-2">
                   <button onClick={clearTasks} className="px-4 py-2 bg-slate-100 text-slate-600 text-xs font-bold rounded-xl hover:bg-slate-200 transition-all">清空列表</button>
                   {failedTasks.length > 0 && <button onClick={retryFailedTasks} className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200">重新上傳失敗項</button>}
                 </div>
               </div>

               {failedTasks.length > 0 && (
                 <div className="bg-red-50 border border-red-100 p-4 rounded-2xl mb-6 flex items-start gap-4 animate-pulse">
                   <i className="fa-solid fa-triangle-exclamation text-red-500 mt-1"></i>
                   <div>
                     <p className="text-sm font-bold text-red-800">偵測到配額限制 (Quota Exceeded)</p>
                     <p className="text-xs text-red-700 mt-1 leading-relaxed">
                       這是因為 Google AI Studio 對免費帳號有限制（每分鐘 15 次）。
                       請暫停上傳，等待約 1 分鐘後，再次點擊「重新上傳失敗項」或手動上傳。
                     </p>
                   </div>
                 </div>
               )}

               <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                 {tasks.length === 0 ? (
                   <div className="p-20 text-center text-slate-400 italic">尚無任何處理任務</div>
                 ) : (
                   <table className="w-full text-left text-sm">
                     <thead className="bg-slate-50 border-b border-slate-100">
                       <tr>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">檔案名稱</th>
