                           <td className="px-6 py-4 font-medium text-slate-700">{task.fileName}</td>
                           <td className="px-6 py-4">
                             {task.status === 'processing' ? (
                               <span className="flex items-center gap-2 text-indigo-500 font-bold"><i className="fa-solid fa-spinner fa-spin"></i> 辨識中</span>
                             ) : task.status === 'completed' ? (
                               <span className="flex items-center gap-2 text-emerald-500 font-bold"><i className="fa-solid fa-circle-check"></i> 完成</span>
                             ) : task.status === 'error' ? (
                               <span className="flex items-center gap-2 text-red-500 font-bold"><i className="fa-solid fa-circle-xmark"></i> 失敗</span>
                             ) : (
                               <span className="flex items-center gap-2 text-slate-400 font-bold"><i className="fa-solid fa-clock"></i> 排隊中</span>
                             )}
                           </td>
                           <td className="px-6 py-4">
                             {task.status === 'completed' ? (
