export default App;

export interface BusinessCardData {
  id: string;
  prefix: string; // Mr, Ms, Dr, etc. (Maps to Title)
  firstName: string;
  lastName: string; // Maps to Last
  title: string; // Job Title
  company: string; // Institution Name
  department: string;
  industry: string; // For Employers
  country: string; // Country or
  email: string;
  phone: string; // Phone (Optional)
  subject: string; // Academic Subject Area
  source: string; // Data Source
  mobile: string;
  fax: string;
  website: string;
  address: string;
  notes: string;
  category: 'employer' | 'academic' | 'staff';
  reasoning: string; 
  scannedAt: number;
  imageUrl?: string;
}

export interface ProcessingTask {
  id: string;
  fileName: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  progress: number;
  error?: string;
  base64?: string; // Temporarily store for retries
}

export type ScanStatus = 'idle' | 'busy' | 'error';

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence for cards
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v7');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v7', JSON.stringify(cards));
  }, [cards]);

  // Cooldown timer logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
    }
  }, [cooldown, isPaused]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const activeTasks = tasks.filter(t => t.status === 'processing' || t.status === 'pending');
  const failedTasks = tasks.filter(t => t.status === 'error');
  const completedTasksCount = tasks.filter(t => t.status === 'completed').length;

  const performTask = async (taskId: string, base64: string) => {
    if (isPaused) return;

    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'processing', error: undefined } : t));

    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      // Remove base64 after success to save memory
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }
    } catch (err: any) {
      const isQuota = err.message?.includes("配額") || err.message?.includes("quota") || err.message?.includes("429");

      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));

      if (isQuota) {
        setErrorMsg("API 配額已達上限！系統將自動暫停 60 秒以冷卻。");
        setIsPaused(true);
        setCooldown(60);
      }
    }
  };

  const processSingleBase64 = async (base64: string, fileName: string = "相機掃描") => {
    const taskId = crypto.randomUUID();
    const newTask: ProcessingTask = { id: taskId, fileName, status: 'pending', progress: 0, base64 };
    setTasks(prev => [newTask, ...prev]);
    setViewMode('tasks');
    await performTask(taskId, base64);
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const newTasks: ProcessingTask[] = [];

    for (const f of fileList) {
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64
      });
    }

    setTasks(prev => [...newTasks, ...prev]);
    setViewMode('tasks');
    event.target.value = '';
  };

  // Automated Queue Processing
  useEffect(() => {
    const processQueue = async () => {
      if (isPaused) return;
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask && nextTask.base64) {
        await performTask(nextTask.id, nextTask.base64);
        // Minimum gap to stay within 15 RPM
        await new Promise(r => setTimeout(r, 4200));
      }
    };
    processQueue();
  }, [tasks, isPaused]);

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) {
      alert("此任務的原始圖片已遺失，請重新上傳。");
      return;
    }
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const retryAllFailed = () => {
    setTasks(prev => prev.map(t => t.status === 'error' ? { ...t, status: 'pending', error: undefined } : t));
    setIsPaused(false);
    setCooldown(0);
  };

  const clearTasks = () => {
    if (activeTasks.length > 0) {
      if (!confirm("尚有任務正在處理中，確定要清空嗎？")) return;
    }
    setTasks([]);
  };

  const cycleCategory = (id: string) => {
    setCards(prev => prev.map(c => {
      if (c.id === id) {
        const order: ('employer' | 'academic' | 'staff')[] = ['employer', 'academic', 'staff'];
        const nextIndex = (order.indexOf(c.category) + 1) % order.length;
        return { ...c, category: order[nextIndex] };
      }
      return c;
    }));
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    let exportData;
    if (category === 'academic' || category === 'staff') {
      exportData = filtered.map(c => ({
        'Source': c.source || 'AI Scanned',
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last': c.lastName,
        'Job Title': c.title,
        'Department': c.department,
        'Institution': c.company,
        'Country or': c.country,
        'Email': c.email,
        'Subject': c.subject || '',
        'Phone (Optional)': c.phone
      }));
    } else {
      exportData = filtered.map(c => ({
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': c.lastName,
        'Job Title': c.title,
        'Company Name': c.company,
        'Industry': c.industry,
        'Country/Territory': c.country,
        'Email Address': c.email
      }));
    }
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}_Export.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[480px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Groups</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportButton color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportButton color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportButton color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <ColumnGroup title="Employer" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Academic" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
          <ColumnGroup title="Staff" color="amber" items={staffCards} activeId={selectedCardId} onSelect={(id:string) => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        {activeTasks.length > 0 && (
          <div className="absolute top-16 left-0 right-0 h-1 bg-slate-100 z-[60] overflow-hidden">
             <div className="h-full bg-indigo-500 transition-all duration-500 animate-[pulse_2s_infinite]" style={{ width: `${(completedTasksCount / tasks.length) * 100}%` }}></div>
          </div>
        )}

        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-6">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400 p-2"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="拍照" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasks.length})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="hidden sm:flex items-center gap-4">
            {isPaused ? (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-100">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs animate-spin"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">配額冷卻中: {cooldown}s</span>
              </div>
            ) : activeTasks.length > 0 ? (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                <i className="fa-solid fa-spinner fa-spin text-indigo-500 text-xs"></i>
                <span className="text-[10px] font-bold text-indigo-600 uppercase">佇列處理中...</span>
              </div>
            ) : null}
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"></div>
              <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">QS Hub Generator</span>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 bg-slate-50/30">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto p-2">
              <CameraScanner onCapture={(b64) => processSingleBase64(b64)} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-2xl p-20 border-2 border-dashed border-slate-300 rounded-[3rem] hover:border-indigo-400 hover:bg-indigo-50/50 transition-all cursor-pointer group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">批量名片辨識</h3>
                <p className="text-slate-400 text-sm mt-2 font-medium italic">系統會自動排隊，每分鐘處理 15 張以避免配額錯誤</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
              <div className="mt-10 flex gap-4">
                <QuotaCard title="每分鐘上限" value="15 張" icon="fa-stopwatch" color="emerald" />
                <QuotaCard title="每日上限" value="1,500 張" icon="fa-calendar-day" color="blue" />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-4">
               <div className="flex justify-between items-end mb-6">
                 <div>
                   <h2 className="text-2xl font-black text-slate-800">辨識任務管理</h2>
                   <p className="text-sm text-slate-400">所有上傳的檔案會在此排隊，API 繁忙時會自動暫停並恢復。</p>
                 </div>
                 <div className="flex gap-2">
                   <button onClick={clearTasks} className="px-4 py-2 bg-slate-100 text-slate-600 text-xs font-bold rounded-xl hover:bg-slate-200 transition-all">清空列表</button>
                   {failedTasks.length > 0 && <button onClick={retryAllFailed} className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-200">重試所有失敗項</button>}
                 </div>
               </div>

               {isPaused && (
                 <div className="bg-red-50 border border-red-100 p-6 rounded-3xl mb-6 flex items-start gap-5 shadow-sm">
                   <div className="w-12 h-12 bg-red-100 rounded-2xl flex items-center justify-center text-red-500 text-xl shrink-0"><i className="fa-solid fa-clock-rotate-left"></i></div>
                   <div>
                     <p className="text-lg font-bold text-red-800">配額暫時耗盡</p>
                     <p className="text-sm text-red-700 mt-1 leading-relaxed">
                       因為頻率過高，Google API 正暫時拒絕請求。系統已暫停運作，<span className="font-black text-red-900 underline">將在 {cooldown} 秒後自動重新開始辨識</span>。
                       您可以稍作休息，不用關閉網頁。
                     </p>
                   </div>
                 </div>
               )}

               <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                 {tasks.length === 0 ? (
                   <div className="p-20 text-center text-slate-400 italic">尚無任何處理任務</div>
                 ) : (
                   <table className="w-full text-left text-sm">
                     <thead className="bg-slate-50 border-b border-slate-100">
                       <tr>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">檔案名稱</th>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">目前的狀態</th>
                         <th className="px-6 py-4 font-bold text-slate-500 uppercase text-[10px]">詳細說明 / 操作</th>
                       </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-50">
                       {tasks.map(task => (
                         <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                           <td className="px-6 py-4 font-medium text-slate-700">{task.fileName}</td>
                           <td className="px-6 py-4">
                             <StatusBadge status={task.status} />
                           </td>
                           <td className="px-6 py-4">
                             {task.status === 'completed' ? (
                               <span className="text-xs text-emerald-600 bg-emerald-50 px-2 py-1 rounded-md font-medium">辨識成功</span>
                             ) : task.status === 'error' ? (
                               <div className="flex items-center gap-3">
                                 <span className="text-xs text-red-600 font-bold max-w-[200px] truncate">{task.error}</span>
                                 <button onClick={() => retryTask(task)} className="text-[10px] bg-indigo-50 text-indigo-600 px-2 py-1 rounded hover:bg-indigo-100 font-black">重試</button>
                               </div>
                             ) : (
                               <span className="text-xs text-slate-400 italic">排隊中...</span>
                             )}
                           </td>
                         </tr>
                       ))}
                     </tbody>
                   </table>
                 )}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                <div className="space-y-6">
                  <div className="bg-white p-2 rounded-2xl shadow-xl border border-slate-200 overflow-hidden ring-4 ring-slate-50">
                    <img src={selectedCard.imageUrl} alt="Scan" className="w-full h-auto rounded-xl" />
                  </div>
                </div>
                <div className="space-y-6">
                  <div className="flex justify-between items-center border-b border-slate-100 pb-4">
                    <h1 className="text-3xl font-black text-slate-900 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                    <button onClick={() => { setCards(prev => prev.filter(c => c.id !== selectedCard.id)); setSelectedCardId(null); }} className="text-slate-300 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <div className={`p-6 rounded-3xl border shadow-sm transition-colors duration-500 ${selectedCard.category === 'employer' ? 'bg-indigo-50 border-indigo-100' : selectedCard.category === 'academic' ? 'bg-emerald-50 border-emerald-100' : 'bg-amber-50 border-amber-100'}`}>
                    <div className="flex items-center justify-between mb-4">
                      <div>
                        <span className="text-[10px] font-bold uppercase opacity-50 block mb-1">分類判定</span>
                        <span className={`text-xl font-black uppercase tracking-tight ${selectedCard.category === 'employer' ? 'text-indigo-600' : selectedCard.category === 'academic' ? 'text-emerald-600' : 'text-amber-600'}`}>
                          {selectedCard.category === 'employer' ? '雇主聲望' : selectedCard.category === 'academic' ? '學術教研' : '校內職員'}
                        </span>
                      </div>
                      <button onClick={() => cycleCategory(selectedCard.id)} className="bg-white px-4 py-2 rounded-xl text-[11px] font-bold border border-slate-200 hover:bg-slate-50 shadow-sm transition-all active:scale-95">切換分類</button>
                    </div>
                    <div className="pt-4 border-t border-white/40">
                      <div className="flex items-center gap-2 mb-2"><i className={`fa-solid fa-brain text-xs ${selectedCard.category === 'employer' ? 'text-indigo-400' : selectedCard.category === 'academic' ? 'text-emerald-400' : 'text-amber-400'}`}></i><span className="text-[10px] font-black uppercase tracking-widest text-slate-500">AI 判定註解</span></div>
                      <p className="text-sm text-slate-600 leading-relaxed font-medium bg-white/50 p-3 rounded-xl border border-white/60">{selectedCard.reasoning}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-1 gap-5 bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
                    <DataEntry label="Source (資料來源)" value={selectedCard.source} icon="fa-database" />
                    <DataEntry label={selectedCard.category === 'employer' ? "Company" : "Institution"} value={selectedCard.company} icon="fa-building" />
                    <DataEntry label="Job Title" value={selectedCard.title} icon="fa-id-badge" />
                    <DataEntry label="Email" value={selectedCard.email} icon="fa-envelope" />
                    {selectedCard.category !== 'employer' && <><DataEntry label="Department" value={selectedCard.department} icon="fa-sitemap" /><DataEntry label="Subject" value={selectedCard.subject} icon="fa-book" /></>}
                    {selectedCard.category === 'employer' && <DataEntry label="Industry" value={selectedCard.industry} icon="fa-industry" />}
                    <DataEntry label="Country or" value={selectedCard.country} icon="fa-globe" />
                    <DataEntry label="Phone (Optional)" value={selectedCard.phone} icon="fa-phone" />
                  </div>
                </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900/90 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] backdrop-blur-md border border-white/10 max-w-lg animate-in fade-in slide-in-from-bottom-2">
          <i className="fa-solid fa-circle-info text-indigo-400 text-xl"></i>
          <span className="text-sm font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-50 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

// Sub-components
const QuotaCard = ({ title, value, icon, color }: any) => (
  <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-3">
     <div className={`w-8 h-8 rounded-full bg-${color}-100 text-${color}-600 flex items-center justify-center text-xs font-bold`}><i className={`fa-solid ${icon}`}></i></div>
     <div className="text-left"><p className="text-[10px] font-black uppercase text-slate-400">{title}</p><p className="text-xs font-bold text-slate-700">{value}</p></div>
  </div>
);

const StatusBadge = ({ status }: { status: ProcessingTask['status'] }) => {
  switch (status) {
    case 'processing': return <span className="flex items-center gap-2 text-indigo-500 font-bold"><i className="fa-solid fa-spinner fa-spin"></i> 辨識中</span>;
    case 'completed': return <span className="flex items-center gap-2 text-emerald-500 font-bold"><i className="fa-solid fa-circle-check"></i> 完成</span>;
    case 'error': return <span className="flex items-center gap-2 text-red-500 font-bold"><i className="fa-solid fa-circle-xmark"></i> 失敗</span>;
    default: return <span className="flex items-center gap-2 text-slate-400 font-bold"><i className="fa-solid fa-clock"></i> 排隊中</span>;
  }
};

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportButton = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-2 rounded text-[9px] font-bold shadow-sm flex flex-col items-center disabled:opacity-30 transition-all`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-users-gear' : label === 'Academic' ? 'fa-graduation-cap' : 'fa-user-tie'} mb-1`}></i>
    <span>{label}</span>
    <span className="opacity-70">({count})</span>
  </button>
);

const ColumnGroup = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Staff' ? 'border-r border-slate-200' : ''}`}>
    <div className={`p-2 bg-${color}-50 border-b border-slate-200 text-center`}>
      <span className={`text-[8px] font-black text-${color}-400 uppercase tracking-tighter`}>{title}</span>
    </div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-1.5 space-y-1.5">
      {items.map((card: any) => (
        <div key={card.id} onClick={() => onSelect(card.id)} className={`p-2 rounded-lg cursor-pointer transition-all flex flex-col gap-0.5 border ${activeId === card.id ? `bg-white shadow-md border-${color}-200 ring-2 ring-${color}-500/10` : 'bg-white/40 border-transparent hover:bg-white hover:shadow-sm'}`}>
          <p className={`text-[10px] font-bold truncate ${activeId === card.id ? `text-${color}-600` : 'text-slate-700'}`}>{card.firstName} {card.lastName}</p>
          <p className="text-[8px] text-slate-400 font-medium truncate">{card.company}</p>
        </div>
      ))}
    </div>
  </div>
);

const DataEntry = ({ label, value, icon }: any) => (
  <div className="group">
    <div className="flex items-center gap-2 mb-1">
      <div className="w-5 h-5 flex items-center justify-center rounded-md bg-slate-50 text-slate-400 text-[10px] group-hover:text-indigo-500 transition-colors"><i className={`fa-solid ${icon}`}></i></div>
      <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</span>
    </div>
    <div className="pl-7"><p className={`text-sm leading-relaxed ${value ? 'text-slate-800 font-semibold' : 'text-slate-300 italic'}`}>{value || '無資料'}</p></div>
  </div>
);

export default App;

export interface BusinessCardData {
  id: string;
  prefix: string;
  firstName: string;
  lastName: string;
  title: string;
  company: string;
  department: string;
  industry: string;
  country: string;
  email: string;
  phone: string;
  subject: string;
  source: string;
  mobile: string;
  fax: string;
  website: string;
  address: string;
  notes: string;
  category: 'employer' | 'academic' | 'staff';
  reasoning: string; 
  scannedAt: number;
  imageUrl?: string;
}

export interface ProcessingTask {
  id: string;
  fileName: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  progress: number;
  error?: string;
  base64?: string;
  batchIndex: number; // For grouping 15 by 15
}

export type ScanStatus = 'idle' | 'busy' | 'error';

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ScanStatus, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentWindow, setProcessedInCurrentWindow] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v7');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v7', JSON.stringify(cards));
  }, [cards]);

  // Cooldown timer
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentWindow(0);
    }
  }, [cooldown, isPaused]);

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const activeTasks = tasks.filter(t => t.status === 'processing' || t.status === 'pending');
  const failedTasks = tasks.filter(t => t.status === 'error');
  const completedTasksCount = tasks.filter(t => t.status === 'completed').length;

  // Group tasks for UI
  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (taskId: string, base64: string) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'processing', error: undefined } : t));

    try {
      const info = await extractCardInfo(base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${base64}`,
      };
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentWindow(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }
    } catch (err: any) {
      const isQuota = err.message?.includes("配額") || err.message?.includes("quota") || err.message?.includes("429");
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));

      if (isQuota) {
        setIsPaused(true);
        setCooldown(60);
      }
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const reader = new FileReader();
      const base64 = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      // Calculate batch index based on existing tasks and current file position
      const globalIndex = startIndex + i;
      const batchIndex = Math.floor(globalIndex / 15) + 1;

      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  // Automated Queue Logic with Batching
  useEffect(() => {
    const processQueue = async () => {
      if (isPaused) return;

      // If we've hit 15 in this cycle, wait 60s
      if (processedInCurrentWindow >= 15) {
        setIsPaused(true);
        setCooldown(60);
        return;
      }

      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask && nextTask.base64) {
        await performTask(nextTask.id, nextTask.base64);
        // Small internal gap for stability
        await new Promise(r => setTimeout(r, 1500));
      }
    };
    processQueue();
  }, [tasks, isPaused, processedInCurrentWindow]);

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) {
      alert("原始圖片已遺失，請重新上傳。");
      return;
    }
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasks.length > 0 && !confirm("確定清空進行中的任務？")) return;
    setTasks([]);
    setProcessedInCurrentWindow(0);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3] relative">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[400px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Data Hub</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasks.length})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {isPaused && (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-100 animate-pulse">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">配額緩衝中: {cooldown}s</span>
              </div>
            )}
            {!isPaused && activeTasks.length > 0 && (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-100">
                <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-ping"></span>
                <span className="text-[10px] font-bold text-indigo-600 uppercase">目前批次: {processedInCurrentWindow}/15</span>
              </div>
            )}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/30">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => {
              const tid = crypto.randomUUID();
              setTasks(p => [...p, { id: tid, fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-300 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all shadow-sm">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">上傳大量名片</h3>
                <p className="text-slate-400 text-sm mt-2">系統將自動分成 <span className="text-indigo-600 font-bold">每組 15 張</span> 進行智慧排隊</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
              <div className="mt-8 flex gap-6 opacity-60">
                <div className="flex items-center gap-2 text-xs font-bold text-slate-500"><i className="fa-solid fa-bolt"></i> 免費版限制: 15次/分</div>
                <div className="flex items-center gap-2 text-xs font-bold text-slate-500"><i className="fa-solid fa-shield-halved"></i> 自動排隊冷卻系統</div>
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto">
               <div className="flex justify-between items-center mb-6">
                 <h2 className="text-2xl font-black text-slate-800">智慧辨識任務</h2>
                 <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 transition-colors">清空任務列表</button>
               </div>

               {isPaused && (
                 <div className="bg-white border border-red-100 p-5 rounded-2xl mb-6 flex items-center justify-between shadow-sm">
                   <div className="flex items-center gap-4">
                     <div className="w-10 h-10 rounded-xl bg-red-50 flex items-center justify-center text-red-500"><i className="fa-solid fa-clock-rotate-left"></i></div>
                     <div>
                       <p className="text-sm font-bold text-slate-800">目前波次已達上限 (15張)</p>
                       <p className="text-xs text-slate-400">正在等待 Google 釋放配額... 還有 {cooldown} 秒</p>
                     </div>
                   </div>
                   <div className="w-12 h-12 relative flex items-center justify-center">
                      <svg className="w-full h-full -rotate-90"><circle cx="24" cy="24" r="20" fill="transparent" stroke="#fee2e2" strokeWidth="4"/><circle cx="24" cy="24" r="20" fill="transparent" stroke="#ef4444" strokeWidth="4" strokeDasharray="125.6" strokeDashoffset={125.6 - (125.6 * cooldown / 60)} strokeLinecap="round" className="transition-all duration-1000"/></svg>
                      <span className="absolute text-[10px] font-black text-red-500">{cooldown}</span>
                   </div>
                 </div>
               )}

               <div className="space-y-8">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-3">
                     <div className="flex items-center gap-3">
                        <span className="bg-slate-800 text-white text-[9px] font-black px-2 py-0.5 rounded uppercase">Group {batchIdx}</span>
                        <div className="h-[1px] flex-1 bg-slate-200"></div>
                        <span className="text-[10px] text-slate-400 font-bold">{batchTasks.filter(t=>t.status==='completed').length}/{batchTasks.length} 完成</span>
                     </div>
                     <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-5 py-3 font-medium text-slate-600">{task.fileName}</td>
                               <td className="px-5 py-3"><StatusLabel status={task.status} /></td>
                               <td className="px-5 py-3 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="text-[10px] font-black text-indigo-500 hover:underline">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
                 {tasks.length === 0 && <div className="p-20 text-center text-slate-400 italic bg-white rounded-3xl border border-dashed">尚無任務</div>}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-5xl mx-auto pb-20">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                 <div className="bg-white p-2 rounded-2xl shadow-lg border border-slate-200"><img src={selectedCard.imageUrl} className="w-full rounded-xl" /></div>
                 <div className="space-y-6">
                   <div className="flex justify-between items-start border-b border-slate-100 pb-4">
                     <h1 className="text-2xl font-black text-slate-800 leading-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                     <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</span>
                   </div>
                   <div className="grid gap-4 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
                      <Field icon="fa-building" label="Institution" value={selectedCard.company} />
                      <Field icon="fa-id-badge" label="Job Title" value={selectedCard.title} />
                      <Field icon="fa-envelope" label="Email" value={selectedCard.email} />
                      <Field icon="fa-globe" label="Country" value={selectedCard.country} />
                      <div className="pt-4 border-t border-slate-50 mt-2">
                        <p className="text-[10px] font-black text-slate-300 uppercase mb-2">AI 判定邏輯</p>
                        <p className="text-xs text-slate-500 leading-relaxed bg-slate-50 p-3 rounded-lg border border-slate-100">{selectedCard.reasoning}</p>
                      </div>
                   </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-6 py-3 rounded-xl shadow-2xl flex items-center gap-3 z-[100] animate-in fade-in slide-in-from-bottom-2">
          <i className="fa-solid fa-circle-exclamation text-indigo-400"></i>
          <span className="text-xs font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-4 opacity-40 hover:opacity-100"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

// UI Components
const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-2.5 rounded-lg text-[10px] font-bold transition-all disabled:opacity-20 flex flex-col items-center gap-1`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span>{label} ({count})</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-3 py-2 rounded-lg text-[11px] font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1 px-2 bg-white/50 border-b border-slate-200 text-center`}><span className={`text-[9px] font-black text-${color}-500 uppercase`}>{title}</span></div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-1.5 space-y-1">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2 rounded-lg cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-sm border-${color}-400 ring-2 ring-${color}-500/10` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[10px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[8px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

const StatusLabel = ({ status }: any) => {
  if (status === 'processing') return <span className="flex items-center gap-1.5 text-indigo-500 font-bold"><i className="fa-solid fa-spinner fa-spin"></i> 辨識中</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">已完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">失敗</span>;
  return <span className="text-slate-300">等待中</span>;
};

const Field = ({ icon, label, value }: any) => (
  <div className="flex gap-4 group">
    <div className="w-8 h-8 rounded-lg bg-slate-50 flex items-center justify-center text-slate-300 group-hover:text-indigo-500 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{label}</p>
      <p className="text-sm font-semibold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);

  // Use a ref to prevent race conditions in the processing loop
  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v8');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v8', JSON.stringify(cards));
  }, [cards]);

  // Cooldown logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
      setErrorMsg(null);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const info = await extractCardInfo(task.base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      // Successful request, add a small 2s buffer before next one to be safe
      await new Promise(r => setTimeout(r, 2000));
    } catch (err: any) {
      const isQuota = err.message?.includes("配額") || err.message?.includes("quota") || err.message?.includes("429");
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));

      if (isQuota) {
        setIsPaused(true);
        setCooldown(65); // Standard cooling time
        setErrorMsg("偵測到 API 限制，系統將自動進入 65 秒冷卻期...");
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  // Automated Sequential Queue Engine
  useEffect(() => {
    if (isPaused || isProcessingRef.current) return;

    // Check batch limit (15 per minute)
    if (processedInCurrentBatch >= 15) {
      setIsPaused(true);
      setCooldown(65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, processedInCurrentBatch]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失，請重新上傳");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空任務？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Data Hub v8</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {isPaused ? (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs animate-spin"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">配額緩衝: {cooldown}s</span>
              </div>
            ) : activeTasksCount > 0 ? (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-200">
                <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-ping"></span>
                <span className="text-[10px] font-bold text-indigo-600 uppercase">進行中 {processedInCurrentBatch}/15</span>
              </div>
            ) : null}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => {
              setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">一鍵批量上傳</h3>
                <p className="text-slate-400 text-sm mt-2">系統會自動以 <span className="text-indigo-600 font-bold">15 張為一組</span> 進行安全排隊</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
              <p className="mt-8 text-xs text-slate-400 font-medium">基於 Google Gemini 15 RPM 安全限制開發</p>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6">
               <div className="flex justify-between items-center">
                 <h2 className="text-2xl font-black text-slate-800">佇列處理進度</h2>
                 <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 transition-colors">清空所有任務</button>
               </div>

               {isPaused && (
                 <div className="bg-indigo-600 text-white p-6 rounded-3xl flex items-center justify-between shadow-xl shadow-indigo-100 animate-in zoom-in duration-300">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-xl"><i className="fa-solid fa-shield-halved"></i></div>
                       <div>
                          <p className="text-lg font-bold">目前正在配額緩衝期</p>
                          <p className="text-sm opacity-80">為了防止 Google API 報錯，我們將在 {cooldown} 秒後啟動下一批次 (Group {Math.floor(tasks.length/15)+1})。</p>
                       </div>
                    </div>
                    <div className="text-3xl font-black opacity-40">{cooldown}s</div>
                 </div>
               )}

               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4">
                        <span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">Group {batchIdx}</span>
                        <div className="h-px flex-1 bg-slate-100"></div>
                        <span className="text-[11px] text-slate-400 font-bold">{batchTasks.filter(t=>t.status==='completed').length} / {batchTasks.length} Done</span>
                     </div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold hover:bg-red-100 transition-colors">重試</button>}
                                 {task.status === 'completed' && <div className="w-6 h-6 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center ml-auto"><i className="fa-solid fa-check text-[10px]"></i></div>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5 duration-500">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                 <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-slate-100 pb-6">
                       <div>
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                          <p className="text-indigo-500 font-bold text-sm mt-1">{selectedCard.title}</p>
                       </div>
                       <div className={`px-4 py-1.5 rounded-full text-[11px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="Institution / Company" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-location-dot" label="Country" value={selectedCard.country} />
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">AI 判定註解</p>
                          <p className="text-sm text-slate-600 leading-relaxed font-medium italic">"{selectedCard.reasoning}"</p>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in bounce-in">
          <i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i>
          <span className="text-sm font-bold tracking-tight">{errorMsg}</span>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="flex items-center gap-2 text-indigo-500 font-bold animate-pulse"><i className="fa-solid fa-brain"></i> 分析中</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold tracking-tight">辨識完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">連線異常</span>;
  return <span className="text-slate-300 font-medium">佇列等待</span>;
};

const InfoField = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-4">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-base font-bold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm shadow-${color}-100`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center`}><span className={`text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</span></div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400 ring-4 ring-${color}-500/5` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate font-medium">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false); // For API Quota cooling
  const [isManualPaused, setIsManualPaused] = useState(false); // For User manual control
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v8');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v8', JSON.stringify(cards));
  }, [cards]);

  // Cooldown logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
      setErrorMsg(null);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const info = await extractCardInfo(task.base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, 2000));
    } catch (err: any) {
      const isQuota = err.message?.includes("配額") || err.message?.includes("quota") || err.message?.includes("429");
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));

      if (isQuota) {
        setIsPaused(true);
        setCooldown(65);
        setErrorMsg("偵測到 API 限制，系統將自動進入 65 秒冷卻期...");
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  // Automated Sequential Queue Engine (Respects Manual Pause)
  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;

    if (processedInCurrentBatch >= 15) {
      setIsPaused(true);
      setCooldown(65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失，請重新上傳");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空任務？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Data Hub v8</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {activeTasksCount > 0 && (
              <button 
                onClick={() => setIsManualPaused(!isManualPaused)}
                className={`flex items-center gap-2 px-3 py-1.5 rounded-full border transition-all ${isManualPaused ? 'bg-amber-50 border-amber-200 text-amber-600' : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-slate-100'}`}
              >
                <i className={`fa-solid ${isManualPaused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
                <span className="text-[10px] font-black uppercase tracking-tight">{isManualPaused ? '恢復執行' : '強制暫停'}</span>
              </button>
            )}

            {isPaused ? (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs animate-spin"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">配額緩衝: {cooldown}s</span>
              </div>
            ) : !isManualPaused && activeTasksCount > 0 ? (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-200">
                <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-ping"></span>
                <span className="text-[10px] font-bold text-indigo-600 uppercase">進行中 {processedInCurrentBatch}/15</span>
              </div>
            ) : null}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => {
              setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">一鍵批量上傳</h3>
                <p className="text-slate-400 text-sm mt-2">系統會自動以 <span className="text-indigo-600 font-bold">15 張為一組</span> 進行安全排隊</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
              <p className="mt-8 text-xs text-slate-400 font-medium">支援手動暫停與自動冷卻機制</p>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6">
               <div className="flex justify-between items-center">
                 <h2 className="text-2xl font-black text-slate-800">佇列處理進度</h2>
                 <div className="flex gap-2">
                    {activeTasksCount > 0 && (
                      <button 
                        onClick={() => setIsManualPaused(!isManualPaused)}
                        className={`px-4 py-2 rounded-xl text-xs font-bold border transition-all ${isManualPaused ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-200' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`}
                      >
                        <i className={`fa-solid ${isManualPaused ? 'fa-play' : 'fa-pause'} mr-2`}></i>
                        {isManualPaused ? '點擊繼續辨識' : '暫停所有任務'}
                      </button>
                    )}
                    <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 px-4 py-2">清空</button>
                 </div>
               </div>

               {isManualPaused && (
                 <div className="bg-amber-50 border border-amber-200 p-6 rounded-3xl flex items-center gap-5 animate-in slide-in-from-top-2">
                    <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 text-xl"><i className="fa-solid fa-hand"></i></div>
                    <div>
                       <p className="text-lg font-bold text-amber-900">任務已由手動暫停</p>
                       <p className="text-sm text-amber-700">您可以先檢查已辨識完的名片。點擊右上角「恢復執行」按鈕繼續。</p>
                    </div>
                 </div>
               )}

               {isPaused && (
                 <div className="bg-indigo-600 text-white p-6 rounded-3xl flex items-center justify-between shadow-xl shadow-indigo-100 animate-in zoom-in duration-300">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-xl"><i className="fa-solid fa-shield-halved"></i></div>
                       <div>
                          <p className="text-lg font-bold">目前正在配額緩衝期</p>
                          <p className="text-sm opacity-80">Google API RPM 限制生效中，將在 {cooldown} 秒後啟動下一批次。</p>
                       </div>
                    </div>
                    <div className="text-3xl font-black opacity-40">{cooldown}s</div>
                 </div>
               )}

               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4">
                        <span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">Group {batchIdx}</span>
                        <div className="h-px flex-1 bg-slate-100"></div>
                        <span className="text-[11px] text-slate-400 font-bold">{batchTasks.filter(t=>t.status==='completed').length} / {batchTasks.length} Done</span>
                     </div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700">{task.fileName}</td>
                               <td className="px-6 py-4">
                                  {isManualPaused && task.status === 'pending' ? (
                                    <span className="text-amber-500 font-bold italic">手動暫停中</span>
                                  ) : (
                                    <StatusBadge status={task.status} />
                                  )}
                               </td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold hover:bg-red-100 transition-colors">重試</button>}
                                 {task.status === 'completed' && <div className="w-6 h-6 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center ml-auto"><i className="fa-solid fa-check text-[10px]"></i></div>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
                 {tasks.length === 0 && <div className="p-20 text-center text-slate-400 italic bg-white rounded-3xl border border-dashed border-slate-200">佇列內尚無任何名片任務</div>}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5 duration-500">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                 <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-slate-100 pb-6">
                       <div>
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                          <p className="text-indigo-500 font-bold text-sm mt-1">{selectedCard.title}</p>
                       </div>
                       <div className={`px-4 py-1.5 rounded-full text-[11px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="Institution / Company" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-location-dot" label="Country" value={selectedCard.country} />
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">AI 判定註解</p>
                          <p className="text-sm text-slate-600 leading-relaxed font-medium italic">"{selectedCard.reasoning}"</p>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in bounce-in">
          <i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i>
          <span className="text-sm font-bold tracking-tight">{errorMsg}</span>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="flex items-center gap-2 text-indigo-500 font-bold animate-pulse"><i className="fa-solid fa-brain"></i> 分析中</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold tracking-tight">辨識完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">連線異常</span>;
  return <span className="text-slate-300 font-medium">佇列等待</span>;
};

const InfoField = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-4">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-base font-bold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm shadow-${color}-100`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center`}><span className={`text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</span></div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400 ring-4 ring-${color}-500/5` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate font-medium">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false); // For API Quota cooling
  const [isManualPaused, setIsManualPaused] = useState(false); // For User manual control
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v8');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v8', JSON.stringify(cards));
  }, [cards]);

  // Cooldown logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
      setErrorMsg(null);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    // Immediately mark as processing to provide snappy feedback
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const info = await extractCardInfo(task.base64);
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      // Reduced delay to 500ms for faster processing within the burst limit
      await new Promise(r => setTimeout(r, 500));
    } catch (err: any) {
      const isQuota = err.message?.includes("配額") || err.message?.includes("quota") || err.message?.includes("429");
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));

      if (isQuota) {
        setIsPaused(true);
        setCooldown(65);
        setErrorMsg("偵測到 API 頻率限制，進入 65 秒冷卻緩衝...");
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  // Automated Sequential Queue Engine (Respects Manual Pause)
  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;

    // 15 requests per minute limit
    if (processedInCurrentBatch >= 15) {
      setIsPaused(true);
      setCooldown(65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失，請重新上傳");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空任務？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Data Hub v9 Fast</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
