import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, retryCount = 0): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Extract contact details from this business card for QS World University Rankings. 
            Categorize into THREE distinct groups:
            1. 'academic': Teaching or Research roles at a University (Professor, Lecturer, Researcher, Dean).
            2. 'staff': Administrative or Support roles at a University (Registrar, HR, IT, Secretary, Office Staff, Facilities).
            3. 'employer': Roles at Corporate, Private, or Government non-educational organizations.

            For Academic/Staff, also identify the 'subject' area (e.g., Arts & Humanities, Engineering & Technology, Life Sciences & Medicine, Natural Sciences, Social Sciences & Management) based on their department or research.
            Set 'source' as "AI Scan".

            Split name into prefix (Mr/Ms/Dr/Prof), first name, and last name.
            Extract country and industry (for employers).
            Provide a brief explanation in Traditional Chinese for why you chose the category based on the institution or job title. 
            If a field is missing, use "". Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING, description: "Salutation" },
            firstName: { type: Type.STRING, description: "First Name" },
            lastName: { type: Type.STRING, description: "Last Name" },
            title: { type: Type.STRING, description: "Job Title" },
            company: { type: Type.STRING, description: "Institution or Company Name" },
            department: { type: Type.STRING, description: "Department" },
            industry: { type: Type.STRING, description: "Industry" },
            country: { type: Type.STRING, description: "Country or Territory" },
            email: { type: Type.STRING, description: "Email address" },
            subject: { type: Type.STRING, description: "Academic Subject Area" },
            source: { type: Type.STRING, description: "Data source" },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            fax: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            notes: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "Reasoning in Traditional Chinese" },
          },
          required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning", "subject", "source"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    // 對於明確的配額錯誤，不再進行內部重試，直接丟給 UI 進行全域暫停
    if (errorMessage.includes("exceeded quota") || errorMessage.includes("429")) {
      throw error;
    }

    // 只針對 500 系列或網路抖動進行有限次重試
    if ((errorMessage.includes("500") || errorMessage.includes("fetch")) && retryCount < 2) {
      await sleep(2000);
      return extractCardInfo(base64Image, retryCount + 1);
    }

    throw error;
  }
};

