  const [isManualPaused, setIsManualPaused] = useState(false); // 強制手動鎖定
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v11');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v11', JSON.stringify(cards));
  }, [cards]);

  // Cooldown timer logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      // 增加逾時保護：若 30 秒沒回應，視為異常
      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時 (超過 30 秒無回應)")), 30000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, 600));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();
      // 偵測配額超出：exceeded quota, 429, limit reached
      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        // 第一步：立刻手動暫停
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(70); // 稍微延長到 70 秒，確保 API 確實重置
        setErrorMsg("API 配額已用盡！系統已「強制暫停」。請等待 70 秒後再手動點擊「恢復」。");

        // 更新該任務狀態
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額超出 (已自動暫停佇列)" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "分析異常" } : t));
        setErrorMsg(`錯誤: ${err.message || "連線異常"}`);
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  // Queue Controller
  useEffect(() => {
    // 嚴格檢查：只要是手動暫停或冷卻中，絕對不往下執行
    if (isPaused || isManualPaused || isProcessingRef.current) return;

    if (processedInCurrentBatch >= 15) {
      setIsPaused(true);
      setCooldown(65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失，請重新上傳");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空任務？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Data Hub v12 Pro</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {activeTasksCount > 0 && (
              <button 
                onClick={() => {
                  setIsManualPaused(!isManualPaused);
                  if (!isManualPaused) setErrorMsg(null);
                }}
                className={`flex items-center gap-2 px-4 py-2 rounded-full border shadow-sm transition-all ${isManualPaused ? 'bg-amber-500 border-amber-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-slate-100'}`}
              >
                <i className={`fa-solid ${isManualPaused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
                <span className="text-[10px] font-black uppercase tracking-tight">{isManualPaused ? '點擊恢復執行' : '暫停佇列'}</span>
              </button>
            )}

            {isPaused ? (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-200 animate-pulse">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs animate-spin"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">重置倒數: {cooldown}s</span>
              </div>
            ) : !isManualPaused && activeTasksCount > 0 ? (
              <div className="flex items-center gap-2 bg-indigo-50 px-3 py-1.5 rounded-full border border-indigo-200">
                <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-ping"></span>
                <span className="text-[10px] font-bold text-indigo-600 uppercase">分析中 {processedInCurrentBatch}/15</span>
              </div>
            ) : null}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto">
              <CameraScanner onCapture={b64 => {
                setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-bolt text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">配額偵測保護模式</h3>
                <p className="text-slate-400 text-sm mt-2">系統已啟用「Exceeded Quota」自動攔截機制</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6">
               <div className="flex justify-between items-center">
                 <h2 className="text-2xl font-black text-slate-800">任務管理中心</h2>
                 <div className="flex gap-2">
                    <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 px-4 py-2">清空佇列</button>
                 </div>
               </div>

               {isManualPaused && (
                 <div className="bg-amber-50 border border-amber-200 p-6 rounded-3xl flex items-center gap-5 border-l-8 border-l-amber-500 shadow-lg animate-in slide-in-from-top-2">
                    <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 text-xl"><i className="fa-solid fa-lock"></i></div>
                    <div>
                       <p className="text-lg font-bold text-amber-900">目前處於暫停狀態</p>
                       <p className="text-sm text-amber-700 font-medium">系統偵測到 API 限流或手動暫停。請等待緩衝後，點擊上方按鈕恢復執行。</p>
                    </div>
                 </div>
               )}

               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4">
                        <span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">Batch {batchIdx}</span>
                        <div className="h-px flex-1 bg-slate-100"></div>
                        <span className="text-[11px] text-slate-400 font-bold">{batchTasks.filter(t=>t.status==='completed').length} / {batchTasks.length} 完成</span>
                     </div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 max-w-[200px] truncate">{task.fileName}</td>
                               <td className="px-6 py-4">
                                  {isManualPaused && task.status === 'pending' ? (
                                    <span className="text-amber-500 font-bold flex items-center gap-2"><i className="fa-solid fa-circle-pause"></i> 待命</span>
                                  ) : (
                                    <StatusBadge status={task.status} />
                                  )}
                               </td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && (
                                   <div className="flex items-center justify-end gap-3">
                                      <span className="text-[9px] text-red-400 font-medium max-w-[120px] truncate">{task.error}</span>
                                      <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold hover:bg-red-100 transition-colors">重試</button>
                                   </div>
                                 )}
                                 {task.status === 'completed' && <div className="w-6 h-6 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center ml-auto"><i className="fa-solid fa-check text-[10px]"></i></div>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
                 {tasks.length === 0 && <div className="p-20 text-center text-slate-400 italic bg-white rounded-3xl border border-dashed border-slate-200">尚無任務</div>}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                 <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-slate-100 pb-6">
                       <div>
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                          <p className="text-indigo-500 font-bold text-sm mt-1">{selectedCard.title}</p>
                       </div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="Institution / Company" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-location-dot" label="Country" value={selectedCard.country} />
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">AI 分析邏輯</p>
                          <p className="text-sm text-slate-600 leading-relaxed font-medium italic">"{selectedCard.reasoning}"</p>
                       </div>
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex items-center gap-4 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl shrink-0"></i>
          <span className="text-sm font-bold tracking-tight">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="flex items-center gap-2 text-indigo-500 font-bold animate-pulse"><i className="fa-solid fa-bolt"></i> 分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold tracking-tight">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">異常</span>;
  return <span className="text-slate-300 font-medium">排隊中</span>;
};

const InfoField = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-4">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-base font-bold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm shadow-${color}-100`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center`}><span className={`text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</span></div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400 ring-4 ring-${color}-500/5` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate font-medium">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

// Define the custom window interface for AI Studio helpers
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  // Cooldown logic
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();
      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("API 配額已用盡！建議切換至「專業版」使用自有 Key 以獲得更高頻率。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;

    // Free plan has a stricter burst limit
    const limit = apiPlan === 'paid' ? 50 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 30 : 65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        await window.aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Premium</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>

          {/* API Plan Selector */}
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button 
               onClick={() => handlePlanSwitch('free')}
               className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400 hover:text-slate-600'}`}
             >
               免費版
             </button>
             <button 
               onClick={() => handlePlanSwitch('paid')}
               className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}
             >
               <i className="fa-solid fa-crown text-[8px]"></i>
               專業版 (付費 Key)
             </button>
          </div>

          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {/* Status Badge */}
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight transition-all ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-gem animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? 'Professional Active' : 'Free Tier'}
            </div>

            {activeTasksCount > 0 && (
              <button 
                onClick={() => { setIsManualPaused(!isManualPaused); if (!isManualPaused) setErrorMsg(null); }}
                className={`flex items-center gap-2 px-4 py-2 rounded-full border shadow-sm transition-all ${isManualPaused ? 'bg-amber-500 border-amber-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-slate-100'}`}
              >
                <i className={`fa-solid ${isManualPaused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
                <span className="text-[10px] font-black uppercase tracking-tight">{isManualPaused ? '恢復執行' : '暫停'}</span>
              </button>
            )}

            {isPaused && (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-200 animate-pulse">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">{cooldown}s</span>
              </div>
            ) }
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto">
              <CameraScanner onCapture={b64 => {
                setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-upload text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">開始批量辨識</h3>
                <p className="text-slate-400 text-sm mt-2">目前的方案：{apiPlan === 'paid' ? '專業版 (極速)' : '免費版 (受限)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center">
                 <h2 className="text-2xl font-black text-slate-800">佇列控管</h2>
                 <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 px-4 py-2">清空全部</button>
               </div>

               {isManualPaused && (
                 <div className="bg-amber-50 border border-amber-200 p-6 rounded-3xl flex items-center justify-between border-l-8 border-l-amber-500 shadow-lg animate-in slide-in-from-top-2">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 text-xl"><i className="fa-solid fa-circle-info"></i></div>
                       <div>
                          <p className="text-lg font-bold text-amber-900">任務暫停中</p>
                          <p className="text-sm text-amber-700 font-medium">若頻繁遇到配額問題，建議切換至「專業版」並填寫自有付費 API Key。</p>
                       </div>
                    </div>
                    {apiPlan === 'free' && (
                      <button 
                        onClick={() => handlePlanSwitch('paid')}
                        className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                      >
                        升級專業版
                      </button>
                    )}
                 </div>
               )}

               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4">
                        <span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">Batch {batchIdx}</span>
                        <div className="h-px flex-1 bg-slate-100"></div>
                     </div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 max-w-[200px] truncate">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && (
                                    <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold hover:bg-red-100 transition-colors">重試</button>
                                 )}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                 <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-slate-100 pb-6">
                       <h1 className="text-3xl font-black text-slate-800 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                       <div className={`px-4 py-1.5 rounded-full text-[11px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="Institution / Company" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-location-dot" label="Country" value={selectedCard.country} />
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600">"{selectedCard.reasoning}"</div>
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4">
            <i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i>
            <span className="text-sm font-bold tracking-tight">{errorMsg}</span>
            <button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          {apiPlan === 'free' && errorMsg.includes("配額") && (
            <button 
              onClick={() => handlePlanSwitch('paid')}
              className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-900/50 transition-all"
            >
              切換至專業版 (自有 API Key)
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">配額受限/異常</span>;
  return <span className="text-slate-300">等待中</span>;
};

const InfoField = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-4">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-base font-bold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import { GoogleGenAI, Type } from "@google/genai";

// Sleep helper function for retry logic
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, retryCount = 0): Promise<any> => {
  // Always create a new GoogleGenAI instance right before making an API call to ensure it always uses the most up-to-date API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image,
            },
          },
          {
            text: `Extract contact details from this business card for QS World University Rankings. 
            Categorize into THREE distinct groups:
            1. 'academic': Teaching or Research roles at a University (Professor, Lecturer, Researcher, Dean).
            2. 'staff': Administrative or Support roles at a University (Registrar, HR, IT, Secretary, Office Staff, Facilities).
            3. 'employer': Roles at Corporate, Private, or Government non-educational organizations.

            For Academic/Staff, also identify the 'subject' area (e.g., Arts & Humanities, Engineering & Technology, Life Sciences & Medicine, Natural Sciences, Social Sciences & Management) based on their department or research.
            Set 'source' as "AI Scan".

            Split name into prefix (Mr/Ms/Dr/Prof), first name, and last name.
            Extract country and industry (for employers).
            Provide a brief explanation in Traditional Chinese for why you chose the category based on the institution or job title. 
            If a field is missing, use "". Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING, description: "Salutation" },
            firstName: { type: Type.STRING, description: "First Name" },
            lastName: { type: Type.STRING, description: "Last Name" },
            title: { type: Type.STRING, description: "Job Title" },
            company: { type: Type.STRING, description: "Institution or Company Name" },
            department: { type: Type.STRING, description: "Department" },
            industry: { type: Type.STRING, description: "Industry" },
            country: { type: Type.STRING, description: "Country or Territory" },
            email: { type: Type.STRING, description: "Email address" },
            subject: { type: Type.STRING, description: "Academic Subject Area" },
            source: { type: Type.STRING, description: "Data source" },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            fax: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            notes: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "Reasoning in Traditional Chinese" },
          },
          required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning", "subject", "source"],
        },
      },
    });

    // Directly access the .text property of the GenerateContentResponse object
    const text = response.text;
    if (!text) throw new Error("AI 回應為空");
    return JSON.parse(text);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    // For explicit quota errors, throw immediately to trigger UI pause/error state
    if (errorMessage.includes("exceeded quota") || errorMessage.includes("429")) {
      throw error;
    }

    // Only retry for 500-series errors or network issues (fetch failures) up to 2 times
    if ((errorMessage.includes("500") || errorMessage.includes("fetch")) && retryCount < 2) {
      await sleep(2000);
      return extractCardInfo(base64Image, retryCount + 1);
    }

    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

// Use the global AIStudio interface to avoid type conflicts and modifier issues
declare global {
  interface Window {
    aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence and initial state loading
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  // Handle cooldown countdown for API limits
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  // Core task processing logic using the extractCardInfo service
  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      // Handle missing entity/key errors by resetting key state and prompting the user
      if (errLower.includes("requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或找不到，請重新切換專業版並選擇 Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 失效" } : t));
        await window.aistudio.openSelectKey();
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("API 配額已用盡！建議切換至「專業版」使用自有 Key 以獲得更高頻率。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  // Automated queue processing loop
  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;

    // Free plan has a stricter burst limit than the paid plan
    const limit = apiPlan === 'paid' ? 50 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 30 : 65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });

      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({
        id: crypto.randomUUID(),
        fileName: f.name,
        status: 'pending',
        progress: 0,
        base64,
        batchIndex
      });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        await window.aistudio.openSelectKey();
        // Following guidelines: assume key selection success and proceed
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const exportData = filtered.map(c => ({
      'Title': c.prefix,
      'First Name': c.firstName,
      'Last Name': c.lastName,
      'Job Title': c.title,
      'Company/Institution': c.company,
      'Email': c.email,
      'Country': c.country,
      'Category': c.category
    }));
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Premium</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>

          {/* API Plan Selector */}
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button 
               onClick={() => handlePlanSwitch('free')}
               className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400 hover:text-slate-600'}`}
             >
               免費版
             </button>
             <button 
               onClick={() => handlePlanSwitch('paid')}
               className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}
             >
               <i className="fa-solid fa-crown text-[8px]"></i>
               專業版 (付費 Key)
             </button>
          </div>

          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="預覽" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            {/* Status Badge */}
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight transition-all ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-gem animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? 'Professional Active' : 'Free Tier'}
            </div>

            {activeTasksCount > 0 && (
              <button 
                onClick={() => { setIsManualPaused(!isManualPaused); if (!isManualPaused) setErrorMsg(null); }}
                className={`flex items-center gap-2 px-4 py-2 rounded-full border shadow-sm transition-all ${isManualPaused ? 'bg-amber-500 border-amber-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-slate-100'}`}
              >
                <i className={`fa-solid ${isManualPaused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
                <span className="text-[10px] font-black uppercase tracking-tight">{isManualPaused ? '恢復執行' : '暫停'}</span>
              </button>
            )}

            {isPaused && (
              <div className="flex items-center gap-2 bg-red-50 px-3 py-1.5 rounded-full border border-red-200 animate-pulse">
                <i className="fa-solid fa-hourglass-half text-red-500 text-xs"></i>
                <span className="text-[10px] font-bold text-red-600 uppercase">{cooldown}s</span>
              </div>
            ) }
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto">
              <CameraScanner onCapture={b64 => {
                setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer group text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-all">
                  <i className="fa-solid fa-upload text-3xl"></i>
                </div>
                <h3 className="text-xl font-bold text-slate-800">開始批量辨識</h3>
                <p className="text-slate-400 text-sm mt-2">目前的方案：{apiPlan === 'paid' ? '專業版 (極速)' : '免費版 (受限)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center">
                 <h2 className="text-2xl font-black text-slate-800">佇列控管</h2>
                 <button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500 px-4 py-2">清空全部</button>
               </div>

               {isManualPaused && (
                 <div className="bg-amber-50 border border-amber-200 p-6 rounded-3xl flex items-center justify-between border-l-8 border-l-amber-500 shadow-lg animate-in slide-in-from-top-2">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600 text-xl"><i className="fa-solid fa-circle-info"></i></div>
                       <div>
                          <p className="text-lg font-bold text-amber-900">任務暫停中</p>
                          <p className="text-sm text-amber-700 font-medium">若頻繁遇到配額問題，建議切換至「專業版」並填寫自有付費 API Key。</p>
                       </div>
                    </div>
                    {apiPlan === 'free' && (
                      <button 
                        onClick={() => handlePlanSwitch('paid')}
                        className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-black text-xs shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                      >
                        升級專業版
                      </button>
                    )}
                 </div>
               )}

               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4">
                        <span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">Batch {batchIdx}</span>
                        <div className="h-px flex-1 bg-slate-100"></div>
                     </div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50/50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 max-w-[200px] truncate">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && (
                                    <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold hover:bg-red-100 transition-colors">重試</button>
                                 )}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                 <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-slate-100 pb-6">
                       <h1 className="text-3xl font-black text-slate-800 tracking-tight">{selectedCard.prefix} {selectedCard.firstName} {selectedCard.lastName}</h1>
                       <div className={`px-4 py-1.5 rounded-full text-[11px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="Institution / Company" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-location-dot" label="Country" value={selectedCard.country} />
                       </div>
                       <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600">"{selectedCard.reasoning}"</div>
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4">
            <i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i>
            <span className="text-sm font-bold tracking-tight">{errorMsg}</span>
            <button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          {apiPlan === 'free' && errorMsg.includes("配額") && (
            <button 
              onClick={() => handlePlanSwitch('paid')}
              className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest shadow-lg shadow-indigo-900/50 transition-all"
            >
              切換至專業版 (自有 API Key)
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">配額受限/異常</span>;
  return <span className="text-slate-300">等待中</span>;
};

const InfoField = ({ icon, label, value }: any) => (
  <div className="flex items-start gap-4">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div>
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      <p className="text-base font-bold text-slate-700">{value || '---'}</p>
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

{
  "name": "QS Hub Desktop Uploader",
  "description": "Professional desktop-style utility for uploading business cards and extracting data in QS Hub format using Gemini AI.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

declare global {
  interface Window {
    aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或找不到，請重新選擇專業版 Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 失效" } : t));
        await window.aistudio.openSelectKey();
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("API 配額已用盡！建議升級專業版使用自有 Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;
    const limit = apiPlan === 'paid' ? 50 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 30 : 65);
      return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files);
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        await window.aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Data_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Premium v12</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費版</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400'}`}>
               <i className="fa-solid fa-crown text-[8px]"></i> 專業版
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-gem animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? 'Professional' : 'Free Tier'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復' : '暫停'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-upload text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳辨識</h3>
                <p className="text-slate-400 text-sm mt-2">目前的模式：{apiPlan === 'paid' ? '專業版 (高速)' : '免費版 (受限)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">任務隊列</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空全部</button></div>
               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">Batch {batchIdx}</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域 (Subject Area)" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && errorMsg.includes("配額") && <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">升級專業版</button>}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">受限 / 異常</span>;
  return <span className="text-slate-300">隊列中</span>;
};

const InfoField = ({ icon, label, value, isLink }: any) => (
  <div className="flex items-start gap-4 group">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100 group-hover:bg-white group-hover:border-indigo-200 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      {isLink && value ? (
        <a href={value.startsWith('http') ? value : `https://${value}`} target="_blank" className="text-sm font-bold text-indigo-500 hover:underline truncate block">{value}</a>
      ) : (
        <p className="text-sm font-bold text-slate-700 truncate">{value || '---'}</p>
      )}
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

// Define AIStudio interface to match the environment's global object
interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    // Fixed: Added 'readonly' to match the system's definition of aistudio and avoid "identical modifiers" error
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或找不到，請重新選擇專業版 Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 失效" } : t));
        await window.aistudio.openSelectKey();
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("API 配額已用盡！建議升級專業版使用自有 Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;
    const limit = apiPlan === 'paid' ? 50 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 30 : 65);
      return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    // Fixed: Explicitly type fileList as File[] to avoid 'unknown' type inference from Array.from
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        // Fixed: Passing f (now typed as File, which extends Blob) correctly to readAsDataURL
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      // Fixed: f.name is now valid as f is correctly typed as File
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        await window.aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Data_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Premium v12</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費版</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400'}`}>
               <i className="fa-solid fa-crown text-[8px]"></i> 專業版
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-gem animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? 'Professional' : 'Free Tier'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復' : '暫停'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-upload text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳辨識</h3>
                <p className="text-slate-400 text-sm mt-2">目前的模式：{apiPlan === 'paid' ? '專業版 (高速)' : '免費版 (受限)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">任務隊列</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空全部</button></div>
               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">Batch {batchIdx}</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域 (Subject Area)" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email Address" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && errorMsg.includes("配額") && <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">升級專業版</button>}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">受限 / 異常</span>;
  return <span className="text-slate-300">隊列中</span>;
};

const InfoField = ({ icon, label, value, isLink }: any) => (
  <div className="flex items-start gap-4 group">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100 group-hover:bg-white group-hover:border-indigo-200 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      {isLink && value ? (
        <a href={value.startsWith('http') ? value : `https://${value}`} target="_blank" className="text-sm font-bold text-indigo-500 hover:underline truncate block">{value}</a>
      ) : (
        <p className="text-sm font-bold text-slate-700 truncate">{value || '---'}</p>
      )}
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

// Define AIStudio interface to match the environment's global object
interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    readonly aistudio: AIStudio;
  }
}

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found") || errLower.includes("unauthorized") || errLower.includes("api key")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或未設定，請點擊上方「付費使用」填寫您的 Google Cloud API Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 設定錯誤" } : t));
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("免費額度已用盡！請切換至「付費使用」並填寫自有 API Key 以解除限制。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;
    const limit = apiPlan === 'paid' ? 100 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 10 : 65);
      return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        // This opens the system dialog where the user can enter/select their Google Cloud API key
        await window.aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Data_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}>
               <i className="fa-solid fa-key text-[8px]"></i> 付費使用
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-bolt animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? '自有 Key 模式' : '免費模式'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復執行' : '暫停'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s 延遲中</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-cloud-arrow-up text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳辨識</h3>
                <p className="text-slate-400 text-sm mt-2">當前狀態：{apiPlan === 'paid' ? '已啟用自有 API Key' : '使用免費共享額度'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">辨識任務列表</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空任務</button></div>
               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">第 {batchIdx} 批次</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="電子郵件" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && (
            <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
              填寫自有 API Key
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">配額受限 / 異常</span>;
  return <span className="text-slate-300">等待隊列</span>;
};

const InfoField = ({ icon, label, value, isLink }: any) => (
  <div className="flex items-start gap-4 group">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100 group-hover:bg-white group-hover:border-indigo-200 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      {isLink && value ? (
        <a href={value.startsWith('http') ? value : `https://${value}`} target="_blank" className="text-sm font-bold text-indigo-500 hover:underline truncate block">{value}</a>
      ) : (
        <p className="text-sm font-bold text-slate-700 truncate">{value || '---'}</p>
      )}
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found") || errLower.includes("unauthorized") || errLower.includes("api key")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或未設定，請點擊上方「付費使用」填寫您的 Google Cloud API Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 設定錯誤" } : t));
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("免費額度已用盡！請切換至「付費使用」並填寫自有 API Key 以解除限制。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;
    const limit = apiPlan === 'paid' ? 100 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 10 : 65);
      return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        // Assume window.aistudio is pre-configured in the environment.
        // Cast to any to safely access methods if types are not perfectly matched in local scope.
        await (window as any).aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Data_${category.toUpperCase()}.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}>
               <i className="fa-solid fa-key text-[8px]"></i> 付費使用
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-bolt animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? '自有 Key 模式' : '免費模式'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復執行' : '暫停'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s 延遲中</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "相機拍攝", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-cloud-arrow-up text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳辨識</h3>
                <p className="text-slate-400 text-sm mt-2">當前狀態：{apiPlan === 'paid' ? '已啟用自有 API Key' : '使用免費共享額度'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">辨識任務列表</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空任務</button></div>
               <div className="space-y-10">
                 {groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">第 {batchIdx} 批次</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="電子郵件" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && (
            <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
              填寫自有 API Key
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">配額受限 / 異常</span>;
  return <span className="text-slate-300">等待隊列</span>;
};

const InfoField = ({ icon, label, value, isLink }: any) => (
  <div className="flex items-start gap-4 group">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100 group-hover:bg-white group-hover:border-indigo-200 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div className="min-w-0">
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      {isLink && value ? (
        <a href={value.startsWith('http') ? value : `https://${value}`} target="_blank" className="text-sm font-bold text-indigo-500 hover:underline truncate block">{value}</a>
      ) : (
        <p className="text-sm font-bold text-slate-700 truncate">{value || '---'}</p>
      )}
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

{
  "name": "QS Hub Desktop Uploader",
  "description": "Professional desktop-style utility for uploading business cards and extracting data in QS Hub format using Gemini AI.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');

  const isProcessingRef = useRef(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing', progress: 10, error: undefined } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      const infoPromise = extractCardInfo(task.base64);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:image/jpeg;base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
        setViewMode('detail');
      }

      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 200 : 800));
    } catch (err: any) {
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found") || errLower.includes("unauthorized") || errLower.includes("api key")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或未設定，請點擊上方「付費使用」填寫您的 Google Cloud API Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 設定錯誤" } : t));
        isProcessingRef.current = false;
        return;
      }

      const isQuota = errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額");

      if (isQuota) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("免費額度已用盡！請切換至「付費使用」並填寫自有 API Key 以解除限制。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "異常" } : t));
      }
    } finally {
      isProcessingRef.current = false;
    }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessingRef.current) return;
    const limit = apiPlan === 'paid' ? 200 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 5 : 65);
      return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        // Trigger the built-in API Key entry box
        await (window as any).aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片遺失");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空辨識隊列？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    isProcessingRef.current = false;
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country,
      'Industry': c.industry, 'Source': c.source
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Hub_${category.toUpperCase()}_Export.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}>
               <i className="fa-solid fa-key text-[8px]"></i> 付費使用
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`任務隊列 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="資料詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-bolt animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? '付費模式' : '免費模式'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復辨識' : '暫停辨識'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s 延遲處理中</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: "現場拍攝名片", status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-cloud-arrow-up text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">開始批量上傳</h3>
                <p className="text-slate-400 text-sm mt-2">目前的模式：{apiPlan === 'paid' ? '付費模式 (無限制)' : '免費額度 (批次處理)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">辨識任務清單</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空所有任務</button></div>
               <div className="space-y-10">
                 {groupedTasks.length === 0 ? (
                   <div className="text-center py-20 text-slate-300 font-bold">目前沒有正在處理的任務</div>
                 ) : groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">Batch {batchIdx}</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">點此重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors" title="Google Search"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司名稱" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email 電子郵件" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話 / 手機" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && (
            <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
              立即填寫自有 API Key
            </button>
          )}
        </div>
      )}
    </div>
  );
};

const StatusBadge = ({ status }: any) => {
  if (status === 'processing') return <span className="text-indigo-500 font-bold animate-pulse">AI 分析中...</span>;
  if (status === 'completed') return <span className="text-emerald-500 font-bold">辨識完成</span>;
  if (status === 'error') return <span className="text-red-400 font-bold">配額受限 / 異常</span>;
  return <span className="text-slate-300">隊列等待中</span>;
};

const InfoField = ({ icon, label, value, isLink }: any) => (
  <div className="flex items-start gap-4 group">
    <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100 group-hover:bg-white group-hover:border-indigo-200 transition-colors"><i className={`fa-solid ${icon} text-sm`}></i></div>
    <div className="min-w-0 flex-1">
      <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-0.5">{label}</p>
      {isLink && value ? (
        <a href={value.startsWith('http') ? value : `https://${value}`} target="_blank" className="text-sm font-bold text-indigo-500 hover:underline truncate block">{value}</a>
      ) : (
        <p className="text-sm font-bold text-slate-700 truncate">{value || '---'}</p>
      )}
    </div>
  </div>
);

const NavBtn = ({ icon, label, active, onClick, highlight }: any) => (
  <button onClick={onClick} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all flex items-center gap-2 relative ${active ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500 hover:text-slate-800'}`}>
    <i className={`fa-solid ${icon}`}></i>
    <span>{label}</span>
    {highlight && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
  </button>
);

const ExportBtn = ({ color, label, count, onClick }: any) => (
  <button onClick={onClick} disabled={count === 0} className={`bg-${color}-600 hover:bg-${color}-700 text-white p-3 rounded-xl text-[10px] font-black transition-all disabled:opacity-20 flex flex-col items-center gap-1.5 shadow-sm`}>
    <i className={`fa-solid ${label === 'Employer' ? 'fa-building-user' : label === 'Academic' ? 'fa-user-graduate' : 'fa-users-gear'}`}></i>
    <span className="tracking-tighter">{label} ({count})</span>
  </button>
);

const Column = ({ title, color, items, activeId, onSelect }: any) => (
  <div className={`flex-1 flex flex-col ${title !== 'Sta' ? 'border-r border-slate-200' : ''}`}>
    <div className={`py-1.5 px-2 bg-white/50 border-b border-slate-200 text-center text-[9px] font-black text-${color}-500 uppercase tracking-widest`}>{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-1.5">
      {items.map((c: any) => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400` : 'border-transparent hover:bg-white/60'}`}>
          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
        </div>
      ))}
      {items.length === 0 && <div className="text-[9px] text-center py-4 text-slate-300 italic font-bold">尚無資料</div>}
    </div>
  </div>
);

export default App;

import { GoogleGenAI, Type } from "@google/genai";

// Sleep helper function for retry logic
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, mimeType: string = 'image/jpeg', retryCount = 0): Promise<any> => {
  // Always create a new GoogleGenAI instance right before making an API call
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `Extract contact details from this business card for QS World University Rankings. 
            Categorize into THREE distinct groups:
            1. 'academic': Teaching or Research roles at a University (Professor, Lecturer, Researcher, Dean).
            2. 'staff': Administrative or Support roles at a University (Registrar, HR, IT, Secretary, Office Staff, Facilities).
            3. 'employer': Roles at Corporate, Private, or Government non-educational organizations.

            For Academic/Staff, also identify the 'subject' area (e.g., Arts & Humanities, Engineering & Technology, Life Sciences & Medicine, Natural Sciences, Social Sciences & Management) based on their department or research.
            Set 'source' as "AI Scan".

            Split name into prefix (Mr/Ms/Dr/Prof), first name, and last name.
            Extract country and industry (for employers).
            Provide a brief explanation in Traditional Chinese for why you chose the category based on the institution or job title. 
            If a field is missing, use "". Return JSON.`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING, description: "Salutation" },
            firstName: { type: Type.STRING, description: "First Name" },
            lastName: { type: Type.STRING, description: "Last Name" },
            title: { type: Type.STRING, description: "Job Title" },
            company: { type: Type.STRING, description: "Institution or Company Name" },
            department: { type: Type.STRING, description: "Department" },
            industry: { type: Type.STRING, description: "Industry" },
            country: { type: Type.STRING, description: "Country or Territory" },
            email: { type: Type.STRING, description: "Email address" },
            subject: { type: Type.STRING, description: "Academic Subject Area" },
            source: { type: Type.STRING, description: "Data source" },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            fax: { type: Type.STRING },
            website: { type: Type.STRING },
            address: { type: Type.STRING },
            notes: { type: Type.STRING },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "Reasoning in Traditional Chinese" },
          },
          required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning", "subject", "source"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");

    // Attempt to clean the response text if it contains markdown markers, although responseMimeType: "application/json" should prevent this
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedText);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    // For explicit quota errors, throw immediately
    if (errorMessage.includes("exceeded quota") || errorMessage.includes("429")) {
      throw error;
    }

    // Only retry for 500-series errors or network issues
    if ((errorMessage.includes("500") || errorMessage.includes("fetch")) && retryCount < 2) {
      await sleep(2000);
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }

    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved data
  useEffect(() => {
    const saved = localStorage.getItem('qs_hub_cards_v12');
    const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setCards(parsed);
        if (parsed.length > 0 && !selectedCardId) {
          setSelectedCardId(parsed[0].id);
        }
      } catch (e) { console.error(e); }
    }
    if (savedPlan) setApiPlan(savedPlan);
  }, []);

  // Save data
  useEffect(() => {
    localStorage.setItem('qs_hub_cards_v12', JSON.stringify(cards));
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [cards, apiPlan]);

  // Handle Cooldown Timer
  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const failedTasks = tasks.filter(t => t.status === 'error');
  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);

  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);

    // Update status to processing
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      if (!task.base64) throw new Error("圖片資料遺失");

      // Determine mimeType if possible, otherwise default to jpeg
      const mimeTypeMatch = task.fileName.match(/\.(png|webp|gif)$/i);
      const mimeType = mimeTypeMatch ? `image/${mimeTypeMatch[1].toLowerCase()}` : 'image/jpeg';

      const infoPromise = extractCardInfo(task.base64, mimeType);
      const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("AI 分析逾時")), 45000));

      const info = await Promise.race([infoPromise, timeoutPromise]) as any;

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${mimeType};base64,${task.base64}`,
      };

      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100, base64: undefined } : t));
      setProcessedInCurrentBatch(prev => prev + 1);

      if (!selectedCardId) {
        setSelectedCardId(newCard.id);
      }

      // Small delay between successful tasks to prevent rate limit triggers on rapid success
      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 300 : 1000));
    } catch (err: any) {
      console.error("Processing error:", err);
      const errLower = (err.message || "").toLowerCase();

      if (errLower.includes("requested entity was not found") || errLower.includes("unauthorized") || errLower.includes("api key")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效或未設定，請點擊左側「付費使用」填寫您的 Google Cloud API Key。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "Key 設定錯誤" } : t));
      } else if (errLower.includes("quota") || errLower.includes("429") || errLower.includes("limit") || errLower.includes("配額")) {
        setIsManualPaused(true); 
        setIsPaused(true);
        setCooldown(75);
        setErrorMsg("辨識額度暫時用盡！請切換至「付費使用」並填寫自有 API Key 以解除限制。");
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: "配額限制" } : t));
      } else {
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "分析異常" } : t));
      }
    } finally {
      setIsProcessing(false);
    }
  };

  // Task processing loop
  useEffect(() => {
    if (isPaused || isManualPaused || isProcessing) return;

    const limit = apiPlan === 'paid' ? 500 : 15;
    if (processedInCurrentBatch >= limit) {
      setIsPaused(true);
      setCooldown(apiPlan === 'paid' ? 5 : 65);
      return;
    }

    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) {
      performTask(nextTask);
    }
  }, [tasks, isPaused, isManualPaused, isProcessing, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;
    const newTasks: ProcessingTask[] = [];

    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const base64 = await new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(f);
      });
      const batchIndex = Math.floor((startIndex + i) / 15) + 1;
      newTasks.push({ id: crypto.randomUUID(), fileName: f.name, status: 'pending', progress: 0, base64, batchIndex });
    }

    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      try {
        await (window as any).aistudio.openSelectKey();
        setApiPlan('paid');
        setErrorMsg(null);
      } catch (e) {
        console.error("Key selection cancelled", e);
      }
    } else {
      setApiPlan('free');
    }
  };

  const retryTask = (task: ProcessingTask) => {
    if (!task.base64) return alert("圖片資料已從快取中移除，請重新上傳。");
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'pending', error: undefined } : t));
  };

  const clearTasks = () => {
    if (activeTasksCount > 0 && !confirm("確定清空正在處理或等待中的任務？")) return;
    setTasks([]);
    setProcessedInCurrentBatch(0);
    setIsProcessing(false);
    setErrorMsg(null);
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const worksheet = XLSX.utils.json_to_sheet(filtered.map(c => ({
      'Prefix': c.prefix, 'First Name': c.firstName, 'Last Name': c.lastName,
      'Title': c.title, 'Institution': c.company, 'Department': c.department,
      'Subject Area': c.subject, 'Email': c.email, 'Phone': c.phone, 'Country': c.country,
      'Industry': c.industry, 'Source': c.source
    })));
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Hub_${category.toUpperCase()}_Export.xlsx`);
  };

  const selectedCard = cards.find(c => c.id === selectedCardId);

  return (
    <div className="flex h-screen w-screen overflow-hidden bg-[#f3f3f3]">
      <aside className={`fixed inset-y-0 left-0 z-50 w-80 lg:static lg:w-[380px] flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}>
               <i className="fa-solid fa-key text-[8px]"></i> 付費使用
             </button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <ExportBtn color="indigo" label="Employer" count={employerCards.length} onClick={() => exportToExcel('employer')} />
            <ExportBtn color="emerald" label="Academic" count={academicCards.length} onClick={() => exportToExcel('academic')} />
            <ExportBtn color="amber" label="Staff" count={staffCards.length} onClick={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`辨識進度 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={failedTasks.length > 0 || isPaused || isManualPaused} />
                {selectedCard && <NavBtn icon="fa-address-card" label="資料詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-bolt animate-pulse' : 'fa-circle'}`}></i>
               {apiPlan === 'paid' ? '已填寫 API Key' : '免費額度模式'}
            </div>
            {activeTasksCount > 0 && (
              <button onClick={() => setIsManualPaused(!isManualPaused)} className={`px-4 py-2 rounded-full border text-[10px] font-black uppercase tracking-tight transition-all ${isManualPaused ? 'bg-amber-500 text-white' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                {isManualPaused ? '恢復執行' : '暫停'}
              </button>
            )}
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200">{cooldown}s 緩衝中</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={b64 => { setTasks(p => [...p, { id: crypto.randomUUID(), fileName: `現場拍攝_${new Date().toLocaleTimeString()}`, status: 'pending', progress: 0, base64: b64, batchIndex: Math.floor(tasks.length/15)+1 }]); setViewMode('tasks'); }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-xl p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto"><i className="fa-solid fa-cloud-arrow-up text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳名片圖片</h3>
                <p className="text-slate-400 text-sm mt-2">支援 JPG, PNG, WebP 格式。當前模式：{apiPlan === 'paid' ? '付費使用 (無限制)' : '免費額度 (15張/次)'}</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6 pb-20">
               <div className="flex justify-between items-center"><h2 className="text-2xl font-black text-slate-800">辨識任務清單</h2><button onClick={clearTasks} className="text-xs font-bold text-slate-400 hover:text-red-500">清空清單</button></div>
               <div className="space-y-10">
                 {groupedTasks.length === 0 ? (
                   <div className="text-center py-20 text-slate-300 font-bold">目前沒有正在辨識的任務</div>
                 ) : groupedTasks.map(([batchIdx, batchTasks]) => (
                   <div key={batchIdx} className="space-y-4">
                     <div className="flex items-center gap-4"><span className="bg-slate-800 text-white text-[10px] font-black px-3 py-1 rounded-full uppercase">第 {batchIdx} 批次</span><div className="h-px flex-1 bg-slate-100"></div></div>
                     <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
                       <table className="w-full text-left text-xs">
                         <tbody className="divide-y divide-slate-50">
                           {batchTasks.map(task => (
                             <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                               <td className="px-6 py-4 font-semibold text-slate-700 truncate max-w-[200px]">{task.fileName}</td>
                               <td className="px-6 py-4"><StatusBadge status={task.status} /></td>
                               <td className="px-6 py-4 text-right">
                                 {task.status === 'error' && <button onClick={() => retryTask(task)} className="bg-red-50 text-red-600 px-3 py-1 rounded-lg font-bold">重試</button>}
                                 {task.status === 'completed' && <i className="fa-solid fa-check text-emerald-500"></i>}
                               </td>
                             </tr>
                           ))}
                         </tbody>
                       </table>
                     </div>
                   </div>
                 ))}
               </div>
            </div>
          ) : selectedCard ? (
            <div className="max-w-6xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-5">
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                 <div className="space-y-6">
                    <div className="bg-white p-2 rounded-3xl shadow-xl border border-slate-100 ring-8 ring-slate-50"><img src={selectedCard.imageUrl} className="w-full rounded-2xl shadow-inner" /></div>
                    <div className="p-6 bg-slate-50 rounded-2xl border border-slate-100 text-sm italic text-slate-600 flex items-start gap-4">
                       <i className="fa-solid fa-brain text-indigo-400 mt-1"></i>
                       <p>"{selectedCard.reasoning}"</p>
                    </div>
                 </div>
                 <div className="space-y-8">
                    <div className="flex flex-col gap-1 border-b border-slate-100 pb-6">
                       <div className="flex items-center gap-3">
                          <h1 className="text-3xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                          <a href={`https://www.google.com/search?q=${encodeURIComponent(`${selectedCard.firstName} ${selectedCard.lastName} ${selectedCard.company}`)}`} target="_blank" className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 transition-colors" title="Google Search"><i className="fa-brands fa-google text-xs"></i></a>
                       </div>
                       <p className="text-indigo-500 font-bold text-lg">{selectedCard.title}</p>
                       <div className={`mt-2 w-fit px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${selectedCard.category === 'employer' ? 'bg-indigo-100 text-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-100 text-emerald-600' : 'bg-amber-100 text-amber-600'}`}>{selectedCard.category}</div>
                    </div>
                    <div className="grid grid-cols-1 gap-6">
                       <InfoField icon="fa-university" label="機構 / 公司名稱" value={selectedCard.company} />
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-building" label="部門" value={selectedCard.department} />
                          <InfoField icon="fa-book-open" label="學科領域" value={selectedCard.subject} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-envelope" label="Email 電子郵件" value={selectedCard.email} />
                          <InfoField icon="fa-phone" label="聯絡電話 / 手機" value={selectedCard.phone || selectedCard.mobile} />
                       </div>
                       <div className="grid grid-cols-2 gap-4">
                          <InfoField icon="fa-location-dot" label="國家 / 地區" value={selectedCard.country} />
                          <InfoField icon="fa-industry" label="行業 (Industry)" value={selectedCard.industry} />
                       </div>
                       {selectedCard.website && <InfoField icon="fa-globe" label="官方網站" value={selectedCard.website} isLink />}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
          <div className="flex items-center gap-4"><i className="fa-solid fa-triangle-exclamation text-amber-400 text-xl"></i><span className="text-sm font-bold">{errorMsg}</span><button onClick={() => setErrorMsg(null)} className="ml-2 text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
          {apiPlan === 'free' && (
            <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
              立即填寫自有 API Key
            </button>
          )}
        </div>
      )}
    </div>
  );
};

