          <p className={`text-[11px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[9px] text-slate-400 truncate">{c.company}</p>
