      <aside 
        ref={sidebarRef}
        style={{ width: `${sidebarWidth}px` }}
        className={`fixed inset-y-0 left-0 z-50 lg:static flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}
      >
        <div className="p-4 border-b border-slate-300 bg-white/50 shrink-0">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <div className="flex gap-2">
              <button onClick={clearAllData} title="清空所有資料" className="w-6 h-6 rounded flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 transition-all"><i className="fa-solid fa-trash-can text-[10px]"></i></button>
              <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
            </div>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}>
