      {errorMsg && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-2xl shadow-2xl flex flex-col gap-3 z-[100] animate-in bounce-in max-w-lg border-2 border-amber-500/30">
