          {apiPlan === 'free' && (
            <button onClick={() => handlePlanSwitch('paid')} className="bg-indigo-600 hover:bg-indigo-500 py-2 rounded-xl text-xs font-black uppercase tracking-widest transition-all">立即填寫自有 API Key</button>
          )}
