    {count > 0 && <button onClick={(e) => { e.stopPropagation(); onClear(); }} className="absolute -top-1 -right-1 w-5 h-5 bg-white text-red-500 rounded-full shadow-lg border border-red-100 flex items-center justify-center opacity-0 group-hover/cat:opacity-100 transition-opacity hover:bg-red-50"><i className="fa-solid fa-xmark text-[8px]"></i></button>}
  </div>
);

