);

export default App;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  const db = await initDB();
  return new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    store.put(card);
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error);
  });
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

const deleteCardFromDB = async (id: string) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).delete(id);
};

const clearAllCardsFromDB = async () => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).clear();
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);

  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = e.clientX;
      if (newWidth > 320 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
        if (dbCards.length > 0) setSelectedCardId(dbCards[0].id);

        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
        setApiPlan(hasKey && savedPlan === 'paid' ? 'paid' : 'free');
      } catch (e) { console.error("DB Init Error", e); }
    };
    init();
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const readFileAsBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案已從記憶體中清除");

      const base64Data = await readFileAsBase64(fileObj);
      const mimeType = fileObj.type || 'image/jpeg';

      const info = await extractCardInfo(base64Data, mimeType);

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${mimeType};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      filesMap.current.delete(task.id);

      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      setProcessedInCurrentBatch(prev => prev + 1);
      if (!selectedCardId) setSelectedCardId(newCard.id);

      const delay = apiPlan === 'paid' ? 500 : 1200;
      await new Promise(r => setTimeout(r, delay));

    } catch (err: any) {
      console.error("Task Failed:", err);
      const msg = err.message?.toLowerCase() || "";
      if (msg.includes("quota") || msg.includes("429")) {
        setIsManualPaused(true); setIsPaused(true); setCooldown(75);
        setErrorMsg("API 配額已達上限！請檢查 API Key 或等待緩衝時間。");
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message || "辨識失敗" } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isPaused || isManualPaused || isProcessing) return;
    if (apiPlan === 'free' && processedInCurrentBatch >= 15) {
      setIsPaused(true); setCooldown(65); return;
    }
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isPaused, isManualPaused, isProcessing, processedInCurrentBatch, apiPlan]);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;
    const fileList = Array.from(files) as File[];
    const startIndex = tasks.length;

    const newTasks: ProcessingTask[] = [];
    for (let i = 0; i < fileList.length; i++) {
      const f = fileList[i];
      const taskId = crypto.randomUUID();
      filesMap.current.set(taskId, f);
      newTasks.push({ 
        id: taskId, 
        fileName: f.name, 
        status: 'pending', 
        progress: 0, 
        batchIndex: Math.floor((startIndex + i) / 15) + 1 
      });
    }
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
    event.target.value = '';
  };

  const handleCapture = async (b64: string) => {
    const taskId = crypto.randomUUID();
    const res = await fetch(`data:image/jpeg;base64,${b64}`);
    const blob = await res.blob();
    filesMap.current.set(taskId, blob);

    setTasks(prev => [...prev, { 
      id: taskId, 
      fileName: `現場拍攝_${new Date().toLocaleTimeString()}`, 
      status: 'pending', 
      progress: 0, 
      batchIndex: Math.floor(tasks.length/15)+1 
    }]);
    setViewMode('tasks');
  };

  const clearAllData = async () => {
    if (!confirm("警告：這將會永久刪除所有資料。確定嗎？")) return;
    await clearAllCardsFromDB();
    filesMap.current.clear();
    setCards([]);
    setTasks([]);
    setSelectedCardId(null);
    setProcessedInCurrentBatch(0);
    setIsProcessing(false);
  };

  const clearTasks = () => {
    if (tasks.length === 0) return;
    filesMap.current.clear();
    setTasks([]);
    setProcessedInCurrentBatch(0);
    setIsProcessing(false);
  };

  const clearCategory = async (category: 'employer' | 'academic' | 'staff') => {
    if (!confirm(`確定要清空所有 ${category.toUpperCase()}？`)) return;
    const targets = cards.filter(c => c.category === category);
    for (const c of targets) await deleteCardFromDB(c.id);
    setCards(prev => {
      const updated = prev.filter(c => c.category !== category);
      if (selectedCardId && prev.find(c => c.id === selectedCardId)?.category === category) setSelectedCardId(null);
      return updated;
    });
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const dataToExport = filtered.map(c => {
      const base = {
        'Source': c.source || 'AI Scan',
        'Title': c.prefix,
        'First Name': c.firstName,
        'Last Name': category === 'employer' ? c.lastName : undefined,
        'Last': category !== 'employer' ? c.lastName : undefined,
        'Position': category === 'employer' ? c.title : undefined,
        'Job Title': category !== 'employer' ? c.title : undefined,
        'Institution': category !== 'employer' ? c.company : undefined,
        'Company Name': category === 'employer' ? c.company : undefined,
        'Department': c.department,
        'Email': c.email,
        'Phone (Optional)': c.phone || c.mobile || '',
        'Country or Territory': c.country,
        'Industry': category === 'employer' ? c.industry : undefined,
        'Subject': category !== 'employer' ? c.subject : undefined,
      };
      return Object.fromEntries(Object.entries(base).filter(([_, v]) => v !== undefined));
    });
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, category.toUpperCase());
    XLSX.writeFile(workbook, `QS_Hub_${category.toUpperCase()}_Export.xlsx`);
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      await (window as any).aistudio.openSelectKey();
      if (await (window as any).aistudio.hasSelectedApiKey()) {
        setApiPlan('paid'); setIsPaused(false); setCooldown(0);
      }
    } else { setApiPlan('free'); }
  };

  const employerCards = useMemo(() => cards.filter(c => c.category === 'employer'), [cards]);
  const academicCards = useMemo(() => cards.filter(c => c.category === 'academic'), [cards]);
  const staffCards = useMemo(() => cards.filter(c => c.category === 'staff'), [cards]);
  const activeTasksCount = tasks.filter(t => t.status === 'processing' || t.status === 'pending').length;
  const groupedTasks = useMemo(() => {
    const groups: Record<number, ProcessingTask[]> = {};
    tasks.forEach(task => {
      if (!groups[task.batchIndex]) groups[task.batchIndex] = [];
      groups[task.batchIndex].push(task);
    });
    return Object.entries(groups).sort((a, b) => Number(a[0]) - Number(b[0]));
  }, [tasks]);
  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden bg-[#f3f3f3] ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      <aside style={{ width: `${sidebarWidth}px` }} className={`fixed inset-y-0 left-0 z-50 lg:static flex flex-col border-r border-slate-200 bg-[#ebebeb] transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 border-b border-slate-300 bg-white/50 shrink-0">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS Hub Data Ingester</h2>
            <div className="flex gap-2">
              <button onClick={clearAllData} className="w-6 h-6 rounded flex items-center justify-center text-slate-400 hover:text-red-500 hover:bg-red-50 transition-all"><i className="fa-solid fa-trash-can text-[10px]"></i></button>
              <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fa-solid fa-xmark"></i></button>
            </div>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費額度</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all flex items-center justify-center gap-1.5 ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400 hover:text-slate-600'}`}><i className="fa-solid fa-key text-[8px]"></i> 付費使用</button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <CategoryGroup color="indigo" label="Employer" count={employerCards.length} onExport={() => exportToExcel('employer')} onClear={() => clearCategory('employer')} />
            <CategoryGroup color="emerald" label="Academic" count={academicCards.length} onExport={() => exportToExcel('academic')} onClear={() => clearCategory('academic')} />
            <CategoryGroup color="amber" label="Staff" count={staffCards.length} onExport={() => exportToExcel('staff')} onClear={() => clearCategory('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="Emp" color="indigo" items={employerCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Aca" color="emerald" items={academicCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
          <Column title="Sta" color="amber" items={staffCards} activeId={selectedCardId} onSelect={id => {setSelectedCardId(id); setViewMode('detail');}} />
        </div>
      </aside>

      <div onMouseDown={startResizing} className="hidden lg:block w-1.5 cursor-col-resize hover:bg-indigo-500/20 transition-colors z-[60] shrink-0" />

      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 shrink-0 bg-white shadow-sm z-[70]">
          <div className="flex items-center gap-4">
             <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden text-slate-400"><i className="fa-solid fa-bars"></i></button>
             <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
                <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label={`進度 (${activeTasksCount})`} active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} highlight={activeTasksCount > 0} />
                {selectedCard && <NavBtn icon="fa-address-card" label="資料詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
          </div>
          <div className="flex items-center gap-4">
            <div className={`hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-full border text-[9px] font-black uppercase tracking-tight ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
               <i className={`fa-solid ${apiPlan === 'paid' ? 'fa-bolt animate-pulse' : 'fa-circle'}`}></i> {apiPlan === 'paid' ? '付費模式' : '免費模式'}
            </div>
            {isPaused && <div className="text-[10px] font-bold text-red-600 bg-red-50 px-3 py-1.5 rounded-full border border-red-200 tracking-tighter animate-pulse">{cooldown}s 緩衝冷卻中</div>}
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 bg-slate-50/20 custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={handleCapture} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
