import { GoogleGenAI, Type } from "@google/genai";

// Sleep helper function for retry logic
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, mimeType: string = 'image/jpeg', retryCount = 0): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `請從這張名片中提取聯絡資訊。

            【語言規則】：
            1. 必須使用名片上的「原始語言」提取資料（如名片是英文就提英文，繁體中文就提繁體中文）。
            2. 不要翻譯姓名、單位名稱或職稱，保持原樣輸出。

            【分類規則】：
            1. 'academic': 大學教研職位（教授、講師、院長、研究員）。
            2. 'staff': 大學行政或支持職位（註冊組、人事、IT、秘書、設施管理）。
            3. 'employer': 企業、私營機構或政府非教育單位。

            【額外屬性】：
            1. orientation: 判斷圖片需要「順時針旋轉」幾度才能轉正（僅限 0, 90, 180, 270）。
            2. reasoning: 用繁體中文簡述分類原因。
            3. subject: 若為 Academic/Staff，識別其學科領域。

            若欄位缺失請填空字串 ""。請回傳 JSON 格式。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING, description: "稱謂 (Mr/Ms/Dr/Prof)" },
            firstName: { type: Type.STRING, description: "名 (First Name)" },
            lastName: { type: Type.STRING, description: "姓 (Last Name)" },
            title: { type: Type.STRING, description: "職稱 (Job Title)" },
            company: { type: Type.STRING, description: "單位/公司名稱" },
            department: { type: Type.STRING, description: "部門" },
            industry: { type: Type.STRING, description: "產業 (Employer用)" },
            country: { type: Type.STRING, description: "國家/地區" },
            email: { type: Type.STRING, description: "電子郵件" },
            subject: { type: Type.STRING, description: "學科領域" },
            source: { type: Type.STRING, description: "來源" },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            orientation: { type: Type.NUMBER, description: "旋轉角度 (0/90/180/270)" },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING, description: "分類理由 (繁中)" },
          },
          required: ["prefix", "firstName", "lastName", "title", "company", "department", "industry", "country", "email", "category", "reasoning", "subject", "orientation"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");

    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedText);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    const isTransient = errorMessage.includes("503") || errorMessage.includes("overloaded") || errorMessage.includes("fetch");

    if (isTransient && retryCount < 3) {
      const delay = Math.pow(2, retryCount + 1) * 1000;
      await sleep(delay);
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

