export default App;

import React, { useRef, useState, useEffect } from 'react';

interface CameraScannerProps {
  onCapture: (base64: string) => void;
  onClose: () => void;
}

const CameraScanner: React.FC<CameraScannerProps> = ({ onCapture, onClose }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const startCamera = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment', 
          width: { ideal: 1920 }, 
          height: { ideal: 1080 } 
        } 
      });
      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }
      setIsReady(true);
    } catch (err: any) {
      // Fix: cast err to any to ensure property access for .name doesn't fail if treated as unknown
      const error = err as any;
      console.error(error);
      if (error.name === 'NotAllowedError' || error.name === 'PermissionDeniedError') {
        setError("相機權限遭拒：請至瀏覽器設定中允許此網頁存取相機，然後重試。");
      } else {
        setError("無法啟動相機：請確認設備具有相機功能或未被其他程式占用。");
      }
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [stream]);

  const capture = () => {
    if (videoRef.current && canvasRef.current && isReady) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const base64 = canvas.toDataURL('image/jpeg', 0.9).split(',')[1];
        onCapture(base64);
      }
    }
  };

  return (
    <div className="flex flex-col items-center justify-center h-full bg-slate-900 rounded-[2.5rem] overflow-hidden relative shadow-2xl border-8 border-slate-800">
      {!isReady ? (
        <div className="flex flex-col items-center justify-center p-8 text-center animate-in fade-in zoom-in duration-300">
          <div className="w-24 h-24 bg-white/10 rounded-full flex items-center justify-center mb-6 text-indigo-400">
             <i className={`fa-solid ${isLoading ? 'fa-circle-notch fa-spin' : 'fa-camera'} text-4xl`}></i>
          </div>

          {error ? (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-lg mb-2">啟動失敗</h3>
              <p className="text-slate-400 text-sm mb-6 leading-relaxed">{error}</p>
              <button 
                onClick={startCamera}
                className="bg-white text-slate-900 px-6 py-2.5 rounded-xl font-bold hover:bg-indigo-50 transition-colors"
              >
                再次嘗試開啟
              </button>
            </div>
          ) : (
            <div className="max-w-xs">
              <h3 className="text-white font-bold text-xl mb-2">準備進行拍攝</h3>
              <p className="text-slate-400 text-sm mb-8 leading-relaxed">點擊下方按鈕將會觸發相機權限請求。為了獲得最佳效果，請允許存取相機。</p>
              <button 
                onClick={startCamera}
                disabled={isLoading}
                className="w-full bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-indigo-900/40 hover:bg-indigo-500 transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                {isLoading ? '啟動中...' : '立即開啟相機'}
                {!isLoading && <i className="fa-solid fa-arrow-right"></i>}
              </button>
            </div>
          )}
        </div>
      ) : (
        <>
          <video ref={videoRef} autoPlay playsInline className="h-full w-full object-cover" />
          <canvas ref={canvasRef} className="hidden" />

          {/* Scanning UI Overlay */}
          <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
             <div className="w-full max-w-sm aspect-[1.6/1] border-2 border-white/50 rounded-2xl relative shadow-[0_0_0_100vmax_rgba(0,0,0,0.5)]">
                {/* Corner markers */}
                <div className="absolute top-0 left-0 w-8 h-8 border-t-4 border-l-4 border-indigo-400 -translate-x-1 -translate-y-1 rounded-tl-lg"></div>
                <div className="absolute top-0 right-0 w-8 h-8 border-t-4 border-r-4 border-indigo-400 translate-x-1 -translate-y-1 rounded-tr-lg"></div>
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b-4 border-l-4 border-indigo-400 -translate-x-1 translate-y-1 rounded-bl-lg"></div>
                <div className="absolute bottom-0 right-0 w-8 h-8 border-b-4 border-r-4 border-indigo-400 translate-x-1 translate-y-1 rounded-br-lg"></div>

                {/* Scanning line animation */}
                <div className="absolute top-0 left-0 w-full h-0.5 bg-indigo-400 shadow-[0_0_15px_rgba(129,140,248,1)] animate-[scan_3s_infinite_linear]"></div>

                <div className="absolute -bottom-10 left-0 right-0 text-center">
                  <span className="text-white/70 text-[10px] font-black uppercase tracking-widest bg-black/50 px-3 py-1 rounded-full">請將名片對準框內</span>
                </div>
             </div>
          </div>

          <div className="absolute bottom-10 left-0 right-0 flex justify-center items-center">
            <button 
              onClick={capture}
              className="w-20 h-20 rounded-full bg-white border-8 border-slate-700/50 flex items-center justify-center hover:scale-110 active:scale-95 transition-all shadow-2xl group"
            >
              <div className="w-12 h-12 rounded-full bg-indigo-600 group-hover:bg-indigo-500 transition-colors"></div>
            </button>
          </div>

          <button 
            onClick={() => {
              if (stream) stream.getTracks().forEach(t => t.stop());
              setIsReady(false);
            }}
            className="absolute top-6 right-6 w-10 h-10 bg-black/40 text-white rounded-full flex items-center justify-center hover:bg-black/60 transition-colors"
          >
            <i className="fa-solid fa-rotate-left"></i>
          </button>
        </>
      )}
      <style>{`
        @keyframes scan {
          0% { top: 0%; opacity: 0; }
          10% { opacity: 1; }
          90% { opacity: 1; }
          100% { top: 100%; opacity: 0; }
        }
      `}</style>
    </div>
  );
};

export default CameraScanner;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).put(card);
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

const deleteCardFromDB = async (id: string) => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(id);
};

const clearAllCardsFromDB = async () => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).clear();
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotation, setManualRotation] = useState(0);

  const [isPaused, setIsPaused] = useState(false);
  const [isManualPaused, setIsManualPaused] = useState(false);
  const [cooldown, setCooldown] = useState(0);
  const [processedInCurrentBatch, setProcessedInCurrentBatch] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = e.clientX;
      if (newWidth > 320 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
        if (dbCards.length > 0) setSelectedCardId(dbCards[0].id);

        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
        setApiPlan(hasKey && savedPlan === 'paid' ? 'paid' : 'free');
      } catch (e) { console.error("DB Init Error", e); }
    };
    init();
  }, []);

  useEffect(() => {
    localStorage.setItem('qs_hub_api_plan', apiPlan);
  }, [apiPlan]);

  useEffect(() => {
    if (cooldown > 0) {
      const timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (cooldown === 0 && isPaused) {
      setIsPaused(false);
      setProcessedInCurrentBatch(0);
    }
  }, [cooldown, isPaused]);

  const readFileAsBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);

    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案丟失");

      const base64Data = await readFileAsBase64(fileObj);
      const mimeType = fileObj.type || 'image/jpeg';
      const info = await extractCardInfo(base64Data, mimeType);

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${mimeType};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      filesMap.current.delete(task.id);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      setProcessedInCurrentBatch(prev => prev + 1);
      if (!selectedCardId) setSelectedCardId(newCard.id);
      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 500 : 1200));

    } catch (err: any) {
      // Fix: cast err to any to ensure properties like .message or .name are accessible
      const error = err as any;
      console.error(error);

      // Handle "Requested entity was not found." as per guidelines
      if (error.message?.includes("Requested entity was not found")) {
        localStorage.removeItem('qs_hub_api_plan');
        setApiPlan('free');
        setErrorMsg("API Key 效期已過或設定錯誤，請重新選取。");
      } else if (error.message?.includes("429")) {
        setIsPaused(true); 
        setCooldown(75);
        setErrorMsg("API 限制中，請稍候。");
      }

      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: error.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isPaused || isProcessing) return;
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isPaused, isProcessing]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;
    // Fix: Cast the result of Array.from to File[] to avoid 'unknown' type issues in map
    const fileList = Array.from(files) as File[];
    const newTasks: ProcessingTask[] = fileList.map((f, i) => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0,
      batchIndex: Math.floor((tasks.length + i) / 15) + 1
    }));
    newTasks.forEach((t, i) => filesMap.current.set(t.id, fileList[i]));
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
  };

  const handleCapture = async (b64: string) => {
    const taskId = crypto.randomUUID();
    const res = await fetch(`data:image/jpeg;base64,${b64}`);
    filesMap.current.set(taskId, await res.blob());
    setTasks(prev => [...prev, { id: taskId, fileName: `快照_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
    setViewMode('tasks');
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const dataToExport = filtered.map(c => ({
      '原文單位': c.company,
      '原文職稱': c.title,
      '姓': c.lastName,
      '名': c.firstName,
      'Email': c.email,
      '電話': c.phone || c.mobile,
      '國家': c.country,
      '備註/註解': Object.values(c.translations || {}).filter(v => v && v !== c.company && v !== c.title).join('; ')
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'QS_Export');
    XLSX.writeFile(workbook, `QS_Data_${category}.xlsx`);
  };

  const clearAllData = async () => {
    if (!confirm("確定刪除所有資料？")) return;
    await clearAllCardsFromDB();
    setCards([]);
    setSelectedCardId(null);
  };

  const handlePlanSwitch = async (plan: ApiPlan) => {
    if (plan === 'paid') {
      await (window as any).aistudio.openSelectKey();
      setApiPlan('paid');
    } else { setApiPlan('free'); }
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => ((selectedCard?.orientation || 0) + manualRotation) % 360, [selectedCard, manualRotation]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden bg-[#f3f3f3] ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      {/* Lightbox / 對比模式 */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[999] bg-slate-900/95 flex animate-in fade-in duration-200">
          <div className="flex w-full h-full">
            <div className="flex-1 flex flex-col items-center justify-center p-6 relative border-r border-white/10 overflow-hidden">
               <div className="absolute top-6 left-6 flex items-center gap-6 z-10">
                  <div className="text-white/40 text-xs font-black uppercase">名片原文核對 (轉正模式)</div>
                  <button onClick={() => setManualRotation(prev => (prev + 90) % 360)} className="bg-white/10 text-white px-4 py-2 rounded-full text-xs font-bold border border-white/10 hover:bg-white/20 transition-all">手動旋轉</button>
               </div>
               <img 
                 src={selectedCard.imageUrl} 
                 style={{ transform: `rotate(${currentRotation}deg)` }}
                 className="max-w-full max-h-[85vh] object-contain shadow-2xl rounded-lg transition-transform duration-300"
                 alt="Original"
               />
            </div>
            <div className="w-[480px] bg-white h-full flex flex-col shadow-2xl">
               <header className="p-6 border-b border-slate-100 flex items-center justify-between">
                  <h2 className="text-xl font-black text-slate-800 tracking-tighter">原文與註解核對</h2>
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center hover:bg-red-50 hover:text-red-500"><i className="fa-solid fa-xmark"></i></button>
               </header>
               <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                  <ComparisonField label="名片全名 (原文)" value={[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')} />
                  <ComparisonField label="單位名稱" value={selectedCard.company} translation={selectedCard.translations?.company} highlight />
                  <ComparisonField label="職稱" value={selectedCard.title} translation={selectedCard.translations?.title} highlight />
                  <ComparisonField label="部門" value={selectedCard.department} translation={selectedCard.translations?.department} />
                  <ComparisonField label="Email" value={selectedCard.email} />
                  <ComparisonField label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                  <ComparisonField label="分類理由 (AI)" value={selectedCard.reasoning} isSmall />
               </div>
               <footer className="p-6 bg-slate-50 border-t border-slate-100">
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-full bg-slate-800 text-white py-4 rounded-2xl font-black text-xs uppercase hover:bg-indigo-600 transition-all">核對完成</button>
               </footer>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside style={{ width: `${sidebarWidth}px` }} className="flex flex-col border-r border-slate-200 bg-[#ebebeb] shrink-0">
        <div className="p-4 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">QS HUB DATA SCANNER</h2>
            <button onClick={clearAllData} className="text-slate-400 hover:text-red-500"><i className="fa-solid fa-trash-can text-xs"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => handlePlanSwitch('free')} className={`flex-1 py-2 text-[10px] font-black rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費</button>
             <button onClick={() => handlePlanSwitch('paid')} className={`flex-1 py-2 text-[10px] font-black rounded-lg transition-all ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-lg text-white' : 'text-slate-400'}`}>API Key</button>
          </div>
          <div className="grid grid-cols-3 gap-1">
            <CategoryGroup color="indigo" label="企業" count={cards.filter(c=>c.category==='employer').length} onExport={() => exportToExcel('employer')} />
            <CategoryGroup color="emerald" label="教研" count={cards.filter(c=>c.category==='academic').length} onExport={() => exportToExcel('academic')} />
            <CategoryGroup color="amber" label="行政" count={cards.filter(c=>c.category==='staff').length} onExport={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <Column title="企業雇主" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
          <Column title="大學教研" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
          <Column title="大學行政" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <div onMouseDown={startResizing} className="w-1 cursor-col-resize hover:bg-indigo-500 transition-colors z-[60]" />

      {/* Main Content */}
      <main className="flex-1 flex flex-col bg-white">
        <header className="h-16 border-b border-slate-100 flex items-center justify-between px-6 bg-white shadow-sm">
           <nav className="flex items-center bg-slate-100 p-1 rounded-xl">
              <NavBtn icon="fa-camera" label="單張拍照" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
              <NavBtn icon="fa-folder-open" label="批量上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
              <NavBtn icon="fa-list-check" label="辨識進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
              {selectedCard && <NavBtn icon="fa-address-card" label="資料詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
           </nav>
           <div className={`px-4 py-1.5 rounded-full border text-[10px] font-black uppercase ${apiPlan === 'paid' ? 'bg-indigo-50 border-indigo-200 text-indigo-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
              {apiPlan === 'paid' ? '專業付費模式' : '免費額度模式'}
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 bg-slate-50/20 custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={handleCapture} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="p-16 border-2 border-dashed border-slate-200 rounded-[3rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-transform"><i className="fa-solid fa-cloud-arrow-up text-3xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">點擊或拖放名片圖片</h3>
                <p className="text-slate-400 text-sm mt-2">支援多張上傳，系統將自動提取名片原文並標註中文。</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-4xl mx-auto space-y-6">
               <h2 className="text-2xl font-black text-slate-800">掃描任務隊列</h2>
               {tasks.length === 0 ? <p className="text-center py-20 text-slate-300 italic">尚無待處理任務</p> : (
                 <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm">
                   <table className="w-full text-left">
                     <tbody>
                       {tasks.map(t => (
                         <tr key={t.id} className="border-b border-slate-50 last:border-0">
                           <td className="px-6 py-4 font-bold text-slate-700">{t.fileName}</td>
                           <td className="px-6 py-4">
                              {t.status === 'processing' ? <span className="text-indigo-500 animate-pulse"><i className="fa-solid fa-spinner fa-spin mr-2"></i>辨識中</span> : 
                               t.status === 'completed' ? <span className="text-emerald-500 font-bold"><i className="fa-solid fa-check mr-2"></i>成功</span> :
                               t.status === 'error' ? <span className="text-red-500 font-bold">失敗</span> : <span className="text-slate-300">排隊中</span>}
                           </td>
                         </tr>
                       ))}
                     </tbody>
                   </table>
                 </div>
               )}
            </div>
          ) : selectedCard ? (
            <div className="max-w-7xl mx-auto animate-in fade-in slide-in-from-bottom-4">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                 <div className="lg:col-span-5">
                    <div className="sticky top-0 space-y-6">
                      <div onClick={() => setIsImageModalOpen(true)} className="group relative bg-white p-4 rounded-[2.5rem] shadow-xl border border-slate-100 cursor-zoom-in ring-8 ring-slate-50 transition-all active:scale-95 overflow-hidden">
                        <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="w-full h-auto rounded-xl shadow-sm transition-transform duration-300" alt="Card" />
                        <div className="absolute inset-0 bg-indigo-600/0 group-hover:bg-indigo-600/5 transition-all opacity-0 group-hover:opacity-100 flex items-center justify-center">
                           <div className="bg-white shadow-lg px-6 py-3 rounded-full font-black text-xs text-indigo-600 tracking-widest uppercase">進入對比模式</div>
                        </div>
                      </div>
                      <div className="p-6 bg-indigo-50/50 rounded-3xl border border-indigo-100 shadow-inner">
                         <div className="text-[10px] font-black text-indigo-400 uppercase mb-3 tracking-widest">AI 判定分類理由</div>
                         <p className="text-sm text-slate-600 italic leading-relaxed">"{selectedCard.reasoning}"</p>
                      </div>
                    </div>
                 </div>

                 <div className="lg:col-span-7 space-y-10">
                    <div className="border-b border-slate-100 pb-8 min-h-[140px]">
                       <h1 className="text-5xl font-black text-slate-800 tracking-tighter mb-2">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                       <div className="flex items-center gap-3">
                          <p className="text-2xl font-bold text-indigo-500">{selectedCard.title}</p>
                          {selectedCard.translations?.title && <span className="text-sm font-medium text-slate-400 bg-slate-100 px-3 py-1 rounded-lg">[{selectedCard.translations.title}]</span>}
                       </div>
                       <div className={`mt-6 w-fit px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest text-white shadow-lg ${selectedCard.category === 'employer' ? 'bg-indigo-600' : selectedCard.category === 'academic' ? 'bg-emerald-600' : 'bg-amber-600'}`}>
                         {selectedCard.category === 'employer' ? '企業雇主' : selectedCard.category === 'academic' ? '大學教研' : '大學行政'}
                       </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-x-10 gap-y-10">
                       <InfoField label="單位/公司 (原文)" value={selectedCard.company} translation={selectedCard.translations?.company} fullWidth />
                       <InfoField label="部門" value={selectedCard.department} translation={selectedCard.translations?.department} />
                       <InfoField label="電子郵件" value={selectedCard.email} />
                       <InfoField label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       <InfoField label="國家/地區" value={selectedCard.country} />
                       {selectedCard.category === 'employer' ? (
                          <InfoField label="產業類型" value={selectedCard.industry} translation={selectedCard.translations?.industry} />
                       ) : (
                          <InfoField label="學科領域 (Subject)" value={selectedCard.subject} translation={selectedCard.translations?.subject} />
                       )}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {errorMsg && <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-10 py-5 rounded-3xl shadow-2xl flex items-center gap-4 border-2 border-indigo-500 animate-in bounce-in z-[100]">
        <i className="fa-solid fa-triangle-exclamation text-amber-400"></i>
        <span className="font-bold text-sm">{errorMsg}</span>
        <button onClick={() => setErrorMsg(null)} className="ml-4 text-slate-400"><i className="fa-solid fa-xmark"></i></button>
      </div>}
    </div>
  );
};

const ComparisonField = ({ label, value, translation, highlight, isSmall }: any) => (
  <div className="flex flex-col gap-1.5">
    <label className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{label}</label>
