import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).put(card);
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

const deleteCardFromDB = async (id: string) => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).delete(id);
};

const clearAllCardsFromDB = async () => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).clear();
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotation, setManualRotation] = useState(0);

  const [isPaused, setIsPaused] = useState(false);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = e.clientX;
      if (newWidth > 320 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
        if (dbCards.length > 0) setSelectedCardId(dbCards[0].id);

        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
        setApiPlan(hasKey && savedPlan === 'paid' ? 'paid' : 'free');
      } catch (e) { console.error("DB Init Error", e); }
    };
    init();
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案丟失");

      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });

      const mimeType = fileObj.type || 'image/jpeg';
      const info = await extractCardInfo(base64Data, mimeType);

      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${mimeType};base64,${base64Data}`,
      };

      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      filesMap.current.delete(task.id);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 500 : 1200));

    } catch (err: any) {
      const error = err as any;
      console.error(error);
      if (error.message?.includes("Requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 無效，請重新設定。");
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: error.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isPaused || isProcessing) return;
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isPaused, isProcessing]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;
    const fileList = Array.from(files) as File[];
    const newTasks: ProcessingTask[] = fileList.map((f, i) => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0,
      batchIndex: 1
    }));
    newTasks.forEach((t, i) => filesMap.current.set(t.id, fileList[i]));
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;
    const dataToExport = filtered.map(c => ({
      'Title (Salutation)': c.prefix,
      'First Name (Given Name)': c.firstName,
      'Last Name (Surname)': c.lastName,
      'Job Title (Original)': c.title,
      'Job Title (Chinese Note)': c.translations?.title || '',
      'Institution / Company (Original)': c.company,
      'Institution / Company (Chinese Note)': c.translations?.company || '',
      'Department': c.department,
      'Subject Area / Industry': c.category === 'employer' ? c.industry : c.subject,
      'Country / Territory': c.country,
      'Email Address': c.email,
      'Phone / Mobile': c.phone || c.mobile,
      'Source': c.source || 'QS Hub Scanner'
    }));
    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'QS Filing Data');
    XLSX.writeFile(workbook, `QS_Data_Export_${category}.xlsx`);
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => ((selectedCard?.orientation || 0) + manualRotation) % 360, [selectedCard, manualRotation]);

  const handleManualRotate = (e: React.MouseEvent) => {
    e.stopPropagation();
    setManualRotation(prev => (prev + 90) % 360);
  };

  return (
    <div className={`flex h-screen w-screen overflow-hidden bg-[#f3f3f3] ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      {/* Lightbox / Comparison Mode */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[999] bg-slate-900/95 flex animate-in fade-in duration-200">
          <div className="flex w-full h-full">
            <div className="flex-1 flex flex-col items-center justify-center p-6 relative border-r border-white/10 overflow-hidden">
               <div className="absolute top-6 left-6 flex items-center gap-6 z-10">
                  <div className="text-white/40 text-[10px] font-black uppercase tracking-widest bg-black/30 px-3 py-1 rounded-md">名片原文核對模式</div>
                  <button onClick={handleManualRotate} className="bg-white/10 text-white px-4 py-2 rounded-full text-xs font-bold border border-white/10 hover:bg-white/20 transition-all">旋轉圖片</button>
               </div>
               <img 
                 src={selectedCard.imageUrl} 
                 style={{ transform: `rotate(${currentRotation}deg)` }}
                 className="max-w-full max-h-[85vh] object-contain shadow-2xl rounded-lg transition-transform duration-300"
                 alt="Original"
               />
            </div>
            <div className="w-[500px] bg-white h-full flex flex-col shadow-2xl overflow-hidden">
               <header className="p-6 border-b border-slate-100 flex items-center justify-between shrink-0">
                  <div>
                    <h2 className="text-xl font-black text-slate-800 tracking-tighter">QS 資料核對專區</h2>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-0.5">QS Data Verification</p>
                  </div>
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-colors"><i className="fa-solid fa-xmark"></i></button>
               </header>
               <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 shadow-inner">
                     <p className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-2">AI 判定分類與理由</p>
                     <p className="text-sm text-slate-600 italic leading-relaxed font-medium">"{selectedCard.reasoning}"</p>
                  </div>

                  <div className="space-y-4">
                    <QSField label="稱謂 (Prefix)" value={selectedCard.prefix} />
                    <QSField label="名 (First Name)" value={selectedCard.firstName} />
                    <QSField label="姓 (Last Name)" value={selectedCard.lastName} />
                    <QSField label="單位名稱 (Institution / Company)" value={selectedCard.company} translation={selectedCard.translations?.company} highlight />
                    <QSField label="職稱 (Job Title)" value={selectedCard.title} translation={selectedCard.translations?.title} highlight />
                    <QSField label="部門 (Department)" value={selectedCard.department} translation={selectedCard.translations?.department} />
                    <QSField label="國家/地區 (Country / Territory)" value={selectedCard.country} />
                    <QSField label="電子郵件 (Email Address)" value={selectedCard.email} />
                    {selectedCard.category === 'employer' ? (
                       <QSField label="產業類型 (Industry)" value={selectedCard.industry} translation={selectedCard.translations?.industry} />
                    ) : (
                       <QSField label="學科領域 (Subject Area)" value={selectedCard.subject} translation={selectedCard.translations?.subject} />
                    )}
                  </div>
               </div>
               <footer className="p-6 bg-slate-50 border-t border-slate-100 shrink-0">
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-full bg-slate-800 text-white py-4 rounded-2xl font-black text-xs uppercase hover:bg-indigo-600 transition-all shadow-lg">核對無誤並關閉</button>
               </footer>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside style={{ width: `${sidebarWidth}px` }} className="flex flex-col border-r border-slate-200 bg-[#ebebeb] shrink-0">
        <div className="p-5 border-b border-slate-300 bg-white/50">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">QS Hub Data Scanner</h2>
            <button onClick={() => { if(confirm("清除所有資料？")) { clearAllCardsFromDB(); setCards([]); setSelectedCardId(null); } }} className="text-slate-300 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can text-xs"></i></button>
