      </main>

      {errorMsg && <div className="fixed bottom-12 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-12 py-6 rounded-3xl shadow-[0_30px_60px_rgba(0,0,0,0.5)] flex items-center gap-6 border-2 border-indigo-500/50 animate-in bounce-in z-[100] max-w-xl">
        <div className="w-12 h-12 bg-indigo-600/20 rounded-2xl flex items-center justify-center text-indigo-400 shrink-0"><i className="fa-solid fa-circle-exclamation text-xl"></i></div>
        <div className="flex-1">
          <p className="font-black text-sm tracking-tight">{errorMsg}</p>
          <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Please update your configuration</p>
