const DataColumn = ({ title, color, items, activeId, onSelect }: any) => (
  <div className="w-1/3 flex flex-col border-r border-slate-100 last:border-0">
    <div className="h-9 flex items-center justify-center bg-slate-50 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-tighter shrink-0">{title}</div>
    <div className="flex-1 overflow-y-auto custom-scrollbar p-1.5 space-y-1">
      {items.map(c => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2.5 rounded-lg cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-md border-${color}-400 ring-2 ring-${color}-400/5` : 'border-transparent hover:bg-slate-50'}`}>
          <p className={`text-[10px] font-bold truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-600'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[8px] text-slate-300 font-bold truncate mt-1">{c.company}</p>
        </div>
      ))}
    </div>
  </div>
);

export default App;

import { GoogleGenAI, Type } from "@google/genai";

// Sleep helper function for retry logic
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const extractCardInfo = async (base64Image: string, mimeType: string = 'image/jpeg', retryCount = 0): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = 'gemini-3-flash-preview';

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Image,
            },
          },
          {
            text: `請從這張名片中提取資訊，並將其格式化為「QS 資料填報」標準。

            【核心提取規則】：
            1. 姓名、單位、職稱等核心欄位必須嚴格抓取「名片原文」。
            2. 若原文為英文或外語，請在 'translations' 物件中提供精準的「中文對應註解」。
            3. 分類標準：
               - 'academic': 大學教研人員（Academic Reputation）。
               - 'staff': 大學行政支持人員。
               - 'employer': 企業雇主（Employer Reputation）。

            【QS 欄位定義】：
            - prefix: 稱謂 (Mr, Ms, Dr, Prof 等)
            - firstName: 名 (First Name)
            - lastName: 姓 (Last Name)
            - title: 職稱 (Job Title)
            - company: 單位名稱 (Institution / Company Name)
            - department: 部門 (Department)
            - subject: 學科領域 (Subject Area - 教研類必填)
            - industry: 產業 (Industry - 雇主類必填)
            - country: 國家/地區 (Country / Territory)

            【額外屬性】：
            - orientation: 轉正角度 (0, 90, 180, 270)。
            - reasoning: 分類理由 (繁中)。

            【重要提示】：
            - 請僅回傳要求的 JSON 格式，嚴禁回傳任何圖像數據或 Base64 字串。
            - 確保所有欄位值皆為提取到的文本。`,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            prefix: { type: Type.STRING },
            firstName: { type: Type.STRING },
            lastName: { type: Type.STRING },
            title: { type: Type.STRING },
            company: { type: Type.STRING },
            department: { type: Type.STRING },
            industry: { type: Type.STRING },
            country: { type: Type.STRING },
            email: { type: Type.STRING },
            subject: { type: Type.STRING },
            source: { type: Type.STRING },
            phone: { type: Type.STRING },
            mobile: { type: Type.STRING },
            orientation: { type: Type.NUMBER },
            category: { type: Type.STRING, enum: ["employer", "academic", "staff"] },
            reasoning: { type: Type.STRING },
            translations: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                company: { type: Type.STRING },
                department: { type: Type.STRING },
                industry: { type: Type.STRING },
                subject: { type: Type.STRING }
              }
            }
          },
          required: ["firstName", "lastName", "title", "company", "category", "orientation", "translations"],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("AI 回應為空");

    // 額外清理邏輯，防止 JSON 解析錯誤
    const cleanedText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    return JSON.parse(cleanedText);

  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("503") && retryCount < 3) {
      await sleep(Math.pow(2, retryCount + 1) * 1000);
      return extractCardInfo(base64Image, mimeType, retryCount + 1);
    }
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 2);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).put(card);
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

const clearAllCardsFromDB = async () => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).clear();
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotation, setManualRotation] = useState(0);
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  const startResizing = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
  }, []);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing) {
      const newWidth = e.clientX;
      if (newWidth > 320 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing]);

  const handleManualRotate = useCallback(() => {
    setManualRotation(prev => (prev + 90) % 360);
  }, []);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
        if (dbCards.length > 0) setSelectedCardId(dbCards[0].id);
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
        setApiPlan(hasKey && savedPlan === 'paid' ? 'paid' : 'free');
      } catch (e) { console.error("DB Init Error", e); }
    };
    init();
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案丟失");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 500 : 1500));
    } catch (err: any) {
      const error = err as any;
      console.error(error);
      if (error.message?.includes("Requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 效期已過，請重新設定。");
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: error.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isProcessing) return;
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isProcessing]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;
    const fileList = Array.from(files) as File[];
    const newTasks: ProcessingTask[] = fileList.map((f) => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0,
      batchIndex: 1
    }));
    newTasks.forEach((t, i) => filesMap.current.set(t.id, fileList[i]));
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;

    // 根據圖片格式精確對齊欄位標題
    const dataToExport = filtered.map(c => {
      if (category === 'employer') {
        return {
          'Source': c.source || 'QS Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Position': c.title,
          'Industry': c.industry,
          'Company Name': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      } else {
        // Academic 或 Staff 格式
        return {
          'Source': c.source || 'QS Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Job Title': c.title,
          'Department': c.department,
          'Institution': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Subject': c.subject,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      }
    });

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'QS Data');
    XLSX.writeFile(workbook, `QS_Export_${category}.xlsx`);
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => ((selectedCard?.orientation || 0) + manualRotation) % 360, [selectedCard, manualRotation]);

  return (
    <div className={`flex h-screen w-screen overflow-hidden bg-[#f8fafc] ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      {/* Lightbox */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[999] bg-slate-900/98 flex animate-in fade-in duration-200">
          <div className="flex w-full h-full">
            <div className="flex-1 flex flex-col items-center justify-center p-10 relative overflow-hidden">
               <div className="absolute top-6 left-6 flex items-center gap-4 z-10">
                  <button onClick={handleManualRotate} className="bg-white/10 text-white px-5 py-2.5 rounded-full text-xs font-bold border border-white/20 hover:bg-white/20 transition-all flex items-center gap-2">
                    <i className="fa-solid fa-rotate-right"></i> 旋轉圖片
                  </button>
               </div>
               <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="max-w-full max-h-[90vh] object-contain shadow-2xl rounded-lg transition-transform duration-300" />
            </div>
            <div className="w-[450px] bg-white h-full flex flex-col shadow-2xl">
               <header className="p-6 border-b border-slate-100 flex items-center justify-between">
                  <h2 className="text-lg font-black text-slate-800">QS 資料核對</h2>
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-colors"><i className="fa-solid fa-xmark"></i></button>
               </header>
               <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
                  <QSField label="單位名稱" value={selectedCard.company} translation={selectedCard.translations?.company} />
                  <QSField label="職稱" value={selectedCard.title} translation={selectedCard.translations?.title} />
                  <QSField label="名" value={selectedCard.firstName} />
                  <QSField label="姓" value={selectedCard.lastName} />
                  <QSField label="Email" value={selectedCard.email} />
               </div>
               <footer className="p-6 bg-slate-50 border-t border-slate-100">
                  <button onClick={() => { setIsImageModalOpen(false); setManualRotation(0); }} className="w-full bg-slate-800 text-white py-4 rounded-xl font-bold hover:bg-indigo-600 transition-all">關閉核對</button>
               </footer>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar */}
      <aside style={{ width: `${sidebarWidth}px` }} className="flex flex-col border-r border-slate-200 bg-white shrink-0">
        <div className="p-5 border-b border-slate-100 bg-slate-50/50">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">QS HUB SCANNER</h2>
            <button onClick={() => { if(confirm("清除所有資料？")) { clearAllCardsFromDB(); setCards([]); setSelectedCardId(null); } }} className="text-slate-300 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can text-xs"></i></button>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-5">
             <button onClick={() => setApiPlan('free')} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費</button>
             <button onClick={async () => { await (window as any).aistudio.openSelectKey(); setApiPlan('paid'); }} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-md text-white' : 'text-slate-400'}`}>專業</button>
          </div>
          <div className="grid grid-cols-3 gap-1.5">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => exportToExcel('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => exportToExcel('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); }} />
        </div>
      </aside>

      <div onMouseDown={startResizing} className="w-1 cursor-col-resize hover:bg-indigo-500 transition-colors z-[60]" />

      {/* Main Content */}
      <main className="flex-1 flex flex-col bg-white">
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-6 bg-white shrink-0 shadow-sm">
           <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl">
              <NavBtn icon="fa-camera" label="單張掃描" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
              <NavBtn icon="fa-folder-open" label="批量上傳" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
              <NavBtn icon="fa-list-check" label="辨識進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
              {selectedCard && <NavBtn icon="fa-address-card" label="填報詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
           </nav>
           <div className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider ${apiPlan === 'paid' ? 'bg-indigo-50 text-indigo-600 border border-indigo-100' : 'bg-slate-50 text-slate-400 border border-slate-200'}`}>
              {apiPlan === 'paid' ? 'PRO MODE' : 'FREE MODE'}
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-10 bg-[#fbfcfd] custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto"><CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `Scan_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
                setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center bg-white shadow-sm group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-transform"><i className="fa-solid fa-upload text-2xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳 QS 填報資料</h3>
                <p className="text-slate-400 text-sm mt-2 max-w-xs mx-auto">點擊選擇名片圖片，系統將自動對齊 QS 欄位。</p>
