  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => {
    if (!selectedCard) return 0;
    return (manualRotations[selectedCard.id] || 0) % 360;
