import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 2);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  const db = await initDB();
  const transaction = db.transaction(STORE_NAME, 'readwrite');
  transaction.objectStore(STORE_NAME).put(card);
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  const db = await initDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result || []);
    request.onerror = () => reject(request.error);
  });
};

const clearAllCardsFromDB = async () => {
  const db = await initDB();
  db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).clear();
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState('file' as ViewMode);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotations, setManualRotations] = useState<Record<string, number>>({});
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Resize listener for mobile state
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const startResizing = useCallback((e: React.MouseEvent) => {
    if (isMobile) return;
    e.preventDefault();
    setIsResizing(true);
  }, [isMobile]);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && !isMobile) {
      const newWidth = e.clientX;
      if (newWidth > 300 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing, isMobile]);

  const handleManualRotate = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedCardId) {
      setManualRotations(prev => ({
        ...prev,
        [selectedCardId]: ((prev[selectedCardId] || 0) + 90) % 360
      }));
    }
  }, [selectedCardId]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
        if (dbCards.length > 0) setSelectedCardId(dbCards[0].id);

        // SAFE window.aistudio check
        const aistudio = (window as any).aistudio;
        let hasKey = false;
        if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
          hasKey = await aistudio.hasSelectedApiKey();
        }

        const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
        setApiPlan(hasKey && savedPlan === 'paid' ? 'paid' : 'free');
      } catch (e) { 
        console.error("Initialization failed", e);
        setErrorMsg("系統載入異常，請重整頁面。");
      }
    };
    init();
  }, []);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案丟失");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
      await new Promise(r => setTimeout(r, apiPlan === 'paid' ? 500 : 1500));
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 效期已過，請重新設定。");
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isProcessing) return;
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isProcessing]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;
    const fileList = Array.from(files) as File[];
    const newTasks: ProcessingTask[] = fileList.map((f) => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0,
      batchIndex: 1
    }));
    newTasks.forEach((t, i) => filesMap.current.set(t.id, fileList[i]));
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;

    const dataToExport = filtered.map(c => {
      if (category === 'employer') {
        return {
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Position': c.title,
          'Industry': c.industry,
          'Company Name': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      } else {
        return {
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Job Title': c.title,
          'Department': c.department,
          'Institution': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Subject': c.subject,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      }
    });

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'QS Data');
    XLSX.writeFile(workbook, `QS_Export_${category}.xlsx`);
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => {
    if (!selectedCard) return 0;
    return (manualRotations[selectedCard.id] || 0) % 360;
  }, [selectedCard, manualRotations]);

  return (
    <div className={`flex h-screen h-[100dvh] w-screen overflow-hidden bg-[#f8fafc] ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      {/* Lightbox */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[999] bg-slate-900/98 flex animate-in fade-in duration-200">
          <div className="flex w-full h-full flex-col md:flex-row">
            <div className="flex-1 flex flex-col items-center justify-center p-4 md:p-10 relative overflow-hidden">
               <div className="absolute top-4 left-4 flex items-center gap-4 z-10">
                  <button onClick={handleManualRotate} className="bg-white/10 text-white px-4 py-2 rounded-full text-xs font-bold border border-white/20 hover:bg-white/20 transition-all flex items-center gap-2">
                    <i className="fa-solid fa-rotate-right"></i> 旋轉
                  </button>
               </div>
               <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="max-w-full max-h-[60vh] md:max-h-[90vh] object-contain shadow-2xl rounded-lg transition-transform duration-300" />
            </div>
            <div className="w-full md:w-[450px] bg-white h-1/2 md:h-full flex flex-col shadow-2xl overflow-hidden">
               <header className="p-4 md:p-6 border-b border-slate-100 flex items-center justify-between">
                  <h2 className="text-lg font-black text-slate-800">QS 資料核對</h2>
                  <button onClick={() => { setIsImageModalOpen(false); }} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center hover:bg-red-50 hover:text-red-500 transition-colors"><i className="fa-solid fa-xmark"></i></button>
               </header>
               <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6 custom-scrollbar">
                  <QSField label="單位名稱" value={selectedCard.company} translation={selectedCard.translations?.company} />
                  <QSField label="職稱" value={selectedCard.title} translation={selectedCard.translations?.title} />
                  <QSField label="名" value={selectedCard.firstName} />
                  <QSField label="姓" value={selectedCard.lastName} />
                  <QSField label="Email" value={selectedCard.email} />
               </div>
               <footer className="p-4 md:p-6 bg-slate-50 border-t border-slate-100">
                  <button onClick={() => { setIsImageModalOpen(false); }} className="w-full bg-slate-800 text-white py-4 rounded-xl font-bold hover:bg-indigo-600 transition-all">關閉核對</button>
               </footer>
            </div>
          </div>
        </div>
      )}

      {/* Sidebar - Enhanced Responsive logic */}
      <aside 
        style={{ width: isMobile ? '100%' : `${sidebarWidth}px` }} 
        className={`fixed inset-0 z-50 lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out flex flex-col border-r border-slate-200 bg-white shrink-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b border-slate-100 bg-slate-50/50 shrink-0">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">QS HUB SCANNER</h2>
            <div className="flex items-center gap-2">
              <button onClick={() => { if(confirm("清除所有資料？")) { clearAllCardsFromDB(); setCards([]); setSelectedCardId(null); } }} className="text-slate-300 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can text-xs"></i></button>
              {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
            </div>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-5">
             <button onClick={() => setApiPlan('free')} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費</button>
             <button onClick={async () => { 
               const aistudio = (window as any).aistudio;
               if (aistudio) {
                 await aistudio.openSelectKey();
                 setApiPlan('paid');
                 localStorage.setItem('qs_hub_api_plan', 'paid');
               }
             }} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-md text-white' : 'text-slate-400'}`}>專業</button>
          </div>
          <div className="grid grid-cols-3 gap-1.5">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => exportToExcel('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => exportToExcel('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      {!isMobile && <div onMouseDown={startResizing} className="w-1 cursor-col-resize hover:bg-indigo-500 transition-colors z-[60]" />}

      {/* Main Content */}
      <main className="flex-1 flex flex-col bg-white w-full overflow-hidden relative">
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-4 md:px-6 bg-white shrink-0 shadow-sm z-30">
           <div className="flex items-center gap-2 overflow-hidden">
             {isMobile && (
               <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-slate-100 rounded-lg text-slate-500 shrink-0">
                 <i className="fa-solid fa-bars-staggered"></i>
               </button>
             )}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl overflow-x-auto no-scrollbar">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="進度" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
           <div className={`hidden sm:block px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider ${apiPlan === 'paid' ? 'bg-indigo-50 text-indigo-600 border border-indigo-100 shadow-sm' : 'bg-slate-100 text-slate-500 border border-slate-200'}`}>
              {apiPlan === 'paid' ? 'PRO MODE' : 'FREE MODE'}
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12 bg-[#fbfcfd] custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `Scan_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-lg p-8 md:p-16 border-2 border-dashed border-slate-200 rounded-[2.5rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center bg-white shadow-sm group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-transform"><i className="fa-solid fa-upload text-2xl"></i></div>
                <h3 className="text-lg md:text-xl font-bold text-slate-800">批量上傳 QS 資料</h3>
                <p className="text-slate-400 text-xs md:text-sm mt-2 max-w-xs mx-auto">選擇名片圖片，系統將自動進行 AI 辨識。</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-3xl mx-auto space-y-6">
               <h2 className="text-xl font-bold text-slate-800 border-b border-slate-100 pb-3">辨識任務 ({tasks.length})</h2>
               {tasks.length === 0 ? <p className="text-center py-20 text-slate-300 italic">無進行中任務</p> : (
                 <div className="bg-white rounded-2xl border border-slate-100 overflow-hidden shadow-sm">
                   {tasks.map(t => (
                     <div key={t.id} className="flex items-center justify-between p-4 border-b border-slate-50 last:border-0">
                        <span className="text-sm font-semibold text-slate-600 truncate flex-1 pr-4">{t.fileName}</span>
                        <div className="flex items-center gap-3 shrink-0">
                           {t.status === 'processing' && <span className="text-indigo-500 text-xs font-bold animate-pulse"><i className="fa-solid fa-spinner fa-spin mr-2"></i>處理中</span>}
                           {t.status === 'completed' && <span className="text-emerald-500 text-xs font-bold"><i className="fa-solid fa-check mr-2"></i>完成</span>}
                           {t.status === 'error' && <span className="text-red-500 text-xs font-bold"><i className="fa-solid fa-xmark mr-2"></i>出錯</span>}
                           {t.status === 'pending' && <span className="text-slate-300 text-xs font-bold">等待</span>}
                        </div>
                     </div>
                   ))}
                 </div>
               )}
            </div>
          ) : selectedCard ? (
            <div className="max-w-[1400px] mx-auto animate-in fade-in slide-in-from-bottom-4 duration-300">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-14">
                 {/* Image Area */}
                 <div className="lg:col-span-6">
                    <div className="lg:sticky lg:top-0 space-y-4 lg:space-y-8 flex flex-col items-center">
                      <div className="relative w-full group bg-white p-3 md:p-4 rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden ring-4 md:ring-8 ring-slate-50 transition-all flex items-center justify-center min-h-[250px] md:min-h-[400px]">
                        <img 
                          onClick={() => setIsImageModalOpen(true)}
                          src={selectedCard.imageUrl} 
                          style={{ transform: `rotate(${currentRotation}deg)` }} 
                          className="max-w-full max-h-[450px] lg:max-h-[600px] w-auto h-auto rounded-xl md:rounded-2xl shadow-sm cursor-zoom-in transition-transform duration-300"
                        />
                      </div>
                      <button onClick={handleManualRotate} className="w-12 h-12 md:w-14 md:h-14 bg-white/90 backdrop-blur shadow-2xl rounded-full text-slate-700 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center border border-slate-200 active:scale-90">
                        <i className="fa-solid fa-rotate-right text-lg md:text-xl"></i>
                      </button>
                      <div className="w-full p-6 md:p-8 bg-white rounded-[1.5rem] md:rounded-[2rem] border border-slate-100 italic text-slate-500 text-[10px] md:text-xs leading-relaxed shadow-sm">
                         <span className="font-black text-indigo-500 uppercase text-[9px] md:text-[10px] block mb-2 md:mb-3 tracking-widest flex items-center gap-2"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 理由</span>
                         "{selectedCard.reasoning}"
                      </div>
                    </div>
                 </div>

                 {/* Detail Area */}
                 <div className="lg:col-span-6 space-y-8 lg:space-y-12">
                    <div className="border-b border-slate-100 pb-6 lg:pb-10">
                       <p className="text-[10px] md:text-[11px] font-black text-slate-300 uppercase tracking-widest mb-1 lg:mb-2">QS 資料全文</p>
                       <h1 className="text-2xl md:text-4xl font-black text-slate-800 tracking-tight leading-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                       <div className="mt-4 lg:mt-5 flex items-center flex-wrap gap-3 lg:gap-5">
                          <p className="text-lg lg:text-xl font-bold text-indigo-500 leading-tight">{selectedCard.title}</p>
                          {selectedCard.translations?.title && (
                            <span className="text-[10px] lg:text-[12px] font-black text-indigo-500 bg-indigo-50 px-3 py-1 lg:px-4 lg:py-1.5 rounded-full border border-indigo-100 shadow-sm max-w-[200px] truncate">
                              [{selectedCard.translations.title}]
                            </span>
                          )}
                       </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 lg:gap-x-12 gap-y-8 lg:gap-y-12">
                       <DetailItem label="單位名稱" value={selectedCard.company} translation={selectedCard.translations?.company} fullWidth />
                       <DetailItem label="稱謂 (Prefix)" value={selectedCard.prefix} />
                       <DetailItem label="部門 (Department)" value={selectedCard.department} translation={selectedCard.translations?.department} />
                       <DetailItem label="名 (First Name)" value={selectedCard.firstName} />
                       <DetailItem label="姓 (Last Name)" value={selectedCard.lastName} />
                       <DetailItem label="Email" value={selectedCard.email} />
                       <DetailItem label="聯絡電話" value={selectedCard.phone || selectedCard.mobile} />
                       <DetailItem label="國家/地區" value={selectedCard.country} />
                       {selectedCard.category === 'employer' ? (
                          <DetailItem label="產業類型" value={selectedCard.industry} translation={selectedCard.translations?.industry} />
                       ) : (
                          <DetailItem label="學科領域" value={selectedCard.subject} translation={selectedCard.translations?.subject} />
                       )}
                    </div>
                 </div>
              </div>
            </div>
          ) : null}
        </div>
      </main>

      {/* Sidebar overlay for mobile */}
      {isMobile && isSidebarOpen && (
        <div className="fixed inset-0 bg-black/60 z-40 animate-in fade-in duration-300" onClick={() => setIsSidebarOpen(false)} />
      )}

      {errorMsg && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-4 animate-in bounce-in z-[100] max-w-[90vw]">
          <i className="fa-solid fa-circle-info text-indigo-400"></i>
          <span className="text-[10px] md:text-xs font-bold">{errorMsg}</span>
          <button onClick={() => setErrorMsg(null)} className="ml-2 opacity-50"><i className="fa-solid fa-xmark"></i></button>
        </div>
      )}
    </div>
  );
};

const QSField = ({ label, value, translation }: any) => (
  <div className="space-y-1.5">
    <label className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{label}</label>
    <div className="p-3 bg-white border border-slate-100 rounded-xl text-sm font-semibold text-slate-700 shadow-sm">
      {value || '---'}
      {translation && translation !== value && <div className="text-[10px] text-indigo-400 mt-1.5 font-bold">註解: {translation}</div>}
    </div>
  </div>
);

const DetailItem = ({ label, value, translation, fullWidth }: any) => {
  const isValidTranslation = translation && translation !== value && translation.length < 80;
  return (
    <div className={`space-y-2 lg:space-y-3 ${fullWidth ? 'sm:col-span-2' : ''}`}>
      <label className="text-[10px] lg:text-[11px] font-black text-slate-300 uppercase tracking-widest border-l-4 border-indigo-400 pl-3 leading-none h-3 inline-flex items-center">{label}</label>
      <div className="flex flex-wrap items-center gap-3 lg:gap-4 pt-1">
         <span className="text-base lg:text-lg font-bold text-slate-700 tracking-tight">{value || '---'}</span>
         {isValidTranslation && (
           <span title={translation} className="text-[10px] lg:text-[11px] font-black text-indigo-500 bg-indigo-50/80 px-2 lg:px-3 py-1 rounded-lg border border-indigo-100/50 shadow-sm max-w-[200px] overflow-hidden text-ellipsis whitespace-nowrap">
             {translation}
           </span>
         )}
      </div>
    </div>
  );
};

const CategoryTab = ({ color, label, count, onExport }: any) => (
  <button onClick={onExport} disabled={count === 0} className={`w-full bg-${color}-600 hover:bg-${color}-700 text-white p-2 rounded-xl text-[8px] md:text-[9px] font-black flex flex-col items-center gap-1 transition-all disabled:opacity-20 active:scale-95 shadow-md`}>
    <span className="truncate w-full">{label}</span>
    <span className="text-[10px] md:text-[12px] bg-black/10 px-2 py-0.5 rounded-md leading-none">{count}</span>
  </button>
);

const NavBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`px-3 md:px-5 py-2 md:py-2.5 rounded-lg text-[10px] md:text-xs font-bold transition-all flex items-center gap-1.5 md:gap-2 whitespace-nowrap shrink-0 ${active ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500 hover:text-slate-700'}`}>
