      {items.map(c => (
        <div key={c.id} onClick={() => onSelect(c.id)} className={`p-2 lg:p-3.5 rounded-xl cursor-pointer transition-all border ${activeId === c.id ? `bg-white shadow-xl border-${color}-400 ring-2 ring-${color}-400/10` : 'border-transparent hover:bg-slate-50 hover:border-slate-100'}`}>
          <p className={`text-[10px] lg:text-[11px] font-black truncate ${activeId === c.id ? `text-${color}-600` : 'text-slate-700'}`}>{c.firstName} {c.lastName}</p>
          <p className="text-[8px] lg:text-[9px] text-slate-400 font-bold truncate mt-1">{c.company}</p>
        </div>
      ))}
      {items.length === 0 && <div className="h-full flex items-center justify-center pt-10 text-[8px] md:text-[10px] font-bold text-slate-300 italic">無</div>}
