);

export default App;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 2);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) {
      reject(e);
    }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await initDB();
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    transaction.objectStore(STORE_NAME).put(card);
  } catch (e) {
    console.warn("Save to IndexedDB failed", e);
  }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await initDB();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();
      request.onsuccess = () => resolve(request.result || []);
      request.onerror = () => reject(request.error);
    });
  } catch (e) {
    console.warn("Read from IndexedDB failed", e);
    return [];
  }
};

const clearAllCardsFromDB = async () => {
  try {
    const db = await initDB();
    db.transaction(STORE_NAME, 'readwrite').objectStore(STORE_NAME).clear();
  } catch (e) {
    console.warn("Clear IndexedDB failed", e);
  }
};

type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotations, setManualRotations] = useState<Record<string, number>>({});
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync mobile state and body styles
  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 1024);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const startResizing = useCallback((e: React.MouseEvent) => {
    if (isMobile) return;
    e.preventDefault();
    setIsResizing(true);
  }, [isMobile]);

  const stopResizing = useCallback(() => setIsResizing(false), []);

  const resize = useCallback((e: MouseEvent) => {
    if (isResizing && !isMobile) {
      const newWidth = e.clientX;
      if (newWidth > 300 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, [isResizing, isMobile]);

  useEffect(() => {
    window.addEventListener('mousemove', resize);
    window.addEventListener('mouseup', stopResizing);
    return () => {
      window.removeEventListener('mousemove', resize);
      window.removeEventListener('mouseup', stopResizing);
    };
  }, [resize, stopResizing]);

  // Initial Data Load
  useEffect(() => {
    const init = async () => {
      try {
        const dbCards = await getAllCardsFromDB();
        if (dbCards.length > 0) {
          setCards(dbCards.sort((a, b) => b.scannedAt - a.scannedAt));
          setSelectedCardId(dbCards[0].id);
        }

        const aistudio = (window as any).aistudio;
        if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
          const hasKey = await aistudio.hasSelectedApiKey();
          const savedPlan = localStorage.getItem('qs_hub_api_plan') as ApiPlan;
          if (hasKey && savedPlan === 'paid') setApiPlan('paid');
        }
      } catch (e) { 
        console.error("Initialization error", e);
      }
    };
    init();
  }, []);

  const handleManualRotate = useCallback((e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedCardId) {
      setManualRotations(prev => ({
        ...prev,
        [selectedCardId]: ((prev[selectedCardId] || 0) + 90) % 360
      }));
    }
  }, [selectedCardId]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("檔案無法讀取");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      console.error(err);
      if (err.message?.includes("Requested entity was not found")) {
        setApiPlan('free');
        setErrorMsg("API Key 效期已過，請重新設定。");
      }
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (isProcessing) return;
    const nextTask = tasks.find(t => t.status === 'pending');
    if (nextTask) performTask(nextTask);
  }, [tasks, isProcessing]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files) return;
    const fileList = Array.from(files) as File[];
    const newTasks: ProcessingTask[] = fileList.map((f) => ({
      id: crypto.randomUUID(),
      fileName: f.name,
      status: 'pending',
      progress: 0,
      batchIndex: 1
    }));
    newTasks.forEach((t, i) => filesMap.current.set(t.id, fileList[i]));
    setTasks(prev => [...prev, ...newTasks]);
    setViewMode('tasks');
  };

  const exportToExcel = (category: 'employer' | 'academic' | 'staff') => {
    const filtered = cards.filter(c => c.category === category);
    if (filtered.length === 0) return;

    const dataToExport = filtered.map(c => {
      if (category === 'employer') {
        return {
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Position': c.title,
          'Industry': c.industry,
          'Company Name': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      } else {
        return {
          'Source': c.source || 'QS Hub Scanner',
          'Title': c.prefix,
          'First Name': c.firstName,
          'Last Name': c.lastName,
          'Job Title': c.title,
          'Department': c.department,
          'Institution': c.company,
          'Country or Territory': c.country,
          'Email': c.email,
          'Subject': c.subject,
          'Phone (Optional)': c.phone || c.mobile || ''
        };
      }
    });

    const worksheet = XLSX.utils.json_to_sheet(dataToExport);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'QS Data');
    XLSX.writeFile(workbook, `QS_Export_${category}.xlsx`);
  };

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => {
    if (!selectedCard) return 0;
    return (manualRotations[selectedCard.id] || 0) % 360;
  }, [selectedCard, manualRotations]);

  return (
    <div className={`fixed inset-0 flex overflow-hidden bg-[#f8fafc] text-slate-900 ${isResizing ? 'select-none cursor-col-resize' : ''}`}>
      {/* Lightbox Modal */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[1000] bg-slate-900/95 flex flex-col md:flex-row animate-in fade-in duration-200">
           <div className="flex-1 flex items-center justify-center p-4 relative overflow-hidden">
              <button onClick={handleManualRotate} className="absolute top-6 left-6 z-20 bg-white/10 hover:bg-white/20 text-white px-4 py-2 rounded-full border border-white/20 text-xs font-bold transition-all">
                <i className="fa-solid fa-rotate-right mr-2"></i>旋轉圖片
              </button>
              <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="max-w-full max-h-[65vh] md:max-h-[90vh] object-contain shadow-2xl rounded-lg transition-transform duration-300" />
           </div>
           <div className="w-full md:w-[420px] bg-white h-1/2 md:h-full flex flex-col shadow-2xl">
              <header className="p-5 border-b flex items-center justify-between">
                <h2 className="text-lg font-black">QS 資料核對</h2>
                <button onClick={() => setIsImageModalOpen(false)} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center hover:bg-red-50 text-slate-500 hover:text-red-500 transition-all"><i className="fa-solid fa-xmark"></i></button>
              </header>
              <div className="flex-1 overflow-y-auto p-5 space-y-5 custom-scrollbar">
                <QSField label="單位" value={selectedCard.company} translation={selectedCard.translations?.company} />
                <QSField label="職稱" value={selectedCard.title} translation={selectedCard.translations?.title} />
                <QSField label="姓名" value={`${selectedCard.firstName} ${selectedCard.lastName}`} />
                <QSField label="Email" value={selectedCard.email} />
              </div>
              <footer className="p-5 bg-slate-50 border-t">
                <button onClick={() => setIsImageModalOpen(false)} className="w-full bg-slate-800 text-white py-4 rounded-xl font-bold hover:bg-indigo-600 transition-all">完成核對</button>
              </footer>
           </div>
        </div>
      )}

      {/* Sidebar */}
      <aside 
        style={{ width: isMobile ? '100%' : `${sidebarWidth}px` }} 
        className={`fixed inset-0 z-50 lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r border-slate-200 shrink-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b bg-slate-50/50 shrink-0">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">QS HUB SCANNER</h2>
            <div className="flex items-center gap-2">
              <button onClick={() => { if(confirm("清除所有資料？")) { clearAllCardsFromDB(); setCards([]); setSelectedCardId(null); } }} className="text-slate-300 hover:text-red-500"><i className="fa-solid fa-trash-can text-xs"></i></button>
              {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
            </div>
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-5">
             <button onClick={() => setApiPlan('free')} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費</button>
             <button onClick={async () => { 
               const aistudio = (window as any).aistudio;
               if (aistudio) {
                 await aistudio.openSelectKey();
                 setApiPlan('paid');
                 localStorage.setItem('qs_hub_api_plan', 'paid');
               }
             }} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-all ${apiPlan === 'paid' ? 'bg-indigo-600 shadow-md text-white' : 'text-slate-400'}`}>專業</button>
          </div>
          <div className="grid grid-cols-3 gap-1.5">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => exportToExcel('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => exportToExcel('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      {!isMobile && <div onMouseDown={startResizing} className="w-1 cursor-col-resize hover:bg-indigo-500 transition-colors z-[60]" />}

      {/* Main Area */}
      <main className="flex-1 flex flex-col bg-white overflow-hidden relative">
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-4 md:px-6 shrink-0 bg-white z-20">
           <div className="flex items-center gap-3">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-slate-100 rounded-lg text-slate-500"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl overflow-x-auto no-scrollbar max-w-[calc(100vw-120px)]">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
           <div className={`hidden sm:block px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-wider ${apiPlan === 'paid' ? 'bg-indigo-50 text-indigo-600' : 'bg-slate-100 text-slate-500'}`}>
              {apiPlan === 'paid' ? 'PRO' : 'FREE'}
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 lg:p-12 bg-[#fcfdfe] custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full max-w-4xl mx-auto">
              <CameraScanner onCapture={async (b64) => { 
                const taskId = crypto.randomUUID();
                const res = await fetch(`data:image/jpeg;base64,${b64}`);
                filesMap.current.set(taskId, await res.blob());
                setTasks(prev => [...prev, { id: taskId, fileName: `Scan_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
                setViewMode('tasks');
              }} onClose={() => setViewMode('file')} />
            </div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center">
              <div className="w-full max-w-lg p-10 md:p-20 border-2 border-dashed border-slate-200 rounded-[2rem] hover:border-indigo-400 hover:bg-white transition-all cursor-pointer text-center bg-white shadow-sm group" onClick={() => fileInputRef.current?.click()}>
                <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mb-6 text-indigo-500 mx-auto group-hover:scale-110 transition-transform"><i className="fa-solid fa-cloud-arrow-up text-2xl"></i></div>
                <h3 className="text-xl font-bold text-slate-800">批量上傳 QS 資料</h3>
                <p className="text-slate-400 text-sm mt-3 max-w-xs mx-auto">選擇名片圖片後由 AI 自動進行結構化辨識。</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={handleFileUpload} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-3xl mx-auto space-y-6">
               <h2 className="text-xl font-bold text-slate-800 border-b pb-3">處理隊列 ({tasks.length})</h2>
               {tasks.length === 0 ? <p className="text-center py-20 text-slate-300 italic">無正在處理的任務</p> : (
                 <div className="bg-white rounded-2xl border overflow-hidden shadow-sm">
                   {tasks.map(t => (
                     <div key={t.id} className="flex items-center justify-between p-4 border-b last:border-0">
                        <span className="text-sm font-semibold text-slate-600 truncate flex-1 pr-4">{t.fileName}</span>
                        <div className="flex items-center gap-3 shrink-0">
                           {t.status === 'processing' && <span className="text-indigo-500 text-xs font-bold animate-pulse"><i className="fa-solid fa-spinner fa-spin mr-2"></i>辨識中</span>}
                           {t.status === 'completed' && <span className="text-emerald-500 text-xs font-bold"><i className="fa-solid fa-check mr-2"></i>完成</span>}
                           {t.status === 'error' && <span className="text-red-500 text-xs font-bold"><i className="fa-solid fa-triangle-exclamation mr-2"></i>錯誤</span>}
                           {t.status === 'pending' && <span className="text-slate-300 text-xs font-bold">待機</span>}
                        </div>
                     </div>
                   ))}
                 </div>
               )}
            </div>
          ) : selectedCard ? (
            <div className="max-w-[1400px] mx-auto animate-in fade-in slide-in-from-bottom-4 duration-300">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 lg:gap-14">
                 {/* Image Area */}
                 <div className="lg:col-span-6">
                    <div className="lg:sticky lg:top-0 space-y-6 flex flex-col items-center">
                      <div className="relative w-full bg-white p-3 md:p-5 rounded-[1.5rem] md:rounded-[2.5rem] shadow-xl border overflow-hidden ring-4 md:ring-8 ring-slate-50 flex items-center justify-center min-h-[250px] md:min-h-[400px]">
                        <img 
                          onClick={() => setIsImageModalOpen(true)}
                          src={selectedCard.imageUrl} 
                          style={{ transform: `rotate(${currentRotation}deg)` }} 
                          className="max-w-full max-h-[450px] lg:max-h-[600px] w-auto h-auto rounded-xl md:rounded-2xl cursor-zoom-in transition-transform duration-300"
                        />
                      </div>
                      <button onClick={handleManualRotate} className="w-12 h-12 md:w-14 md:h-14 bg-white shadow-lg rounded-full text-slate-700 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center border border-slate-100 active:scale-90">
                        <i className="fa-solid fa-rotate-right text-lg md:text-xl"></i>
                      </button>
                      <div className="w-full p-6 md:p-8 bg-white rounded-3xl border italic text-slate-500 text-[11px] md:text-xs leading-relaxed shadow-sm">
                         <span className="font-black text-indigo-500 uppercase text-[10px] block mb-3 tracking-widest flex items-center gap-2"><i className="fa-solid fa-wand-magic-sparkles"></i> AI 理由</span>
                         "{selectedCard.reasoning}"
                      </div>
                    </div>
                 </div>

                 {/* Detail Area */}
