type ViewMode = 'camera' | 'file' | 'detail' | 'tasks';
type ApiPlan = 'free' | 'paid';

export default App;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BusinessCardData, ProcessingTask } from './types';
import { extractCardInfo } from './services/geminiService';
import CameraScanner from './components/CameraScanner';
import * as XLSX from 'xlsx';

// --- IndexedDB Utility ---
const DB_NAME = 'QSHubDB_V2';
const STORE_NAME = 'cards';

const getDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    try {
      const request = indexedDB.open(DB_NAME, 2);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    } catch (e) { reject(e); }
  });
};

const saveCardToDB = async (card: BusinessCardData) => {
  try {
    const db = await getDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(card);
  } catch (e) { console.warn("DB Save Error", e); }
};

const getAllCardsFromDB = async (): Promise<BusinessCardData[]> => {
  try {
    const db = await getDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result || []);
      req.onerror = () => resolve([]);
    });
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [sidebarWidth, setSidebarWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const [isImageModalOpen, setIsImageModalOpen] = useState(false);
  const [manualRotations, setManualRotations] = useState<Record<string, number>>({});
  const [apiPlan, setApiPlan] = useState<ApiPlan>('free');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    // 初始化資料載入
    const loadInitialData = async () => {
      const savedCards = await getAllCardsFromDB();
      if (savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        setSelectedCardId(savedCards[0].id);
      }

      const aistudio = (window as any).aistudio;
      if (aistudio && typeof aistudio.hasSelectedApiKey === 'function') {
        try {
          const hasKey = await aistudio.hasSelectedApiKey();
          if (hasKey && localStorage.getItem('qs_hub_api_plan') === 'paid') {
            setApiPlan('paid');
          }
        } catch (e) { console.warn("API Key Check Failed", e); }
      }
    };

    loadInitialData();
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleManualRotate = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedCardId) {
      setManualRotations(prev => ({
        ...prev,
        [selectedCardId]: ((prev[selectedCardId] || 0) + 90) % 360
      }));
    }
  };

  // Fix: Added missing exportToExcel function to handle category exports using XLSX library
  const exportToExcel = useCallback((category: 'employer' | 'academic' | 'staff') => {
    const categoryCards = cards.filter(c => c.category === category);
    if (categoryCards.length === 0) return;

    const exportData = categoryCards.map(c => ({
      '稱謂 (Prefix)': c.prefix || '',
      '姓 (Last Name)': c.lastName || '',
      '名 (First Name)': c.firstName || '',
      '職稱 (Title)': c.title || '',
      '單位 (Company)': c.company || '',
      '部門 (Department)': c.department || '',
      '學科 (Subject)': c.subject || '',
      '產業 (Industry)': c.industry || '',
      '國家/地區 (Country)': c.country || '',
      'Email': c.email || '',
      '電話 (Phone)': c.phone || '',
      '手機 (Mobile)': c.mobile || '',
      '翻譯職稱': c.translations?.title || '',
      '翻譯單位': c.translations?.company || '',
      '分類 (Category)': c.category,
      '辨識日期': new Date(c.scannedAt).toLocaleString()
    }));

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "QS Data");
    XLSX.writeFile(workbook, `QS_Export_${category}_${new Date().toISOString().split('T')[0]}.xlsx`);
  }, [cards]);

  const performTask = async (task: ProcessingTask) => {
    if (isProcessing) return;
    setIsProcessing(true);
    setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'processing' } : t));

    try {
      const fileObj = filesMap.current.get(task.id);
      if (!fileObj) throw new Error("File not found");
      const reader = new FileReader();
      const base64Data = await new Promise<string>((resolve) => {
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(fileObj);
      });
      const info = await extractCardInfo(base64Data, fileObj.type || 'image/jpeg');
      const newCard: BusinessCardData = {
        id: crypto.randomUUID(),
        ...info,
        scannedAt: Date.now(),
        imageUrl: `data:${fileObj.type || 'image/jpeg'};base64,${base64Data}`,
      };
      await saveCardToDB(newCard);
      setCards(prev => [newCard, ...prev]);
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed' } : t));
      if (!selectedCardId) setSelectedCardId(newCard.id);
    } catch (err: any) {
      setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: err.message } : t));
    } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    if (!isProcessing) {
      const nextTask = tasks.find(t => t.status === 'pending');
      if (nextTask) performTask(nextTask);
    }
  }, [tasks, isProcessing]);

  const selectedCard = useMemo(() => cards.find(c => c.id === selectedCardId), [cards, selectedCardId]);
  const currentRotation = useMemo(() => selectedCard ? (manualRotations[selectedCard.id] || 0) % 360 : 0, [selectedCard, manualRotations]);

  return (
    <div className={`flex h-full w-full overflow-hidden bg-[#f8fafc] text-slate-900`}>
      {/* 燈箱 Modal */}
      {isImageModalOpen && selectedCard && (
        <div className="fixed inset-0 z-[1000] bg-slate-900/95 flex flex-col md:flex-row">
           <div className="flex-1 flex items-center justify-center p-4 relative">
              <button onClick={handleManualRotate} className="absolute top-6 left-6 z-20 bg-white/10 text-white px-4 py-2 rounded-full border border-white/20 text-xs font-bold">
                <i className="fa-solid fa-rotate-right mr-2"></i>旋轉
              </button>
              <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="max-w-full max-h-[60vh] md:max-h-[90vh] object-contain shadow-2xl transition-transform" />
           </div>
           <div className="w-full md:w-[400px] bg-white h-1/2 md:h-full flex flex-col">
              <header className="p-4 border-b flex items-center justify-between">
                <h2 className="font-black">資料核對</h2>
                <button onClick={() => setIsImageModalOpen(false)} className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center"><i className="fa-solid fa-xmark"></i></button>
              </header>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                <QSField label="單位" value={selectedCard.company} translation={selectedCard.translations?.company} />
                <QSField label="職稱" value={selectedCard.title} translation={selectedCard.translations?.title} />
                <QSField label="姓名" value={`${selectedCard.firstName} ${selectedCard.lastName}`} />
              </div>
              <footer className="p-4 border-t">
                <button onClick={() => setIsImageModalOpen(false)} className="w-full bg-slate-800 text-white py-3 rounded-xl font-bold">完成</button>
              </footer>
           </div>
        </div>
      )}

      {/* 側邊欄 (Mobile 響應式) */}
      <aside 
        style={{ width: isMobile ? '100%' : `${sidebarWidth}px` }} 
        className={`fixed inset-0 z-[100] lg:relative lg:translate-x-0 transition-transform duration-300 bg-white flex flex-col border-r border-slate-200 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
      >
        <div className="p-5 border-b bg-slate-50/50">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">QS HUB SCANNER</h2>
            {isMobile && <button onClick={() => setIsSidebarOpen(false)} className="text-slate-400 p-2"><i className="fa-solid fa-xmark"></i></button>}
          </div>
          <div className="bg-slate-200/50 p-1 rounded-xl flex mb-4">
             <button onClick={() => setApiPlan('free')} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg ${apiPlan === 'free' ? 'bg-white shadow-sm text-slate-700' : 'text-slate-400'}`}>免費</button>
             <button onClick={async () => { 
               const aistudio = (window as any).aistudio;
               if (aistudio) { await aistudio.openSelectKey(); setApiPlan('paid'); localStorage.setItem('qs_hub_api_plan', 'paid'); }
             }} className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg ${apiPlan === 'paid' ? 'bg-indigo-600 text-white' : 'text-slate-400'}`}>專業</button>
          </div>
          <div className="grid grid-cols-3 gap-1.5">
            <CategoryTab color="indigo" label="Employer" count={cards.filter(c=>c.category==='employer').length} onExport={() => exportToExcel('employer')} />
            <CategoryTab color="emerald" label="Academic" count={cards.filter(c=>c.category==='academic').length} onExport={() => exportToExcel('academic')} />
            <CategoryTab color="amber" label="Staff" count={cards.filter(c=>c.category==='staff').length} onExport={() => exportToExcel('staff')} />
          </div>
        </div>
        <div className="flex-1 flex overflow-hidden">
          <DataColumn title="Employer" color="indigo" items={cards.filter(c=>c.category==='employer')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Academic" color="emerald" items={cards.filter(c=>c.category==='academic')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
          <DataColumn title="Staff" color="amber" items={cards.filter(c=>c.category==='staff')} activeId={selectedCardId} onSelect={id => { setSelectedCardId(id); setViewMode('detail'); setIsSidebarOpen(false); }} />
        </div>
      </aside>

      {/* 主工作區 */}
      <main className="flex-1 flex flex-col min-w-0 bg-white relative">
        <header className="h-14 border-b border-slate-100 flex items-center justify-between px-4 shrink-0 bg-white">
           <div className="flex items-center gap-2 overflow-hidden">
             {isMobile && <button onClick={() => setIsSidebarOpen(true)} className="w-10 h-10 flex items-center justify-center bg-slate-100 rounded-lg text-slate-500 shrink-0"><i className="fa-solid fa-bars-staggered"></i></button>}
             <nav className="flex items-center bg-slate-100/80 p-1 rounded-xl overflow-x-auto no-scrollbar">
                <NavBtn icon="fa-camera" label="單張" active={viewMode === 'camera'} onClick={() => setViewMode('camera')} />
                <NavBtn icon="fa-folder-open" label="批量" active={viewMode === 'file'} onClick={() => setViewMode('file')} />
                <NavBtn icon="fa-list-check" label="任務" active={viewMode === 'tasks'} onClick={() => setViewMode('tasks')} />
                {selectedCard && <NavBtn icon="fa-address-card" label="詳情" active={viewMode === 'detail'} onClick={() => setViewMode('detail')} />}
             </nav>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {viewMode === 'camera' ? (
            <div className="h-full"><CameraScanner onCapture={async (b64) => { 
              const taskId = crypto.randomUUID();
              const res = await fetch(`data:image/jpeg;base64,${b64}`);
              filesMap.current.set(taskId, await res.blob());
              setTasks(prev => [...prev, { id: taskId, fileName: `Scan_${Date.now()}`, status: 'pending', progress: 0, batchIndex: 1 }]);
              setViewMode('tasks');
            }} onClose={() => setViewMode('file')} /></div>
          ) : viewMode === 'file' ? (
            <div className="h-full flex flex-col items-center justify-center text-center">
              <div className="w-full max-w-sm p-10 border-2 border-dashed border-slate-200 rounded-[2rem] bg-white shadow-sm cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                <i className="fa-solid fa-cloud-arrow-up text-3xl text-indigo-400 mb-4"></i>
                <h3 className="text-lg font-bold">上傳名片</h3>
                <p className="text-slate-400 text-xs mt-2">支援批次上傳圖片檔案</p>
                <input type="file" ref={fileInputRef} className="hidden" accept="image/*" multiple onChange={(e) => {
                  const files = e.target.files; if (!files) return;
                  // Fix: Explicitly type 'f' as 'File' to resolve "Property 'name' does not exist on type 'unknown'" and type mismatch with filesMap
                  const newTasks = Array.from(files).map((f: File) => {
                    const id = crypto.randomUUID();
                    filesMap.current.set(id, f);
                    return { id, fileName: f.name, status: 'pending' as any, progress: 0, batchIndex: 1 };
                  });
                  setTasks(prev => [...prev, ...newTasks]);
                  setViewMode('tasks');
                }} />
              </div>
            </div>
          ) : viewMode === 'tasks' ? (
            <div className="max-w-2xl mx-auto space-y-4">
              <h2 className="font-bold border-b pb-2">辨識隊列 ({tasks.length})</h2>
              {tasks.map(t => (
                <div key={t.id} className="p-3 bg-white border rounded-xl flex items-center justify-between text-xs">
                  <span className="truncate flex-1 font-semibold">{t.fileName}</span>
                  <span className={`font-bold ${t.status === 'completed' ? 'text-emerald-500' : t.status === 'error' ? 'text-red-500' : 'text-indigo-500'}`}>
                    {t.status === 'processing' ? '正在辨識...' : t.status === 'completed' ? '已完成' : t.status === 'error' ? '出錯' : '排隊中'}
                  </span>
                </div>
              ))}
            </div>
          ) : selectedCard ? (
            <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in duration-300">
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <div className="flex flex-col items-center gap-4">
                    <div className="w-full aspect-[1.6/1] bg-white p-3 rounded-2xl border shadow-sm flex items-center justify-center overflow-hidden">
                      <img src={selectedCard.imageUrl} style={{ transform: `rotate(${currentRotation}deg)` }} className="max-w-full max-h-full rounded-lg cursor-zoom-in" onClick={() => setIsImageModalOpen(true)} />
                    </div>
                    <button onClick={handleManualRotate} className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center"><i className="fa-solid fa-rotate-right"></i></button>
                  </div>
                  <div className="space-y-6">
                    <div className="border-b pb-4">
                      <h1 className="text-2xl font-black text-slate-800 tracking-tight">{[selectedCard.prefix, selectedCard.firstName, selectedCard.lastName].filter(Boolean).join(' ')}</h1>
                      <p className="text-indigo-500 font-bold mt-1">{selectedCard.title}</p>
                    </div>
                    <div className="grid grid-cols-2 gap-6">
                      <DetailItem label="單位" value={selectedCard.company} translation={selectedCard.translations?.company} />
                      <DetailItem label="Email" value={selectedCard.email} />
                      <DetailItem label="部門" value={selectedCard.department} />
                      <DetailItem label="地區" value={selectedCard.country} />
                    </div>
                  </div>
               </div>
            </div>
          ) : null}
        </div>
      </main>

      {isMobile && isSidebarOpen && <div className="fixed inset-0 bg-black/60 z-[90]" onClick={() => setIsSidebarOpen(false)} />}
    </div>
  );
};

